window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_012"]={"n":"林占梅","dyn":"清","poems":[{"t":"游剑潭寺","f":"五言律诗","c":["晚凉同散步，小径入花坪。","野草缘阶绿，岩松破壁生。","钟飘云外响，泉咽涧中声。","日暮归禅院，翛然俗虑清。"]},{"t":"师韫轩杂咏 其一","f":"七言绝句","c":["绿窗绣罢对敲棋，女伴机锋亦可儿。","回首见侬忙避去，不知侬立已多时。"]},{"t":"师韫轩杂咏 其二","f":"七言绝句","c":["擘笺窗下学抄书，葱指纤纤运管徐。","写罢泥郎评甲乙，簪花字格果何如。"]},{"t":"师韫轩杂咏 其三","f":"七言绝句","c":["生成慧性善传神，花卉翎毛总逼真。","毕竟带些幽媚态，新篁爱学管夫人。"]},{"t":"师韫轩杂咏 其四","f":"七言绝句","c":["荷亭竹榭共乘凉，贪睡嗤侬午梦长。","独自看书消永昼，碧纱橱内静焚香。"]},{"t":"师韫轩杂咏 其五","f":"七言绝句","c":["流苏五采玉鸦义，半掩罘罳静不哗。","揭起绣帏偷眼看，簟痕满颊印铅华。"]},{"t":"师韫轩杂咏 其六","f":"七言绝句","c":["银筝池上和琵琶，按曲归来日欲斜。","忙煞笼中绿鹦鹉，声声帘下唤烹茶。"]},{"t":"师韫轩杂咏 其七","f":"七言绝句","c":["香浥芳塘开白莲，摘来恰爱露华鲜。","胆瓶插满还添水，供在慈云大士前。"]},{"t":"师韫轩杂咏 其八","f":"七言绝句","c":["菱花照影镜新磨，晓向妆台点翠娥。","误得侍儿身后拜，一轮明月现姮娥。"]},{"t":"邀曾籋云先生偕诸同人涵镜轩纳凉，烹茶赏荷，分韵得「娇」字","f":"七言律诗","c":["半亩沦涟趣已饶，芙蕖更喜绽今朝。","如临宝镜凝妆靓，似浴温泉出水娇。","玉柄风生含麝馥，翠盘露滴爱珠摇。","热尘即此销除尽，暑气何缘到绮寮。"]},{"t":"新庄道中口号 其二","f":"七言律诗","c":["萦纡石径藓苔青，逼屋榕枝覆杳冥。","天外落霞齐远骛，竹间微雨乱流萤。","山排翠闼撑书幌，月印清波漾画屏。","一枕晚凉新睡觉，笛声断续起烟汀。"]},{"t":"新庄道中口号 其三","f":"七言律诗","c":["避暑年来几度过，琴书镇日自摩挲。","清溪浪碧垂杨合，远岸沙平野竹多。","坡老大瓢游岭海，志和箬笠老烟波。","绿阴满地襟如水，笑拍阑干发浩歌。"]},{"t":"新庄别馆月夜","f":"七言律诗","c":["竹篱近水两三家，一带芳塍稻未花。","远火江村星倒挂，平烟树幕雾横遮。","蛙声接浦跳萍闹，萤焰冲风入竹斜。","好是晚凉无个事，汲泉拾叶煮新茶。"]},{"t":"双溪晓行","f":"五言律诗","c":["宛转双溪路，茏葱芋粟纷。","深坑巢乱石，远树泊轻云。","屋尽穿岩构，泉多截竹分。","啸猿声不断，每向静中闻。"]},{"t":"诸同友人重游剑潭寺 其一","f":"七言律诗","c":["瞳瞳旭日映窗纱，觅胜携朋泛晓楂。","水上轻烟浮钓艇，溪干丛竹护渔家。","空潭倒浸青山影，怪石翻冲白浪花。","最好柳堤晴可望，数峰缺处见明霞。"]},{"t":"诸同友人重游剑潭寺 其二","f":"七言律诗","c":["振衣同憩古招提，陌柳苍苍一望迷。","石径风来松子脱，花阴昼静鸟声啼。","放光水族惊投剑，闻筶池龟同伺齐。","步到上方殊寂寞，竹间门掩老僧栖。"]},{"t":"宿芝兰庄","f":"五言律诗","c":["怪树悬崖秃，飞泉挂壁长。","墙低山瞰屋，帘浅月登床。","竹籁寂清梦，兰风飘晚香。","幽居何必广，即此是仙乡。"]},{"t":"关渡舟行即事","f":"七言律诗","c":["破晓波光一镜澄，瞳瞳旭日正东升。","篷窗露润襟如湿，帆席风微桨乍增。","吟咏恰邀知己友，跏趺长似坐禅僧。","枫林偶泊浑无事，閒看渔翁补旧罾。"]},{"t":"重游栖云顶，即景作画并题 其一","f":"七言绝句","c":["晴川历历树毵毵，游侣追随兴倍酣。","笑指旧时行乐地，绿阴深处小溪南。"]},{"t":"重游栖云顶，即景作画并题 其二","f":"七言绝句","c":["一幅云烟爪迹留，不堪回首忆前游。","晚霞影落长天外，画出秋光古渡头。"]},{"t":"月夜同杨雨峰芝兰访友","f":"七言律诗","c":["篷窗试茗当飞觞，银汉无云夜色凉。","明月满船人访戴，清箫一曲客携扬。","渡头犬吠知村近，水面荷齐得露香。","遥指榜人停泊处，竹桥以外是山庄。"]},{"t":"寄怀榕城陈连峰广文","f":"七言律诗","c":["每从海上望高嵩，十载无由诉别衷。","侠气干云敦旧雨，贤声贯耳播春风。","星因德聚同时出，楼比名高百尺雄。","翘首渊源深景仰，赏心何但企丝桐。"]},{"t":"苦旱","f":"七言律诗","c":["旱霓四布若流丹，处处惊云陇亩乾。","无石可鞭难致雨，有河皆涸不知滩。","村庄画地争田水，老少呼天结社坛。","但得一声雷起顿，土膏尺寸为论欢。"]},{"t":"老来娇","f":"五言古诗","c":["有菊东篱下，始遭凡菊娇。","露苞时矗矗，绽蕊尚寥寥。","他花开欲遍，弱蒂尚摇摇。","岂知此花好，植品特超超。","不轻逞颜色，时至始苗条。","芳房高吐萼，锦瓣密垂髫。","艳丽奔金粉，轻盈著绛绡。","牡丹差比态，粉本岂能描。","如人未遇时，交谪竞腾嚣。","及逢得志日，瓦砾亦琼瑶。","梁灏一学究，买臣一山樵。","晚成推大器，土壤忽云霄。","回头奋迹地，妇孺亦歌谣。","人生犹如此，何况物之翘。","春秋肯阅历，雨露相滋浇。","自然会腾达，华贵在一朝。","我欲锡佳名，奚以称孤标。","园丁草解事，呼曰「老来娇」。"]},{"t":"莲峰先生代购古琴并惠手书，赋诗志感","f":"七言律诗","c":["忽报榕城鸟使还，瑶琴、华翰喜双颁。","兰言满幅珠玑灿，桂轸横床锦绣斑。","白鹤朱霞频想像，暮云春树切追攀。","临风无限知音想，何但尘襟一切删。"]},{"t":"感怀","f":"七言绝句","c":["画眉旧事悲张敞，戏彩遗欢痛老莱。","况值寒霜沉月夜，一灯如豆梦新回。"]},{"t":"书感","f":"七言律诗","c":["钻纸纷纷笑冻蝇，年来兴趣冷于冰。","广交已觉迎人苦，习静翻招傲物称。","琴韵逸宜林下客，诗心苦似定中僧。","且将白眼青天望，俗论悠悠任爱憎。"]},{"t":"有劝予诗勿多为悲歌感慨，口占答之","f":"七言绝句","c":["平子讴吟愁易集，灵均词赋感偏多。","我生斯土非燕、赵，其奈情随笔下何。"]},{"t":"慈孝引","f":"五言古诗","c":["人生天地间，慈孝本皆同。","孝者少能尽，慈者多有终。","所以古今人，慈心过孝衷。","因思古孝子，姓氏岂冥濛。","舜帝与闵子，自古所推崇。","王祥孝其母，黄帝孝其翁。","孝者殊落落，慈者竟充充。","非可率尔行，天性出乎中。","慈心涧中水，孝心树杪风。","树风摇有息，涧水流无穷。","定评慈与孝，二语为至公。","是故慈母恩，罔极似苍穹。","哀哀我慈母，莫报劬劳功。"]},{"t":"冲寒由小径入霄里","f":"七言律诗","c":["官道才过小径连，严冬无雨亦森然。","新晴云脚如拖帛，积雪山头若盖毡。","风逆寒鸦难到树，途长羸马忍加鞭。","舆中镇日垂帘卧，闷极看书又几篇。"]},{"t":"霄里庄晓发","f":"五言律诗","c":["唱彻鸡声后，篮舆破晓驰。","霜高虫穴闭，木落鸟巢危。","冻日藏低树，寒烟羃远陂。","行来三五里，村舍始晨炊。"]},{"t":"悼瑟吟","f":"五言古诗","c":["弱冠嗜音乐，性即嗜峄阳。","音节虽未妙，独弹情悠扬。","瑶琴称雅乐，惟瑟可匹当。","龙门有雅制，音清韵自长。","好合时无间，承欢慰北堂。","和乐将女载，一旦坠牙床。","坠碎弦齐断，鸾胶续未遑。","西山斜日落，凉月照空房。","空房寒寂寞，无复奏潇湘。","岁久结习在，孤桐犹自将。","挥手聊解郁，未鼓先断肠。","一弹风飒飒，再鼓露苍苍。","飞雉悲朝日，啼鸟惊夜霜。","一弹再三叹，响殚指转僵。","指僵音节错，欲续曲茫茫。","推琴起太息，四顾徒徬徨。"]},{"t":"正月二十日启馆呈逊兰师，并示若村舍弟","f":"五言律诗","c":["少小须勤学，文章实可亲。","师严力不废，性定课方真。","绛帐丹铅重，青灯尺璧珍。","待看春试返，芹藻羡头巾。"]},{"t":"十五日郊迎朱丹园司马，途次口号 其一","f":"七言绝句","c":["晓起藤舆出竹城，芳原绿水涨春耕。","青旗未待田间劝，何处不闻布谷声。"]},{"t":"十五日郊迎朱丹园司马，途次口号 其二","f":"七言绝句","c":["饭罢乡村日始升，牧童三五发鬅鬙。","牛高人小骑难上，拣得斜坡垫脚登。"]},{"t":"地震歌","f":"七言古诗","c":["天朗气清日亭午，閒吟散食步廊庑。","耳根彷佛隐雷鸣，又似波涛风激怒。","涛声乍过心犹疑，忽诧栋梁能动移。","顷刻金甑相倾碎，霎时身体若笼筛。","厩马嘶蹶犬狂吠，智者猝然亦愚昧。","悲风惨惨日无光，霎尔晴空成昼晦。","扶老携幼出门走，忙忙真似丧家狗。","更有楼居最动摇，欲下不得心急焦。","心急势危肝胆碎，失足一堕魂难招。","蚁走热锅方寸乱，两脚圈豚绳索绊。","窘逼转愁门户狭，攀援不觉窗棂断。","如逢虎狼如触蠍，形神惝恍魂飞越。","偷眼视之但溟茫，满耳声闻唯窸窣。","千家万家齐屏息，大儿小儿多避匿。","少选声停地始平，相顾人人成土色。","地平踏稳相欣告，众口一时同喧噪。","老者无策少者疑，从此夜眠心不怡。","东南虽缺地无缝，岂有妖物簧鼓之。","自是乾坤气吞吐，世人那得知其故。","幸哉淡水尚安全，可怜嘉、彰成墟墓。","试问既震何重轻，消息茫茫归劫数。","长歌赋罢心转愁，惊魂未定笔亦柔。","此情回首不堪忆，此身犹自随沉浮。","安得长房缩地法，居吾乐土免烦忧。"]},{"t":"过隙溪村","f":"五言律诗","c":["觅胜过村西，清阴夹岸齐。","桥危新涨急，树暗野云迷。","倚竹鱼庄密，乘潮蟹■低。","苍茫看暮色，落日隔前溪。"]},{"t":"北村访曾籋云先生归途口号","f":"七言律诗","c":["先生家住翠云窝，往访归来踏软莎。","路出炊烟乌桕树，桥回流水鸭头波。","平畴鸦落随牛去，窄径人停让马过。","况值清和天气好，薰风处处送秧歌。"]},{"t":"与内兄黄伟山孝廉园中夜饮醉归","f":"五言律诗","c":["把盏怀同放，联吟月已低。","更深频剪烛，夜静远闻鸡。","笑我顽如石，怜君醉似泥。","相将归就寝，扶过竹楼西。"]},{"t":"东城感赋","f":"七言律诗","c":["扶童閒步上东城，凭眺危栏感慨生。","骨肉廿年悲聚散，林园十载话枯荣。","山从绿野平边起，水向青陂缺处鸣。","景物长存时事改，回头何所不关情。"]},{"t":"六月初七日午雨暴注，少刻即晴，偶得绝句四首 其一","f":"五言绝句","c":["电熌奔雷疾，沟流急水鸣。","晚风檐溜歇，满耳复蛙声。"]},{"t":"六月初七日午雨暴注，少刻即晴，偶得绝句四首 其二","f":"五言绝句","c":["猝水庭除满，莓苔漾若萍。","更看篱畔竹，郁郁入帘青。"]},{"t":"六月初七日午雨暴注，少刻即晴，偶得绝句四首 其三","f":"五言绝句","c":["雨沉斜径没，水退涨泥存。","一院洼坳处，纵横屐齿痕。"]},{"t":"六月初七日午雨暴注，少刻即晴，偶得绝句四首 其四","f":"五言绝句","c":["园林新霁后，一抹夕阳留。","无限青山色，都收竹外楼。"]},{"t":"寄怀内兄伟山孝廉","f":"七言律诗","c":["京华昔共鲤庭趋，廿载交真谊李、卢。","时誉足当真绣虎，父书能读即家驹。","多文莫道身非富，大智由来貌若愚。","未稔伯伦卮酒兴，沉酣得似往年无。"]},{"t":"偶成","f":"七言律诗","c":["抚琴馀兴事吟笺，岁序消磨邺架边。","海外求书如访友，梦中得句若逢仙。","举杯肯让青莲醉，拜石还如大米颠。","閒里更寻消遣法，笑拈偈语学参禅。"]},{"t":"伏后天气多爽，与籋云先生露坐中庭，随笔成十韵","f":"五言古诗","c":["夜色凉水如，中庭薤簟铺。","微风来短榻，皎月挂高梧。","树润因过雨，荷圆乍有珠。","名茶分玉盏，宝篆枭金炉。","地僻心常静，诗多兴未孤。","閒谈挥麈尾，联句戛冰壶。","竹影时浓淡，兰香和有无。","携琴弹落雁，倚枕听啼蛄。","蛙鼓回环奏，瓶笙断续呼。","况当幽境在，自免俗尘拘。"]},{"t":"閒吟奉籋云先生","f":"七言律诗","c":["岭表、闽中自各天，交因翰墨信前缘。","花间爱我琴三弄，月下欣君赋一篇。","共洗马肝评砚谱，曾焚鹊尾对香筵。","有时携手登临去，踏尽青山绿水边。"]},{"t":"梳头见白发一茎戏作","f":"五言律诗","c":["壮年三十出，华发一茎生。","揽镜仍韶景，逢人慰寿徵。","半斑虽尚未，拔白亦中惊。","独我知其故，多伤离别情。"]},{"t":"题郑芷亭仪部北郭园 其一","f":"七言律诗","c":["悬车藉此养閒身，大隐何须避市尘。","山水有情皆入画，园林无日不生春。","传经也有吟诗婢，载酒还多问字人。","书带君家原得种，更欣兰桂绕阶新。"]},{"t":"题郑芷亭仪部北郭园 其二","f":"七言律诗","c":["清泉怪石绕回廊，八角亭虚驾碧塘。","松菊宛同陶令宅，诗书重见郑公乡。","风来竹坞琴声远，月转花坪酒兴长。","更好伏时招避暑，清斋一枕水云凉。"]},{"t":"游土地坑即景","f":"五言古诗","c":["出郭西南境，嵚崎别辟奇。","篮舆呼仆舁，茶榼付童持。","正值秋晴日，欣逢气爽时。","山形牛角抱，石磴犬牙危。","圣迹千年著，灵区十笏宜。","焚香先礼佛，披草共寻碑。","风定归云懒，坑纡出水迟。","老榕蟠峭壁，修竹荫通逵。","海雾浮沉幻，岚光晓暮移。","泉清堪煮茗，地胜合题诗。","花底琴横榻，栏前酒满卮。","鸟声听上下，树影落参差。","曲径樵歌答，长林牧笛吹。","人乘斜照返，马趁晚凉驰。","谷口三叉路，桥头六尺篱。","翠笼僧寺柏，青飐酒家旗。","雉堞行行近，苍烟户户炊。","襟怀无限好，更约后游期。"]},{"t":"宿大坪庄，夜半风雨骤至，走笔率记","f":"七言古诗","c":["迢迢仆马西南出，行到山庄刚落日。","绕屋更无竹与松，满园惟有芋和栗。","缭垣独舍鲜邻居，上下数间皆斗室。","除尘解橐理明灯，始馀隙地堪容膝。","芦帘草阁壁泥涂，竹榻槿篱户蓬荜。","村中夜静绝更筹，床下秋深鸣蟋蟀。","频频转侧梦难成，惝恍中心如有失。","忽听阶前飞雨骤，重闻屋角迅雷疾。","狂涛汹涌势澎訇，万马争奔声怒叱。","排山倒海震撼来，四体摇摇心胆慄。","照户方惊熌电光，破窗更讶飓风䬆。","此时枕簟一齐冰，陋屋难将风窦窒。","拥衾不敢偶伸头，满屋昏昏黑如漆。","可怜旅舍本凄凉，那堪风雨增萧瑟。"]},{"t":"宿大坪庄","f":"五言古诗","c":["山村休息早，落日掩荆扉。","吠犬穿篱过，流萤绕砌飞。","林烟看羃䍥，野火辨依稀。","独坐欢情少，孤吟逸趣违。","月昏迷远树，露重湿单衣。","吩咐行厨设，朝晴蹋翠微。"]},{"t":"过隙溪庄","f":"七言绝句","c":["周遭水竹护山庄，小小柴门短短墙。","野色一鞭看不尽，晚风吹出豆花香。"]},{"t":"再游北郭园，戏柬郑荫堂孝廉","f":"七言绝句","c":["曲折林扃荔百株，青山楼外胜披图。","退閒异日重来此，一席君能借我无。"]},{"t":"同籋云先生园池夜步，即景分韵","f":"七言律诗","c":["秋斋寂坐无情趣，聊向小园同散步。","夜色朦胧薄雾漫，箫声断续凉风度。","池边萤误水中星，芦际花疑沙上鹭。","吟罢新诗漏欲终，半规斜月悬汀树。"]},{"t":"东篱有感","f":"七言律诗","c":["落尽垂杨与绿荷，东篱采菊几回过。","花饶晚节姿容淡，人到中年感慨多。","愁绪如丝纷束缚，雄心似铁渐销磨。","金萱凋落尤增痛，苦向江头痛逝波。"]},{"t":"秋夜留彭雅夫夜话","f":"七言律诗","c":["一轮明月柳梢头，唧唧虫声傍砌幽。","有客清谈同煮茗，谁家吹笛尚凭楼。","竹阴滴露萧斋夜，梧叶飘风小院秋。","漏鼓沉沉君莫去，纵非陈榻也须留。"]},{"t":"赠家子范明经","f":"七言律诗","c":["相逢一笑大瀛东，况复龙田谱序同。","慧业生从金粟影，神姿清比玉兰丛。","直倾三峡文波阔，横扫千人笔阵雄。","他日端门看缓辔，诗章早上御屏风。"]},{"t":"西园见山池有感，作示友人","f":"古风","c":["人生世上苦不足，愿大焉能偿所欲。","身才饱煖思艳妻，既得艳妻慕金玉。","天台四万八千丈，巨海茫茫路莫续。","洞庭三万六千顷，层云缈缈目难瞩。","妄想能教鬼魅乘，暗里牵人投桎梏。","何如园圃养吾身，息机汉阴无窘促。","亭外有山排闼青，栏前有水盈池绿。","池痕添夜雨，山光映朝旭。","春来上山游，暑至临池浴。","知足即此可行乐，翀霄何必慕鸿鹄。","不然纵移天台、洞庭到我前，难免得陇复望蜀。","我劝世上人，园圃勤锄斸。","切休纤芥苦劳心，有限精神自荼毒。","图大往往小亦亡，无路可行羝藩触。"]},{"t":"书叹四首 其一","f":"七言律诗","c":["阳乌虚掷叹如梭，冷煖年来遍历过。","谄笑夏蛙多病客，浮华春梦付村婆。","刀能绕指经锤鍊，镜到明心费濯磨。","须把翟公为炯戒，门前方免见张罗。"]},{"t":"书叹四首 其二","f":"七言律诗","c":["气数茫茫未可知，生平得失每猜疑。","功轻每愧邀恩重，娶早翻伤抱子迟。","岸柳易高先落叶，岩松难长后凋枝。","但看树木犹如此，造物何曾有所私。"]},{"t":"书叹四首 其三","f":"七言律诗","c":["雌黄轻肆祸之根，守口如瓶舌且扪。","雅量面甘师德唾，恃才命不祢衡存。","欲舒积懑唯长啸，纵有微词敢大言。","棒喝从兹知猛省，幽□日日闭柴门。"]},{"t":"书叹四首 其四","f":"七言律诗","c":["呼马呼牛任毁誉，但期无愧在閒居。","四愁平子吟堪拟，三乐荣公叹不如。","早岁凋残伤骨肉，中年陶写赖琴书。","读终常向幽篁里，一道清风百虑除。"]},{"t":"遇雨宿树杞林","f":"五言律诗","c":["满庭欣草木，一雨足郊原。","暮色林梢压，滩声枕上喧。","竹床疑水浸，茅屋似春温。","辗转过长夜，诗篇手自翻。"]},{"t":"与越客偶谈风土","f":"七言律诗","c":["海甸炎凉旦暮更，随时变态似人情。","鱼鳞云绉风将起，鸭卵天开雨乍晴。","木叶少从冬里落，禾苗每自腊中生。","一般地气分南北，南富槟榔北富橙。"]},{"t":"七星墩山村午后散步","f":"五言律诗","c":["缓步到林坰，前山入望青。","牛羊眠草岸，鹅鸭浴沙汀。","老树根为榻，秋萝蔓作亭。","晚风来更好，时带野花馨。"]},{"t":"薄暮狮头崖望官渡，叠前年韵","f":"七言律诗","c":["寒消潦水碧潭澄，百级高崖奋袂升。","远树忽明残照射，平沙乍隐晚潮增。","港吞口似贪婪吏，山烧头如受戒僧。","一带萧芦残苇里，又多无数打鱼罾。"]},{"t":"秋日游栖云岩，作即景画赠许荫庭明经并题","f":"七言绝句","c":["挂壁流泉匹练飞，白云深处叩禅扉。","斜阳一抹秋林晚，古径无人僧独归。"]},{"t":"初晴舟中口号","f":"五言律诗","c":["雨过黑云收，清溪长急流。","风高帆鼓腹，浪涌艇昂头。","谋利心恒淡，图名志未休。","何时沧海上，鼓棹向皇州。"]},{"t":"雨后过青藤峡口","f":"五言律诗","c":["亭午甘霖过，淋漓遍隰源。","奔流鸣急濑，湿鸟噪荒村。","石耸山撑骨，崖崩树露根。","浓云何处去，薄暮翠岩屯。"]},{"t":"偕友人游剑潭寺西岩晚泊","f":"七言律诗","c":["斜日西岩系钓舻，凉风瑟瑟动菰蒲。","岸痕犹湿潮初落，山色微黄草未枯。","古寺僧归闻犬吠，危桥叟过倩人扶。","篷窗指与朋侪道，一幅荆关小画图。"]},{"t":"剑潭晚步，憩庄家书屋","f":"五言律诗","c":["散步幽潭上，岚光夕更佳。","虬松钳堕石，骤水齧崩崖。","树绿门前绕，山青屋后排。","短篱三五掩，折曲入清斋。"]},{"t":"芝兰庄夜归","f":"五言律诗","c":["水阔天逾碧，林深月亦低。","流奔鱼■战，芦密蟹灯迷。","溪道直还曲，帆风东复西。","咿咿村树里，忽听唱晨鸡。"]},{"t":"官渡门两傍极似严子陵栖隐处","f":"七言绝句","c":["岸上几家还竹屋，溪边无数钓鱼舟。","俨然七里泷中过，两面青山夹水流。"]},{"t":"八里分港冒雨返棹","f":"七言律诗","c":["泉石云山到处留，片帆冷落海门秋。","潮穿峭壁多成眼，云罩高峰不露头。","十里烟波摇客棹，一天风雨送归舟。","浪游不及林居乐，好把新盟订白鸥。"]},{"t":"过中沥马上口号","f":"七言绝句","c":["马头簇簇拥征尘，自叹奔波历苦辛。","羡煞野翁閒逸甚，柴门拄杖看行人。"]},{"t":"痛悼","f":"七言律诗","c":["生死悠悠恨最长，魂难入梦慰衷肠。","丁兰刻木空追像，潘岳吟诗半悼亡。","读到「蓼莪」篇顿发，歌来「窈窕」句堪伤。","中宵枨触忧离起，又听征鸿唳夜霜。"]},{"t":"忆昔","f":"七言律诗","c":["忆昔髫龄上帝京，晓风残月趁行程。","南船周听关山曲，北马曾经鲁、卫城。","故友凋零伤往事，游衣检点痛馀生。","即今被体看针线，犹是当年密密成。"]},{"t":"独宿扈尾山庄梦亡室感作","f":"七言律诗","c":["纸窗飒飒觉风生，一穗明灯暗复明。","独夜凄凉真鬼境，空山寂寞少人声。","招魂不作蘅芜梦，营葬徒伤宿草情。","起坐支颐孤枕上，泪痕如水尚盈盈。"]},{"t":"秋雨夜宿圆山庄","f":"五言律诗","c":["夜气冷侵肤，愁怜独客孤。","灯光寒顿缩，人影淡如无。","燐火前林出，鸮声隔涧呼。","复闻窗外雨，凄绝滴檐梧。"]},{"t":"冲寒过杨梅村遇雨","f":"五言律诗","c":["薄暮过荒村，茅檐护竹垣。","人寒如鹭立，犬健作熊蹲。","老树风前舞，浓云岭上屯。","滑泥行不得，听雨倍消魂。"]},{"t":"答徐碧岩令弟荐秋茂才 其一","f":"七言绝句","c":["胸中万轴富邱坟，年少翩翩白练裙。","笑我头衔称太守，却无高榻愧留君。"]},{"t":"答徐碧岩令弟荐秋茂才 其二","f":"七言绝句","c":["珊瑚笔架旧家声，人自温醇学自精。","宝翰沸漓承辱赠，还将木李报投琼。"]},{"t":"七七苦雨行","f":"古风","c":["大造茫茫杳无际，水国春阴真成例。","今春气煖日光辉，天宇晶明覆海圻。","忽然一夜惊霹雳，惊蛰未到人悚惕。","俗传四十九日乌，此语翁媪验历历。","漫天匝地苦淋漓，其状若何一数之。","微如丝缕骤强弩，大过倾盆小漏卮。","日比卵黄壳遮隔，尾肖鳞甲片参差。","陌上百花皆落魄，堤前万柳尽颦眉。","不履著久前后折，油伞淋多骨肉离。","处处茅檐青笠盖，家家苔壁绿蓑披。","风似剪刀利何用，云如堆墨笨难移。","吾淡由来多阴雨，困人无过今春苦。","除却深居简出入，觅食细民畏若虎。","岂系娲皇炼未精，石塌天河注下倾。","估客货湿愁贸易，农夫种烂废〔耘〕耕。","有时搔首仰问天，天何言哉惟默默。","回思旱魃□为灾，穿墟伐冢搜之急。","即今甚雨正需之，千金燕市求不得。","转辗咨嗟叹奈何，世间真个苦人多。","夜来愁□滴欲碎，挑灯作此当悲歌。"]},{"t":"薄暮自近村归新庄精舍","f":"七言律诗","c":["閒来野老话桑麻，谈罢归时兴趣赊。","水足春田看叱犊，日平暮树听啼鸦。","连村修竹阴随步，一路芳荪绿到家。","自掩荆扉灯上后，拨炉重试雨前茶。"]},{"t":"白石村春日閒游","f":"七言律诗","c":["草堂昼永日迟迟，笠屐郊原倜傥时。","十亩嫩苗肥似韭，一川碎石白于脂。","独归田叟锄翻荷，对语村童犊倒骑。","行过桥南堤尽处，读书堂认柳丝丝。"]},{"t":"閒兴 其一","f":"七言律诗","c":["万轴牙签一亩居，嚣尘远隔爱吾庐。","煨茶为备醒时歠，聚墨因防兴到书。","画架彩笼歌巧鸟，青盆碧藻漾文鱼。","当前生意争春长，地窄何嫌趣有馀。"]},{"t":"閒兴 其二","f":"七言律诗","c":["不趋声势不沽名，笑口开时琢句成。","山有奇峰名始著，人非憨癖艺难精。","醉书张旭常濡发，妙画长康重点睛。","我亦痴怀耽雅博，夜深卷页尚纵横。"]},{"t":"閒兴 其三","f":"七言律诗","c":["啸傲閒身已十年，百花深处拥书眠。","琴心渐会中庸道，诗学难参上乘禅。","白眼衔杯茶当酒，青丝绕屋柳如烟。","藜床抱膝浑无事，重检蒙庄「内外篇」。"]},{"t":"閒兴 其四","f":"七言律诗","c":["绿阴由由幂窗纱，帘幕低垂静不哗。","事到从容胸有竹，文当酣畅笔生花。","焚香稚子精神肃，问字雏姬意态赊。","遣兴一时歌数曲，□将诗句谱琵琶。"]},{"t":"游芝兰庄竹林石屋诸胜","f":"古风","c":["夜泛剑潭水，晚过芝兰冈。","郊原多景色，岩壑任翱翔。","村连竹树人应雅，地产芝兰水亦香。","舍舟携友同登陆，一带幽居枕山麓。","土沃禾梁犬豕肥，水深溪渚鱼虾蓄。","和风麦陇昼鸣鸠，细雨烟郊春叱犊。","黄童白叟各怡然，相见依依民雍睦。","上有松峰樵径奇，绝顶千寻逼九嶷。","岭松蟠结树葱郁，山石荦确径嵚巇。","平生不自勤磨炼，跻胜无资力已疲。","双脚踏谢屐，两手拄张藜。","攀缘登林木，缓步踏云梯。","盘空竟达高峰上，拂开烟树到招提。","危立层巅同纵目，田园掌大牛疑羝。","仰面上观浮云近，俯身不视飞鸟低。","我居城郭如帷幔，那得名山长在玩。","登此始知大地宽，不觉望洋自嗟叹。","徘徊立久静无闻，万木荫森绝斧斤。","高声长啸答岩谷，四山落叶落纷纷。","下有竹林藏石室，夹径穿山尽此君。","临阶几榻生清冷，挂壁藤罗吐翠芬。","当年七子恣行乐，却无石室高论文。","披图每羡前人福，对此盘桓意倍欣。","回途几度行又止，归到村居口已□。","铺床拂石乐箕踞，下箸十千求兼味。","欢然一饱向黑甜，来朝复拟寻幽去。"]},{"t":"双溪观石窍泉，晚归灯下作示同游诸友 其一","f":"古风","c":["双溪一□更堪誇，徜徉徘徊意境赊。","流水声中山色好，绛桃灼灼艳于霞。","桃花迎我面，流水清我耳。","从此已觉武陵近，不探仙源安可止。","一重一掩趣无穷，㟏岈崱屴鬼神功。","两山交护如无缝，随径逶迤谷自通。","乍通幽谷名区见，郁郁高林绕芳甸。","凝眸四望接烟芜，花底时闻唤鹧鸪。","双溪左右分廉让，叠嶂高低展画图。","一花一木皆幽致，到此已无尘俗累。","溪边添个休休亭，可拟司空栖隐地。","此社从来我未经，钧天仿佛奏泠泠。"]},{"t":"双溪观石窍泉，晚归灯下作示同游诸友 其二","f":"古风","c":["寻声共觅登山路，断续横斜途错互。","荒蹊翠葛拂罗衣，曲磴苍苔印芒履。","两道灵源山中溢，瀑布喷从石窍出。","美味沁脾酌醁醽，清音漱石鸣琴瑟。","彻底照人清且鲜，千枝万派落畬田。","有人搆屋临幽澳，镇日高眠无剥啄。","泉流绕砌茗堪烹，松影当窗书可读。","隐逸能方郑子居，应接不暇山阴目。","雨过月朗空山静，榻上焦桐慰幽独。","我思就隐水云乡，结契烟霞意味长。","祗因未了显扬愿，尚有黄粱梦一场。","一场尘梦浑如寄，岂甘久作风尘吏。","他年琴鹤谷中来，耕读为家初心遂。","男婚女嫁向平年，桐帽棕鞋任游戏。","日暮高歌乘兴还，者番淤乐信难攀。","路人问我何乐此，我笑未答意自閒。","君不见桃花流水杳然去，别有天地非人间。"]},{"t":"游滴泉岩归饮佃家，醉后题壁","f":"七言律诗","c":["几家板屋自成村，乔木阴多绿叶繁。","入市人归儿候路，登山客至犬迎门。","盘飧味厚供园韭，社酒香浓接瓦盆。","醉后懵腾岩下石，却疑身在谢公墩。"]},{"t":"夜宿栖云岩","f":"五言律诗","c":["崱屴山门外，穿林一径分。","虫声春暖闹，竹露夜深闻。","水际沉孤月，松巅带片云。","禅堂清课早，香气遍氤氲。"]},{"t":"金瓜寮山庄偶成","f":"五言律诗","c":["层巇环幽僻，阴房苦寂寥。","石崇山径仄，李广野园饶。","偷果猿如贼，号林鸟类鸮。","瘴云飞作雨，过午辄萧萧。"]},{"t":"园楼偶兴","f":"七言律诗","c":["竹外斜阳映碧流，午前雨过绿阴稠。","花飞著网蛛惊攫，树影侵潭鸟误投。","万物静观多妙趣，半生守拙懒深谋。","曲栏倚遍天将晚，自放湘帘下小楼。"]},{"t":"雨后醉归，香山道中憩野人家","f":"七言绝句","c":["笋舆乘雨出郊扃，野叟迎人请暂停。","羡煞平畴无个事，鸦锄放处麦青青。"]},{"t":"园居早起","f":"五言律诗","c":["园居侵晓起，寂历似郊坰。","鱼跃池萍破，鸦翻竹露零。","宿云屯远岫，初日上东亭。","行过蔷薇架，花风拂面馨。"]},{"t":"「会心处不在远」，晋简文语也。余入西圃，有触而作 其一","f":"五言古诗","c":["春草借雨力，一雨生最易。","数日不窥园，蔓延无隙地。","茸茸遍阶除，当足难引避。"]},{"t":"「会心处不在远」，晋简文语也。余入西圃，有触而作 其二","f":"五言古诗","c":["小童荷锸来，亟亟命芟弃。","姑息勿如前，丛生任其炽。","势盛欲拔之，甃石胥受累。","窗前留不除，茂叔取生意。","虽存博爱心，终有滋蔓忌。","况夹蒺藜生，何可疏防备。","不忍剪伐严，将遂纵横志。","转瞬春雷鸣，如指已成臂。","庭变荆棘林，非种还为祟。","栽梅难发华，放鹤难展翅。","斩刈叹已迟，著体皆芒刺。","始知妇人仁，不可与成事。","姑息祸之媒，优柔害之使。","寄语弟侄行，书绅切牢记。","如疑未必然，是我曾亲试。"]},{"t":"「会心处不在远」，晋简文语也。余入西圃，有触而作 其三","f":"五言古诗","c":["种松几树低，种竹成林广。","松高岁数寸，一纪未盈丈。","何时成老龙，朝夕劳梦想。","却言绿筼筜，百竿抽芽上。","夜静解箨时，簌簌听幽响。","昨日才比肩，今朝已过颡。","凌云志气高，遥遥如立仗。","隔别三日间，刮目堪企仰。","回顾几株松，云霄与土壤。","同受雨露滋，其故难明朗。","忽然得元奥，理如指诸掌。","若问意如何，虚心故易长。","凡我为学人，此理真堪仿。"]},{"t":"仿上官竹庄「莆阳天马晴岚图」，自题山水横披 其一","f":"古风","c":["似水天心秋爽，如屏山上晴岚。","正值新凉气候，游人两两三三。"]},{"t":"仿上官竹庄「莆阳天马晴岚图」，自题山水横披 其二","f":"古风","c":["小阁半藏山坞，浮云长绕峰腰。","却喜潺湲流水，中通一道横桥。"]},{"t":"仿上官竹庄「莆阳天马晴岚图」，自题山水横披 其三","f":"古风","c":["苍苍极目烟树，遥遥远接汀沙。","濑际竹篱蟹舍，林间茅屋人家。"]},{"t":"仿上官竹庄「莆阳天马晴岚图」，自题山水横披 其四","f":"古风","c":["临水芳塍饶沃，连村老木萧疏。","此是莆阳天马，被人写入画图。"]},{"t":"题櫹榔木屏风","f":"七言律诗","c":["气味清香质亦优，罘罳何必缘沈求。","灵根土产同猫首，妙画天成比虎头。","射雀唐高应命中，闻风满奋自无忧。","一方保障安床侧，宝鼎丝桐趣共幽。"]},{"t":"学圃 其一","f":"七言律诗","c":["薙草诛茅地数弓，连町茅栗郁葱葱。","挽车劳勚徒思妇，作约殷勤每课童。","鸦嘴泥黏朝雨后，鸭头水挹晚塘中。","从来机事生机械，抱瓮犹存上古风。"]},{"t":"学圃 其二","f":"七言律诗","c":["闭门种菜当生涯，戴月锄云趣益赊。","方宅阴浓陶令柳，平畦绿蔓邵侯瓜。","引泉堤外培菰首，插棘篱边护笋芽。","不是西南城一角，客来错认作山家。"]},{"t":"池上夜坐","f":"五言古诗","c":["散发向荷池，轩窗欣洞启。","浮云净大虚，穴寥清似洗。","汲水自烹茶，芬馥过嘉醴。","一饭轻两腋，数杯畅四体。","小步出前庭，长吟凭树柢。","柳垂露满梢，波定月沉底。","快哉此幽居，目中无尘眛。","何必侈襟期，咨嗟肉生髀。","凡事能知足，愁颜翻破涕。","堪叹名利场，纷纷峦触抵。","未若白与陶，耽诗乐清堤。","复羡马少游，郡掾依祖补。","抱此高淡怀，俗人难测蠡。","我今未能行，我去终有徯。"]},{"t":"漫兴 其一","f":"七言律诗","c":["尘网虽繁意自宽，青箱白朴足寻观。","交情寄处驰名易，诗律严时觅句难。","落笔有神看兔鹘，长篇作势在波澜。","惭我钝过陈无已，一字推敲屡废餐。"]},{"t":"漫兴 其二","f":"七言律诗","c":["玲珑精舍绝纤埃，环堵琴书逸趣该。","姜诗忌多三酌醉，名花嫌少百弓栽。","身常安饱宁非福，志在林泉称不才。","疏懒竟成都散仆，野鸥见我莫惊猜。"]},{"t":"漫兴 其三","f":"七言律诗","c":["不病维摩俗虑蠲，绿杨深处地尤偏。","喜临逸少来禽帖，悲动香山鬻骆篇。","睡意渐生抛卷卧，闷怀难吐藉琴传。","碧波篆袅风切飔，玉轸重调抚七弦。"]},{"t":"漫兴 其四","f":"七言律诗","c":["饭馀聊息苦吟身，学罢熊经学鸟伸。","晴日半窗花影碎，凉阴一院蝉声频。","闭门但作仇书客，入座时为战茗人。","漫道悠悠过岁月，閒中随处见天真。"]},{"t":"偶述","f":"五言律诗","c":["搔首追前事，酸辛已备尝。","人情蝗食稻，世味鼠搬姜。","为问笙歌乐，何如笔砚良。","微吟休拥鼻，时觉墨花香。"]},{"t":"遣兴","f":"七言律诗","c":["棕鞋桐帽喜偷閒，强半生涯落寞间。","闭户无聊惟种菜，登楼有兴为看山。","云中仙鹤招难到，天外飞禽倦自还。","岁月蹉跎生感慨，检囊亲把旧诗删。"]},{"t":"薄暮香山道中","f":"五言律诗","c":["薄暮凉飙动，萧萧振角巾。","疲驴归路健，猛犬过村驯。","潦水痕初减，霜枫色渐新。","苍茫秋浦外，声落雁行频。"]},{"t":"村居即事","f":"七言律诗","c":["南阡北陌互交通，贫富虽殊乐趣同。","里鼓喧阗因社近，山歌杂沓觉年丰。","如云沃野秋观稼，叠浪平畴晚度风。","笑我疏慵游览惯，未能握算学王戎。"]},{"t":"夜秋山寺即事","f":"五言律诗","c":["共话欣秋爽，禅扃夜静时。","溪风催煮茗，松月瞰弹棋。","坐久流萤集，声高宿鸟移。","露华浓似水，冷气觉侵肌。"]},{"t":"中秋夜宴涵镜轩筵中作，并赠荫坡孝廉","f":"七言律诗","c":["彩云空际涌冰毬，客主情殷乐事优。","撤烛翘观千里色，张筵共赏一轮秋。","鸳鸯瓦碧蟾光耀，鹦鹉杯香桂影浮。","今夜广寒无限景，羡君曾向此中游。"]},{"t":"曲水岩访李山人不遇","f":"五言律诗","c":["曲水潆洄入，孤村窄萼栖。","绿萝牵老屋，碧藓净幽溪。","山断浮云续，林高落日低。","主人何处去，独鹤步桥西。"]},{"t":"登青潭岩顶题壁","f":"五言律诗","c":["共羡溪山好，逍遥似隔凡。","钟声敲落日，飞鸟趁归帆。","暮霭长林泊，秋光远渚衔。","精篮藏极顶，爽岭遍松杉。"]},{"t":"夜宿清水岩僧舍","f":"古风","c":["幽区秋色晚，日夕倍生凉。","地险山多石，林疏叶落霜。","寒泉分细濑，明月碎流光。","鹤梦危松稳，?声峭壁藏。","烟霞□道侣，钟磬答禅堂。","老衲元谈奥，沙弥夜课长。","烛销莲漏水，茶沸竹炉香。","饭罢同趺坐，蒲团睡味良。"]},{"t":"夜不成寐，作此自遣 其一","f":"七言律诗","c":["儿时游冶废陈编，樗栎材微黯自怜。","谋利无心云出岫，思亲有泪涧渚泉。","理难胜数徒憎命，事不如人敢怨天。","除却琴樽陶写外，得来灵药只酣眠。"]},{"t":"夜不成寐，作此自遣 其二","f":"七言律诗","c":["庭树更深薄雾笼，荧荧灯火小窗红。","书因烦燥温难熟，诗到穷愁写易工。","寂坐时闻鸡腷膊，孤琴迭倚槛西东。","无端壮岁干云气，并作离情感断蓬。"]},{"t":"夜卧有感","f":"七言律诗","c":["掠地垂帘合复开，残香一缕恋琴台。","阶前蟋蟀悲花落，槛外芭蕉报雨来。","凉夜易生秋士感，雄心未敢壮年灰。","妖氛频听延湖汉，戢乱谁为颇、牧材。"]},{"t":"与容谈山东道中事，忆旧作此","f":"七言律诗","c":["登车四顾总茫茫，铃铎声中见火光。","匝地风霜冲雁阵，漫天尘土过驴纲。","琵琶客路歌红袖，林木人家恼白杨。","行尽畿南二千里，衾中缩卧类摇床。"]},{"t":"同友人西城楼凭眺即事","f":"古风","c":["竹城西北地势平，田园参错续海坪。","凉秋九月风怒吼，黄沙滚滚海雾腾。","朝来气暖纤尘净，睇眄中天极辽夐。","群峰缥缈列画图，巨海澄浤涵明镜。","高楼凭眺兴欲狂，振衣疑蹑千仞岗。","大呼奚奴捧斗墨，露肘颠书十数行。","题罢馀情犹未已，朋辈之中有绝技。","龙团一饮润我喉，客吹羌笛我长讴。","法曲乍聆「梅花落」，名泉又报「鱼眼浮」。","但耽雅乐与香茗，何须佳酿共珍馐。","君不见赵嘏有句艳今古，长笛横吹倚画楼。","又不见卢仝作经细评骘，七碗风生百虑休。","清音美荈各痂嗜，骚人适意何知愁。","我非骚人多坎壈，生平十事九烦忧。","秋前约侣游榕省，遍海鲸鲵迭闻警。","况当海氛迭闻警，积闷萦胸劳引领。","空有低昂七尺躯，才劣终军敢请缨。","自从游兴动中来，意马心猿常驰骋。","今日登临怀抱开，高天迥地任徘徊。","归时笑傲闺中友，聊当乘风破浪回。"]},{"t":"九芎林庄晚归即景","f":"七言律诗","c":["人影西斜暮色微，萧条满目思依依。","漫空云作糊涂态，撼树风施跋扈威。","岭背林喧寒鹊噪，溪头水急晚潮归。","回途倍觉阴霾甚，山市家家昼掩扉。"]},{"t":"二坪道中遇大风","f":"五言律诗","c":["冲寒惟疾走，闭口似衔枚。","飞土扬天起，狂风捲地来。","雁行低复断，猿啸急尤哀。","小憩茅亭下，相看面欲灰。"]},{"t":"咸水港归途口号","f":"五言律诗","c":["乾坤俄顷幻，明晦霎时中。","日色当头没，涛声裂耳雄。","冻云凝一水，寒雨滞层空。","行客龙钟甚，迟迟似老翁。"]},{"t":"冒雨过隙溪庄","f":"五言律诗","c":["仆马行来急，冲寒过小溪。","酒家茅屋里，樵径竹桥西。","冻犬倚炉卧，昏鸦绕树啼。","风威狂似虎，捲起陌尘迷。"]},{"t":"残腊苦雨","f":"七言律诗","c":["急景萧条腊欲残，那堪阴雨复潸潸。","羁栖旅宦愁家远，负戴□氓恨力孱。","无计送穷凭鬼恋，有台避债任人讪。","自从水患成凶岁，菜色鹑衣满市阛。"]},{"t":"过凤山崎","f":"五言律诗","c":["下视遥村近，群峰似画屏。","野田春水白，山坞暮烟青。","倦鸟知休息，长松入杳冥。","修途行尚远，坐憩小邮亭。"]},{"t":"晓过青草湖村","f":"七言律诗","c":["舆中晓望破萧寥，极目荒塍未插苗。","白鸟数行飞习习，青溪一道去迢迢。","山含雨意沉岩树，水藉风威撼野桥。","待到晴明青可踏，□痕周地作裙腰。"]},{"t":"树杞林村即景","f":"古风","c":["一村风景倍翛然，杂遝峰峦断复连。","鸟趁白云齐度水，人随黄犊共耕烟。","山溪逼仄挤奇树，石嶝嵚?泻急泉。","安乐有窝谁卜筑，槿篱茅舍翠微间。"]},{"t":"双峰庄新晴晓望","f":"七言律诗","c":["幽居难得此山庄，傍石依岩谷缭墙。","左右峰尖双插耳，萦纡径曲九回肠。","高田架木通流水，广陌编茅护嫩秧。","又值新晴天乍晓，子规声里遍春光。"]},{"t":"双溪庄题壁 其一","f":"七言律诗","c":["负耒人惟学守雌，黄童白叟乐熙熙。","双湾水足平田沃，四壁峰高晓日迟。","石径行间花气馥，茅檐隐处柳阴垂。","此乡我若来为主，半业耕渔半赋诗。"]},{"t":"双溪庄题壁 其二","f":"七言律诗","c":["地迥嚣尘寂不闻，棕鞋随兴踏苔纹。","羊肠径曲逶迤远，燕尾流斜左右分。","绝壑林扉疑蓄雨，深山岩穴尽巢云。","竹床置向泉根上，六月何曾暑气薰。"]},{"t":"过内湖庄","f":"五言律诗","c":["平陇多栽稻，高园半种茶。","溪弯沙岸仄，径曲竹篱斜。","老屋栖深树，閒门掩落花。","地幽人境隔，耕读足生涯。"]},{"t":"内湖僧舍小憩","f":"五言律诗","c":["古寺隐蚕丛，逶迤曲径通。","风微钟懒送，水急碓勤舂。","老柏春华吐，重峦晚翠笼。","泉渚悬绝涧，百尺似飞虹。"]},{"t":"过内湖小村憩望","f":"七言律诗","c":["客行常喜此停车，村坞中藏四、五家。","挂壁绿萝牵补屋，环阶红槿织成笆。","溪云漠漠随流水，岸柳条条绾落花。","无限好山排万叠，当门似有画屏遮。"]},{"t":"游清潭内山","f":"七言律诗","c":["萝薜低垂纵步难，无边野趣饱游观。","山形盘曲疑无路，水势奔腾觉近滩。","短屋数椽门似窦，高堤几里树为栏。","此间幽奥堪肥遁，日拓疏窗对翠峦。"]},{"t":"过南港茶岩","f":"七言律诗","c":["墟落深藏乱树遮，悬崖绝壑势嵯岈。","惊人童稚蓬门立，款客盘飧野菜花。","牛角触墙成「八」字，马蹄去路辨三叉。","俨然身到崇安道，山北山南遍种茶。"]},{"t":"同友人迷途，夜宿山家，吟诗以记","f":"五言古诗","c":["乘兴探灵峦，山穷天已夕。","苍茫烟云合，行径渺无迹。","本非姓丁人，那得冲霄翮。","又非鹅笼生，家具口中积。","游侣三五辈，束手正无策。","忽闻犬吠声，知有隐者宅。","联襼相追寻，茅茨露岩隙。","举目共翘观，风景足幽僻。","门藉芦帘遮，屋有槿篱隔。","一扣幽扉开，主人称莫逆。","案上列琴书，窗前植松柏。","截竹架檐端，烹茶分泉脉。","留我抵足眠，藤床可安席。","自言栖岩阿，不类车尘迫。","安居数十年，优悠无恐嚇。","妄念永不生，心閒身乃适。","兴到读「黄庭」，饥来煮白石。","扫地静焚香，内和外安息。","颐养乐天真，奚烦求玉液。","不闻先达言，「光阴如过客」。","何必自羁鞿，此心为形役。","叹我落尘网，举步天地窄。","人耐幽寂难，我求不可获。","贱者虽自贱，南面不与易。","天明辞主人，恋恋怀难释。","临别订后期，重来觅欢怿。","指点山下途，所经如别辟。","回顾幽人居，巑岏皆峭壁。"]},{"t":"自题万壑松古琴歌","f":"楚辞体","c":["君不见灵光之殿能常峙，独立崔巍众翘企。","又不见显庆之辂能久存，任教戎马来播掀。","若非神物常护卫，石泐金寒久应敝。","兹有琴名「万壑松」，青莲佳句工形容。","质轻如纸坚如玉，漆光幻出云烟浓。","陆离不藉玳瑁饰，斑驳浑同苔藓封。","蛇腹已誇化工妙，牛毛又受断文重。","文士纷纷琴是抱，琴中别有商山皓。","三尺丝桐鬼神呵，数点梅花天地老。","荒唐何必说钧天，元音细按出冰弦。","断续隔林传远磬，琤琮漱石听鸣泉。","彝是商兮鼎是夏，太古之物岂徒然。","鸢飞鱼跃天机畅，馀音既歇心尤旷。","想见当时运斧功，饬材精庀诚哲匠。","嗟予嗜痂生海东，十年大索难遭逢。","坐上指南忽有客，不辞航海求真龙。","赵璧价昂非所惜，果然得此拟焦桐。","腹镌「至德」唐年号，邂逅如观千岁翁。","尤欣本为吾家物，「次崖」二字篆奇崛。","后因兵燹归登瀛，五叶珍藏谁敢乞。","我今一旦购得之，登山临水每携持。","凉月当空一再鼓，如对先生抱膝时。"]},{"t":"闻警","f":"七言绝句","c":["日日传闻警报频，风声鹤唳半疑真。","可怜萧散琴诗客，也作仓皇甲冑身。"]},{"t":"台、凤土匪滋事，闻警戒严","f":"七言律诗","c":["戎装日日上城巅，饷窘兵孱械未全。","披甲营徒张赤帜，买刀家尽卖乌犍。","人敲刁斗残更月，官括荒城富室钱。","如此年时如此况，乐输争奈奋空拳。"]},{"t":"书叹","f":"七言律诗","c":["寇起萑苻叹蔓延，即今海甸尽骚然。","征途处处生荆棘，战地家家废陌阡。","浪巨农曾空菽粟，兵多灶又起风烟。","堪嗟百里膏腴地，数载纷纷尽变迁。"]},{"t":"途间见分类难民痛述时事","f":"七言绝句","c":["吴、越分争火烛天，问渠何事竟茫然。","可怜乡社成焦土，囷极监门绘不全。"]},{"t":"香山暮归","f":"五言律诗","c":["荦确遍沙湾，匆匆薄暮还。","风腥知近海，日暗欲衔山。","策蹇粘泥滞，浮鸥踏浪閒。","遥瞻阛阓接，犹在莽苍间。"]},{"t":"感赋","f":"五言律诗","c":["抛琴将半载，废卷亦三旬。","势逼难通隐，时艰枉率真。","干戈生咫尺，乡社痛湮沦。","拨乱诚无术，劳劳愧此身。"]},{"t":"往各庄安辑马上口号","f":"七言律诗","c":["晓夜奔驰歇未能，几回马上自凌兢。","荒郊日落鸮啼树，野店宵深鼠瞰灯。","寂寞剧怜生趣减，传闻每痛死伤仍。","何时丑类都歼尽，玉蠋重调岁序登。"]},{"t":"夜宿斗案棚庄","f":"七言律诗","c":["狺狺吠犬惊人起，哑哑啼乌绕树重。","堠卒频敲穷巷柝，山魈乱撞破楼钟。","风行老屋寒泉吼，月暗空林宿务浓。","唤醒仆夫聊伴胆，天明神思尚憧憧。"]},{"t":"小寒后煖如三、四月间，作此志异","f":"古风","c":["谁信寒晖北陆行，羊裘葛帔日纷更。","只缘气煖花先发，岂为民贫地久晴。","人畏萑苻同虎穴，?喧窗户作雷声。","莫言世事沧桑甚，节序迁流也不明。"]},{"t":"将近新庄口号","f":"五言绝句","c":["遥望眼朦胧，非复旧闾里。","忽闻鸡犬声，前村藏雾里。"]},{"t":"乱后经红毛港有感","f":"五言古诗","c":["山径阴森极，寒侵鹤氅裘。","风摧林竞吼，石砌水横流。","袅獍何时殄，沧桑此日更。","运乖天心偪，心怯梦魂惊。","破屋鬼欺客，荒村民苦兵。","桃源如可觅，竞欲避秦行。","暴雨强于弩，元云拥作帱。","笋舆行荦确，狼狈益增愁。","日短易黄昏，萧萧万籁繁。","榛荆生沃壤，鸡犬寂荒村。","估客腰缠裘，征人踵接奔。","流离多失业，康济愧前言。"]},{"t":"红毛港晓发","f":"五言律诗","c":["竟夜梦难圆，晨星窥客舍。","仆夫眼瞢腾，轮鞅迟迟驾。","小犬嗥阶前，寒灯闪篱罅。","霜华冷似冰，小立茅檐下。"]},{"t":"书感 其一","f":"五言律诗","c":["严冬风雨急，恻恻自怜予。","骨肉雕残后，乡邻丧乱馀。","霜寒悲雁阵，路梗绝鱼书。","百感真交集，宵长气莫舒。"]},{"t":"书感 其二","f":"五言律诗","c":["海陬方遘乱，淮上久遭兵。","烽燧连天起，鸱鸮匝地横。","庙谟宁失策，臣力少乾城。","拔剑闻鸡舞，悲歌涕泪倾。"]},{"t":"乱后逢李霭云感作","f":"七言律诗","c":["世事纷纭听莫真，萧条旅舍遍生尘。","荒郊血渍燐光乱，破屋风号犬吠频。","寒逼残年同刺客，愁攻中夜似仇人。","朦胧欲入还乡梦，作恶鸡声闹隔邻。"]},{"t":"次曾籋云先生「听鼓水仙曲」原韵奉答","f":"七言律诗","c":["窥窗凉月夜沉沉，兀坐胡床为听琴。","曲奏「水仙」闻逸响，人来岛佛赏清音。","潘江、陆海誇君赋，白石清松契我心。","不是阳春投雅什，谁知绿绮用功深。"]},{"t":"题巢松道人小照","f":"七言绝句","c":["元都法箓叹森严，道观焚修苦劳役。","在天在地两俱难，松顶结巢是安宅。"]},{"t":"夏初以来，四境不靖，园中花事就芜。届残腊，始报安堵。爰修小园，招诸韵士雅集，各有佳作。予忝主位，乃强颜续成五排一首","f":"五言古诗","c":["鼙鼓声才歇，园林兴欲颠。","百忧宽此日，三揖进群贤。","圃晚犹存菊，池空已谢莲。","老梅争腊放，弱柳待春眠。","诗社供金佛，花瓢养水仙。","堂虚陈古器，几净列琼筵。","绿酿葡萄熟，红包橘柚鲜。","㽐㽑尝异果，潋滟挹流泉。","茶沸铜瓶火，香浮宝鼎烟。","音清琴互抚，景好韵同联。","剧饮应中圣，幽思定入禅。","囊收昌谷句，墨洒薛涛笺。","东阁吟堪继，西园宴并传。","云龙常契合，岁月任催迁。","豪气欣长夜，高谈达晓天。","酒阑灯灺后，馀趣尚悠然。"]},{"t":"过咸水港","f":"五言律诗","c":["寒威能刺骨，愁绪欲焚心。","海峤风刚劲，山陬雨浸淫。","草粘沙碛远，树冒瘴烟深。","日日征鞍上，无聊只苦吟。"]},{"t":"嵌顶庄冲寒晚归","f":"七言律诗","c":["历尽山隈复水隈，沿崖一径尚崔巍。","云腾海峤奔骄马，风撼林扃怒吼雷。","受冻皴颜如著酒，冲寒禁口若衔枚。","归时未暇行装卸，自拨红炉煖绿醅。"]},{"t":"癸丑岁暮苦苦行","f":"古风","c":["苦苦苦，频年苦，频年未有今年苦。","兵燹纷纷百事乖，道途梗塞财源杜。","公私逼窘年已残，借贷何从觅阿堵。","食指计千空两拳，巧妇难为无米釜。","扬威时有暴富儿，索债声高狂似虏。","嗟予历过而立年，那曾遭遇此凌侮。","点金无术避无台，良策惟有装聋瞽。","漫拟子云作解嘲，苦况笔笔从头数。","记自夏初遭阽危，玄冥为祟日淋漓。","霪霖无霁日，沮洳无乾时。","桑田变沧海，芦灰力莫支。","昆阳未战屋先毁，人畜漂没极遐迩。","死者无辜生无聊，谷价虽贱无人市。","如逢富弼能赈民，祸乱未形自可止。","复因台、凤贼猖狂，销患焉能先及此。","岂料凶徒藉此诱穷民，因饥夺食成群起。","一朝啸聚盈绿林，王道平平忽尔尔。","出没无常肆剽掠，如虎负嵎险足恃。","可怜玩敌难成功，未发先泄事危矣。","健卒群誇曳落河，登坛自诩将门子。","探穴思裹邓艾毡，渡河旋陷张方垒。","满胸锐气陡然平，风声鹤唳尽疑兵。","袅獍从兹益无忌，百里溪山日纵横。","亦知恶极难逃咎，思将分类避贼名。","讹言四起民摇动，漳、泉疆划斗祸成。","两造焚攻焰烛天，八人到处氓无廛。","我为池鱼祸并及，凡百如扫成云烟。","此时生命轻于纸，杀人食肉类屠豕。","控肝夸□肆强凶，馀骸枕藉烧无已。","烧无已，痛如何。","乃父空局蹐，乃祖徒媕娿。","掉头浑不顾，同室任操戈。","更有惨祸绝今古，伐幽毁骨伤天和。","鲜血既流荡阴里，枯骨空抛无定河。","岂忘拨乱缘饷匮，不药之病病难瘥。","小道皆荆棘，大道遍妖魔。","自夏徂秋行不得，「行不得也哥哥」。","向使有病须针砭，亦宜调剂加抚摩。","虽云养痈恐贻患，庸医躁进罪更苛。","加之喜功图利己，微风海上复生波。","只知高官厚禄雄豪快，其如万户千家咒詈多。","鄙夫畏贼如畏虎，血仅禦贼短资斧。","遂使滋蔓久难除，聚?成雷应跋扈。","即今财货齐匮艰，闾阎寂寂停商贾。","矧复天寒岁暮时，巨户财竭细民苦。","苦苦苦，频年苦，频年未有今年苦。"]},{"t":"元旦望阙 其一","f":"七言绝句","c":["北望神京叩祝遥，五云深处奏箫韶。","御炉香霭千官拥，鹄立通明侍早朝。"]},{"t":"元旦望阙 其二","f":"七言绝句","c":["星云纠缦日华明，舞踏雍容佩玉鸣。","草莽微臣无别愿，妖氛早息颂升平。"]},{"t":"病中感赋","f":"七言律诗","c":["愁病相兼剧可怜，奄奄命似一丝延。","求医难遇肱三折，虑事何曾眼一眠。","蜡视盘飧浓亦淡，海添更漏夜如年。","更闻蛮触争蜗角，搔首咨嗟只问天。"]},{"t":"偕王子明茂才登楼偶作","f":"七言律诗","c":["百尺飞楼石作梯，仲宣此日喜同跻。","龙门西向波涛壮，鳞瓦中分井里齐。","远树阴连公廨近，高峰势压女墙低。","正思铁笛凌空弄，忽听秧歌起野畦。"]},{"t":"出郊感赋","f":"七言律诗","c":["竹城城南草如绵，竹城城北柳如烟。","古坟游鬼自寒食，腥风掠点云连天。","庐舍前头尽巢穴，野哭千家肠欲绝。","山桃野杏为谁春，尽作哀鸿口中血。"]},{"t":"憩内湾庄家","f":"七言律诗","c":["习习轻风拂面和，柳阴堤外听村歌。","平畴土沃肥粳稻，曲沼泉温泛鸭鹅。","径熟童眠牛背稳，桑生妇采陌头多。","宛然耕织图中景，万叠峰峦似翠螺。"]},{"t":"忧时","f":"五言律诗","c":["烽烟催劫至，膏血烂于糜。","天步艰难日，人情恐惧时。","温裾悲莫绝，钱枕感频欹。","忧愤中宵起，排愁藉酒卮。"]},{"t":"郊行感事","f":"五言律诗","c":["到处戈矛起，幽居也隐忧。","山林多遁客，陇亩有閒牛。","税迫荒田纳，粮艰战士咻。","点金仙术短，一策莫能筹。"]},{"t":"阻雨香山港市楼漫兴","f":"七言律诗","c":["黑云翻雨倒天瓢，独上层楼感寂寥。","远树苍苍沙岸阔，孤帆隐隐海门遥。","射潮雨势钱王弩，入市风声伍子箫。","热血一腔何处洒，酒杯在手剑横腰。"]},{"t":"过郑氏小庄 其一","f":"七言绝句","c":["园花争媚陌花芳，小景烟霞趣亦长。","一道清幽门外水，中央丛竹是山庄。"]},{"t":"过郑氏小庄 其二","f":"七言绝句","c":["历历孤烟起远岑，蜂腰桥隐绿杨阴。","小亭坐久忘归去，不住清蝉头上吟。"]},{"t":"感怀 其一","f":"五言律诗","c":["两髀今生肉，功名事渐休。","流年才转眼，去日几回头。","性直多招谤，情深易惹愁。","鸡虫谁得失，一笑付浮沤。"]},{"t":"感怀 其二","f":"五言律诗","c":["生涯甘落寞，家计懒经营。","吟苦都缘癖，愁多每为情。","十年虚墨稼，万笏只书城。","枉负干云志，田园久息耕。"]},{"t":"官渡港暮望即景 其一","f":"五言律诗","c":["幽阒沙原里，渔家结屋栖。","潮平桥脚短，汐退港喉低。","牡蛎粘船腹，旋螺贴蟹脐。","一村风景胜，绿柳护长堤。"]},{"t":"官渡港暮望即景 其二","f":"五言律诗","c":["荡桨喧童稚，渔家乐趣生。","帆疏如网漏，船小类瓢轻。","岩树苏秋雨，溪霞熨晚晴。","行吟归故缓，落日扣柴荆。"]},{"t":"晓发后垄道中 其一","f":"五言律诗","c":["幽禽鸣竹杪，睍睆似流莺。","远岫云初动，前溪月尚明。","林疏知野旷，水落见沙平。","数里康庄道，篮舆快晓行。"]},{"t":"晓发后垄道中 其二","f":"五言律诗","c":["问渡向芦洲，天空景更幽。","霞光明似晓，露气湛如秋。","极浦双帆定，孤村一笛愁。","行看红日上，晴色满溪楼。"]},{"t":"乌眉崎遇雨","f":"五言律诗","c":["汗多衣褦襶，峻岭道崔嵬。","酷日蒸雷出，奔云挟雨来。","沟渠鸣急水，野径绝纤埃。","顷刻旋开霁，斜阳照路隈。"]},{"t":"奉命办理团练，冒暑赴郡感作","f":"七言律诗","c":["一片旌旗事远程，櫜鞬日日向南行。","迢迢远道征鞭急，赫赫炎空火伞擎。","移筏敢辞泸水热，登陴长望瘴烟平。","不因豺虎纷当道，盛夏何烦统甲兵。"]},{"t":"宿苑里村","f":"七言律诗","c":["狼籍残骸痛未收，荒凉满目起悲愁。","迷人旱魃巢墟墓，拜月妖狐顶髑髅。","黝黝荒林晴亦暝，萧萧衰草夏如秋。","夜深隔岸燐光闪，知是魂从旷野游。"]},{"t":"冒暑过房里村","f":"五言律诗","c":["触热长征去，劳劳暑气侵。","蜂窝民舍偪，鼠穴贼巢深。","张伞愁炎景，挥戈激壮心。","简书催就道，无暇憩松阴。"]},{"t":"途次西螺驿口号","f":"五言律诗","c":["镇日旅尘侵，沿溪复出林。","随行三尺剑，伴睡七弦琴。","瀹茗消尘虑，观书静道心。","笋舆虽逼仄，兴到亦高吟。"]},{"t":"薄暮次罗山野望","f":"七言律诗","c":["长征此去路无穷，漠漠征尘逐晚风。","一片孤城哀角外，千竿修竹夕阳中。","血腥战骨争饥犬，雨打荒营没乱蓬。","但愿牧民来召、杜，笙歌重见旧瀛东。"]},{"t":"过茅港尾庄","f":"七言律诗","c":["腥血吹风扑面凉，萧条何处觅村庄。","千堆白骨皆新冢，十里平沙是战场。","落日昏黄闻鬼哭，啼禽呜咽断人肠。","当年此地人居密，转眼荒凉倍可伤。"]},{"t":"暮次麻豆道中","f":"七言律诗","c":["暮云黯黯欲黄昏，纵辔狂随夕照奔。","仆马驰驱嗟远道，田园荒废剩空村。","林烟惨淡疑烽火，碛草模糊认血痕。","今夜不知何处宿，啼鸦绕树对消魂。"]},{"t":"赴郡苦热，得雨偶作","f":"古风","c":["酷暑风来亦为厄，暖风熛怒几烁石。","恶氛矧复逐征尘，白昼道傍鬼捉客。","叹我南行当其时，健夫十人九丧魄。","彻夜传呼巫与医，身心交瘁莫安席。","想见武侯渡泸时，精诚在抱消疠疫。","古今无数匡济才，许国御微敢自惜。","捧檄我亦奉命来，旅次焦劳热反剧。","欲逃乐土苦无从，救兵一夜来风伯。","大块噫气夹雷鸣，俄顷滂沱势漂麦。","此时消尽胸中愁，旱魃成群皆辟易。","自是天心协人意，遇难成祥由善积。","遥思七省临欃枪，杀人如麻地流赤。","吁嗟乎，安得王师如此雨，露布一朝传遐僻。"]},{"t":"呈台澎道徐树人廉访四首 其一","f":"七言律诗","c":["价留鸾掖有文章，此日旌旄镇海疆。","众望巍巍崇鲁殿，舆情历历数甘棠。","培才不惜金针度，选士频操玉尺量。","喜看公门桃李树，秋来并作桂花香。"]},{"t":"呈台澎道徐树人廉访四首 其二","f":"七言律诗","c":["黄初七子仰前基，廿载廉勤受特知。","讲学堂高施绛帐，宣威部肃拥朱旗。","人瞻北斗钦风度，我向龙门愧品题。","最羡联辉花萼贵，阿连并侍凤皇池。"]},{"t":"呈台澎道徐树人廉访四首 其三","f":"七言律诗","c":["辞章、经术两超然，海内闻风亦有年。","文信豚鱼韩子檄，恩赒粟麦范公船。","东南任重屏藩寄，教化功深礼乐宣。","愧我驽骀无报处，惟将椿树祝青天。"]},{"t":"呈台澎道徐树人廉访四首 其四","f":"七言律诗","c":["听讼堂闲可设罗，遂教僻壤遍弦歌。","良筹既殛螳当毂，善政曾闻虎渡河。","弼教以刑持己重，无心之德感人多。","滔滔世泽如沧海，会见庭槐百尺过。"]},{"t":"山阴余慎斋先生性长厚，幕游东瀛数十载，予师事之。别后至甲寅夏，闻复奉命抵郡。方拟趋谒，而先生已捐馆十日矣。呜呼。何一见之悭也。因挽以诗","f":"七言律诗","c":["函丈追倍已廿年，何期此日遽登仙。","身游莲幕公门久，家与兰亭胜地连。","金石交情能慎重，斗山学业叹精专。","望风犹想仪型在，触目遗容总怆然。"]},{"t":"送徐树人师内渡","f":"五言律诗","c":["甫许春风坐，谁知遽别离。","识韩空有愿，御李怅无期。","豸服威名著，鳣堂教化施。","受恩嗟未报，有泪洒临歧。"]},{"t":"奉答树人师复用送别 其一","f":"七言律诗","c":["平生遭际话辛酸，感遇如公意一宽。","不孝原知无后大，厚施惟愧报恩难。","育麟方妙青囊贮，舞凤书珍墨宝看。","最是关情同骨肉，此行洵不负瞻韩。"]},{"t":"奉答树人师复用送别 其二","f":"七言律诗","c":["箫鼓嗷嘈士庶喧，苦留无计共攀辕。","推袁志切门墙远，说项情殷奖誉繁。","未得黄金摹贾岛，聊思彩线绣平原。","乡愚此后空翘切，不复慈云护覆盆。"]},{"t":"赤嵌城野望","f":"五言律诗","c":["登城閒眺望，触目起离愁。","荒草迷行径，斜阳黯戍楼。","壮心磨盾鼻，归思指刀头。","沧海茫无际，谁乘破浪舟。"]},{"t":"过郡城北口号","f":"五言律诗","c":["日斜閒步屧，郭外偶经过。","废冢无翁仲，空山遍女萝。","牛羊看卧起，樵牧听讴歌。","故址模糊甚，神伤吊古何。"]},{"t":"开元寺吊古歌","f":"楚辞体","c":["君不见钱武肃王镇吴越，知命举家朝宋阙。","由来一国无二君，卧侧岂容鼾声发。","当年郑氏踞东瀛，建牙赐姓剧威名。","兵穷鹭屿雄心丧，战捷鲲身霸业成。","带甲称戈据穷岛，居然倔强比田横。","时方壮盛三十九，气冲牛斗辟鲲鲸。","定是天心厌祸乱，故蹙其年致太平。","喧传一夜将星坠，编氓僚吏齐倾泪。","嗟哉子经事豪奢，监国藩臣直儿戏。","无常出没继孙恩，徙民失业咸受累。","误将扼要托健儿，七府功成旋复弃。","金瓯多缺力难完，日游别墅强偷安。","传位克?差得主，善政能教百姓欢。","无端变起毒谋设，伏甲都堂地流血。","别妻、为奴两不容，砥柱中流遽摧折。","奇勋未廓唐庄基，惨祸复蹈荆州辙。","势成累卵复何言，主君懦弱贼臣尊。","严刑重敛疲民命，日望王师振覆盆。","果然圣祖动矜悯，王浚船从海上屯。","梅花一阵收澎岛，吼门势窘国轩奔。","乘桴尚欲友邦夺，衔璧难将祖业存。","随行那有却正畴，可怜无泪别山邱。","朝班幸执降王梃，锡爵仍叨归命侯。","卅载海氛从此息，雨泽均沾教化周。","即今绣陌连千里，礼乐文章遍海陬。","灵光寂莫成兰若，荒烟蔓草虫啾啾。","我来凭吊故宫过，扪碑剔藓费摩挲。","自古握符有真命，枉思撼树蚍蜉多。","英雄我羡虬髯客，太原一见辄投戈。","不然当时楚项籍，喑哑叱吒徒销磨。","举鼎之雄拔山力，神州赤县思包罗。","岂知自刎乌江曲，「虞兮、虞兮奈若何」。","劝君莫妄窥神器，一局棋终已烂柯。"]},{"t":"过谢氏废园","f":"七言绝句","c":["坏甃荒阶遍绿苔，修篁左右水潆洄。","玉钗珠履归何处，惟有山禽自去来。"]},{"t":"过郑东平王墓","f":"五言律诗","c":["一旅抗王师，东瀛首建基。","衣冠存故国，韬略慑东夷。","大海长鲸杳，荒坟石马欹。","云礽犹建节，圣代有恩施。"]},{"t":"题五妃墓","f":"五言律诗","c":["薇蕨悲歌后，罗巾染血痕。","五人同毕命，一死足酬恩。","入地鸳鸯队，生天杜宇魂。","可怜环佩冷，荒冢易黄昏。"]},{"t":"雨后游竹溪寺题壁","f":"七言律诗","c":["雨气含凉暑气微，小南门外叩僧扉。","携樽有约同消夏，听磬无言共息机。","竹影环阶青欲滴，苔痕上壁翠成围。","蒲团枯坐清尘虑，禅榻茶烟兴不违。"]},{"t":"嵌城东园小住","f":"七言律诗","c":["行行曲径经池北，隐隐名园指郭东。","篱角斜分邻竹绿，墙头高映野花红。","净锄蔓草培新笋，细引清泉灌晚菘。","我与子猷同好竹，入门宾主不曾通。"]},{"t":"赠海东山长黄小石比部","f":"七言律诗","c":["海内经师位望尊，登龙我亦仰君门。","亲人叔度波千顷，好客陈遵酒一樽。","谈剑气豪肝胆露，论诗律细性情存。","道傍倾盖交如故，知己由来胜感恩。"]},{"t":"书感","f":"七言律诗","c":["自知坦率性难除，肆口雌黄任毁誉。","心似桔槔频辗转，名非觱篥待吹嘘。","烦劳事业鲇升竹，辜负勋名鹤在车。","况道不同谋寡合，家园念切赋归欤。"]},{"t":"留别黄小石 其一","f":"七言绝句","c":["天上浮槎到赏音，班荆未久惜分襟。","心香一瓣长望汝，韩、孟交情深更深。"]},{"t":"留别黄小石 其二","f":"七言绝句","c":["谈元话古意尤同，无限精神别后通。","但得吟笺频惠我，十年已备碧纱笼。"]},{"t":"游漱石山人幽园，题壁即赠","f":"七言律诗","c":["镇日幽斋事啸吟，池前漱石映清阴。","苍松偃盖浑难画，白鹤登堂为听琴。","重叠图书张邺架，玲珑秘阁肖云林。","羡君独得岩栖趣，地僻尘音未易寻。"]},{"t":"罗山道中口号","f":"五言律诗","c":["倦鸟寻窠下，幽花隔树香。","晚风清暑气，客路绕愁肠。","马恋平芜绿，旗翻落日黄。","费公仙术短，坐叹道遥长。"]},{"t":"游大仙岩，复题寺壁","f":"七言律诗","c":["远望峰峦画本张，钟声迢递度禅堂。","一溪沙石晴波洁，半岭松杉午气凉。","云里僧归衣带湿，花间客过屐生香。","重来胜地酣凭眺，扫壁寻诗兴更狂。"]},{"t":"重晤丁鸣皋道人于大仙寺，作诗赠之","f":"七言律诗","c":["重晤辽东老令威，方瞳碧眼世间稀。","剑光出袖青蛇活，舄影翻空白鹤归。","閒理素琴调道性，静参秘箓悟元机。","遥知云履星冠客，即日丹成列紫薇。"]},{"t":"观水火穴纪事","f":"五言古诗","c":["闻说火山奇，共入火山去。","遥望白芙蓉，排列白云处。","廿里大仙岩，寄宿许小住。","俯视来时途，白云积如絮。","破晓乘篮舆，重觅火山路。","沿径诘曲行，四塞皆烟雾。","林外闻清钟，引向禅堂驻。","老僧瘦于猿，问答多妙悟。","引我观火穴，舍舆著芒屦。","崎岖历蚕丛，阴翳入深树。","攀萝数里馀，倏忽睹奇趣。","山头曲突如，火光烂飞炷。","其穴乃有六，穴烈燄竞吐。","中有清泉流，如瀑势奔注。","水火同一源，上炎下流溯。","有树奇不枯，去火甫两步。","青草环四傍，土色俨铁铸。","煮茗有异芳，饮之等甘澍。","对此共称奇，莫能明其故。","徘徊同忘归，不觉碧天暮。","纪异愧无才，即景诗聊赋。"]},{"t":"观瀑布泉二首 其一","f":"五言律诗","c":["绝磴扪萝上，奔泉擅异观。","长虹悬树杪，飞电落岩间。","常引千寻响，能生六月寒。","我来当盛夏，漱石听淙潺。"]},{"t":"观瀑布泉二首 其二","f":"五言律诗","c":["日丽全融雪，峰晴陡溜冰。","绛河波骤泻，白练色如凝。","绡岂鲛人织，梭疑龙女腾。","夜来临皓月，掩映倍清澄。"]},{"t":"游清水岩","f":"五言律诗","c":["绝壁攀萝上，岩高一磴通。","泉清烹苦茗，籁静抚焦桐。","访胜碑重抚，谈禅偈亦空。","山僧留话晚，归路月明中。"]},{"t":"宿清水岩题壁","f":"五言律诗","c":["野寺虽萧瑟，禅房结构精。","清泉流月出，疏磬逐云行。","地僻人踪断，松高鹤梦清。","何时脱尘网，居此息劳生。"]},{"t":"旅次大甲，夜醒口号","f":"五言律诗","c":["夜阑灯欲灭，四壁听喧阗。","黠鼠欺生客，荒鸡搅熟眠。","神烦尘梦杂，身倦欲心捐。","苦历礌硠道，今宵暂解鞯。"]},{"t":"后垄道中，小憩佃屋","f":"五言律诗","c":["归途风景暮，放步爱康庄。","落日红溪树，奔涛白野航。","酒旗招客兴，村笛断人肠。","待渡沙滩上，柴门已在望。"]},{"t":"后垄道中晓发作","f":"五言古诗","c":["旅夜不成眠，棂风吹败纸。","驾言向中途，町蹊随迤逦。","孤月憩岩巅，遥山潜雾里。","村鸡听三号，舆夫行五里。","曙色犹朦胧，道旁暂休止。","星影辨前林，滩声知近水。","临流掬月光，一漱凉侵齿。","欲下舆舆眠，吟情时复起。"]},{"t":"中港待渡","f":"五言律诗","c":["归途心怯远，晓夜厌奔驰。","马健兼程疾，潮平待渡迟。","遥山斜照薄，极浦晚霞移。","伫立垂杨下，摇鞭且赋诗。"]},{"t":"中港海濒，晓行遇雨","f":"五言律诗","c":["晓行多荦确，劳悴欲消魂。","远屿浓云没，长空旭日昏。","风高帆竞捷，雨急树齐喧。","旷野无从避，挥鞭指近村。"]},{"t":"盐水港归途","f":"五言律诗","c":["岭下多沙碛，弯环出水滨。","山云堆臃肿，海日散轮囷。","潮势狂吞艇，风威猛扑人。","舆窗时半启，放眼尽埃尘。"]},{"t":"论诗 其一","f":"七言绝句","c":["杜、苏以外岂无诗，界宋分唐祗自欺。","何必寻仙蓬岛上，性情相合即师之。"]},{"t":"论诗 其二","f":"七言绝句","c":["性灵、学问两宜兼，老妪能知律转严。","俗语都从书史出，一经镕铸值千缣。"]},{"t":"抚琴","f":"五言古诗","c":["夜静碧天净，万籁响沉沉。","捲帘伫明月，焚香调素琴。","泠泠七弦趣，山水始同心。","声希而味淡，俗耳无知音。","顾我独乐此，摩挲情更深。","一弹涤尘虑，再鼓发清吟。","朝游共一舆，夜眠共一衾。","晨夕永不离，生死盟诚忱。","兴至作「三弄」，趺石坐松林。","远招云间鹤，飘然落前岑。","携琴骑鹤去，天风荡虚襟。","汗漫九垓上，高踪谁能寻。"]},{"t":"园中木兰盛开，偶题一绝","f":"七言绝句","c":["绿叶扶疏势复斜，馣馣扑鼻气无涯。","遥看错道如来粟，满树黄金缀桂花。"]},{"t":"登香山港市楼晚归","f":"七言律诗","c":["楼外苍茫日欲倾，眼光惝恍耳交鸣。","沧溟云暗垂鹏翼，林樾风狂起虎声。","动地波涛攻断岸，漫天沙土障遥城。","匆匆仆马归来晚，垒块时消酒一罂。"]},{"t":"閒中感述","f":"七言律诗","c":["匿采韬光戒妄求，数年世事半牢愁。","读书有癖同元凯，生子何须肖仲谋。","天道微茫难遽信，国恩深重敢忘忧。","可怜日望干戈息，袜线才疏志未休。"]},{"t":"潜园主人歌","f":"古风","c":["试问潜园主，镇日何所为。","开轩纳远岫，种竹沿水湄。","清谈招乐广，大睡彷希夷。","睡足启双眸，窗外日迟迟。","息机常抱瓮，窥园不下帷。","跏趺抚古琴，偃仰吟小诗。","琴亦无定曲，心旷神自怡。","诗亦不拘体，意到笔自随。","龙涎爇一饼，雀舌歠一卮。","诗清为茶甘，琴妙觉香奇。","爱听竹窗雨，虚枕夜长欹。","爱玩溪楼月，洞箫时独吹。","冬爱暖阁卧，炉火温肌肢。","夏爱凉亭息，岩泉沁心脾。","偶动登山兴，谢屐凌嵚?。","偶□垂纶兴，严竿钓涟漪。","放鹤向北亭，观稼过东菑。","种梅入西园，荡桨泛南池。","曲折行三径，药圃连菊篱。","徘徊度双桥，莲岛续杨陂。","花舒当槛锦，柳扫缘岸丝。","眼阔胸次旷，心摹手足追。","谓我终日閒，韵事勤纷驰。","谓我终日忙，幽情乐莫支。","无事乃汲汲，有事竟嬉嬉。","有事、无事间，乐此不知疲。","为閒或为忙，问我我亦疑。","素希晋陶潜，北窗傲皇羲。","复拟唐李约，南山友鹿麋。","瞰破名利场，变诈祗自欺。","富得朱顿富，财聚名受訾。","贵得金张贵，位高身心危。","可知冥冥中，饮啄皆有司。","弄巧反为拙，谋盈反成亏。","古来知命者，乐道自恬熙。","我非昔贤比，襟怀不外斯。","嗟自弃养后，百念早灰之。","久凭邓禹笑，长抱毛义悲。","陈、张成仇怨，友道更难持。","已作伤弓鸟，择交当再思。","况系閒散人，性懒不受羁。","不若长掩关，悠悠学叔痴。","赀产永不营，荣辱总不知。","但求常安饱，此外听天施。","如问意云何，黄、老是吾师。"]},{"t":"赠宗朗如","f":"七言律诗","c":["平生同谱倾心少，此日论交见面迟。","琴不安弦希靖节，诗多入画肖王维。","门无俗事清閒惯，家有幽轩结构奇。","最羡一堂联棣萼，天伦乐事庆怡怡。"]},{"t":"勉五舍弟 其一","f":"七言律诗","c":["闭门思过过应删，惩创从兹力莫孱。","试轭稚驹难就范，入云倦鸟好知还。","能敦品节士方正，不读诗书仙亦顽。","如得宣尼真乐趣，曲肱饮水总怡颜。"]},{"t":"勉五舍弟 其二","f":"七言律诗","c":["功名自重求非妄，物欲能蠲害不侵。","见义须逾谋利意，待人勿用作文心。","立身曾子常三省，励志程公著四箴。","愧我绮年耽逸乐，诗书功望阿连深。"]},{"t":"霞漳江叟，朴实人也。冠式奇古，见之无不捧腹。笑赠以诗","f":"七言律诗","c":["欹侧巍峨态似慵，傍人为正始温恭。","方山制古宜狂客，高屋形奇称野踪。","仿似小冠分子夏，也因折角重林宗。","劝君勿赴重阳宴，醉后宜防落九龙。"]},{"t":"秋夜","f":"七言律诗","c":["袅袅茶烟飏小楼，楼头风月趣兼收。","寺钟韵远传清夜，坞竹声多报早秋。","半部诗篇宗白傅，一生心事肖黄州。","灯前重览南来信，绿绮频弹莫解忧。"]},{"t":"秋夜感旧作","f":"五言古诗","c":["秋风从西来，萧萧鸣纸阁。","百感忽然生，四顾叹离索。","忆我束发时，壮怀亦磊落。","买棹游江湖，走马入京洛。","文士交何、刘，侠客结朱、郭。","携酒上歌楼，挥金恣欢乐。","归来曾几时，家居渐落寞。","两鬓惊萧疏，一身苦羁缚。","已敝苏子貂，不舞羊公鹤。","负此七尺躯，铸就六州错。","安得请长缨，直扫单于幕。","射虎弯星弧，斩蛟拭霜锷。","已矣复何言，此想真虚作。","中夜起披衣，转觉鸡声恶。"]},{"t":"秋游隙溪，饮草亭作","f":"七言古诗","c":["修篁簇簇连沙汀，秋色苍然来草亭。","岩云片片忽飞去，送到群峰入眼青。","杖头幸有百钱挂，村沽饮共桑麻话。","曲涧清泉鸣似琴，平林冷淡秋如画。","樽前畅饮杯复杯，陶然诗兴酒边来。","吟秋步入菊畦去，寒香插鬓笑颜开。","人生自古贵行乐，明朝还把游山约。","数声牧笛催人归，前村已上如钩月。"]},{"t":"甲寅八月望儿生，赋答诸亲友","f":"五言律诗","c":["鬓毛将见白，惭愧乍悬弧。","半老篁添笋，中年鹤哺雏。","谬褒池上凤，敢比掌中珠。","欲种儿孙福，心田是远图。"]},{"t":"祉亭大姻翁以诗见贺，回叠原韵答谢","f":"五言律诗","c":["甲第钦前辈，诗书切后图。","窃符歌采苡，敢道梦怀珠。","公爱乌因屋，人传鹤引雏。","来年如再索，汤饼报悬弧。"]},{"t":"望儿弥月述怀，寄内兄黄伟山广文二首 其一","f":"七言律诗","c":["笨车羸马可为方，称善毋须去故乡。","但愿生儿愚且蠢，肯教对客瘦而狂。","心存济世谈何易，事不欺人意自良。","但免饥寒无逼郁，相承叶叶学刘苍。"]},{"t":"望儿弥月述怀，寄内兄黄伟山广文二首 其二","f":"七言律诗","c":["那堪远处在瀛东，满目妖氛道未通。","寂寂亲朋音信外，悠悠家国感怀中。","宦途此际多弹铗，世事何时早櫜弓。","但得升平如旧日，同游有约到华嵩。"]},{"t":"香山海堤晚归","f":"七言律诗","c":["沙鸥翔集渚兰芬，千尺长堤傍水坟。","来往帆乘潮汐挂，高低田赖陌阡分。","波平落日徐沉海，风定孤烟直入云。","缭绕归途天渐晚，铿鲸百八已遥闻。"]},{"t":"闻警","f":"五言律诗","c":["夜上高楼望，欃枪彻夜明。","无才悲乱世，遭劫痛编氓。","武略筹边重，文章报国轻。","连朝闻警报，投笔欲谈兵。"]},{"t":"洋盗窃据鸡笼汛，闻警感赋","f":"七言律诗","c":["恶浪翻空毒雾浮，孽蛟营窟蜃嘘楼。","连天烽燧惊风鹤，入夜欃枪犯斗牛。","义旅同心齐结垒，奇兵扼吭孰焚舟。","何时横海来飞将，极目沧溟起暮愁。"]},{"t":"秋思","f":"七言绝句","c":["秋英开后已无花，征战频年怅海涯。","独对西风起愁思，孤城落日又鸣笳。"]},{"t":"高楼秋望感赋","f":"七言律诗","c":["海门雨过远天清，万类都从眼底呈。","秋水盈盈回岛屿，晴沙漠漠下鵁鶄。","东来边信师将老，北望中原寇未平。","独凭危楼惆怅久，日斜鼓角又悲声。"]},{"t":"金门溪上晚归，触怀口号","f":"七言律诗","c":["西风凛凛送悲笳，极目寒云磴道遮。","柳外夕阳红漾水，渡头衰草白沉沙。","恋驹羸马归蹄健，失侣孤鸿倦翼斜。","对此苍茫生百感，终天抱恨痛无涯。"]},{"t":"因公自后垄归，行高崖上，感怀口号","f":"七言律诗","c":["遥遥天水渺茫间，长啸登临意觉閒。","世事无常如白浪，交情不改只青山。","烽烟日炽频闻警，原野秋清独往还。","每叹涛斜军误举，匡时无术反投艰。"]},{"t":"登内湾岩","f":"七言律诗","c":["百尺危楼峭壁悬，元龙那有此天然。","迎眸山色无今古，悦耳泉声有管弦。","野鹭行行投晚浦，丛篁历历数平川。","可怜大道皆荆棘，胜境睽违已廿年。"]},{"t":"香山口防堵作 其一","f":"七言律诗","c":["警报纷传乱未平，戒严此地设防兵。","鲸鲵跋扈狂翻浪，鹅鹳成军密结营。","一片旌旗摇月色，五更刁斗答涛声。","书生小试筹边策，不负雄心是请缨。"]},{"t":"香山口防堵作 其二","f":"七言律诗","c":["报国生平矢效忠，毛锥一掷便从戎。","世无俞、戚谁筹策，贼是孙、卢易建功。","壮志欲除蛟虎害，近灾莫谓马牛风。","海门潮急欃枪闪，剑气冲霄已化虹。"]},{"t":"鸡笼事平撤防，喜赋","f":"七言律诗","c":["蛟害欣闻仗剑除，喜看寰海镜清如。","孤军扼险当关虎，小丑跳梁咏釜鱼。","兵气全销吟望惬，饶歌高唱凯旋徐。","旌旗焕彩鞭丝软，整策花骢返草庐。"]},{"t":"秋望感怀 其一","f":"五言律诗","c":["干戈愁满地，怅怅欲何之。","天步艰难日，民生困厄时。","笙歌声已歇，鼓角听尤悲。","小立河桥上，斜阳照大旗。"]},{"t":"秋望感怀 其二","f":"五言律诗","c":["城南与城北，满目景苍凉。","村舍焚馀废，田园战后荒。","戒严多斥堠，伏衅惧萧墙。","不忍谈时事，西风易断肠。"]},{"t":"秋夜书怀 其一","f":"七言律诗","c":["空斋寂坐感牢骚，一片秋声起怒涛。","大海鱼龙方叫啸，中原鸿雁更哀嗷。","四城杀气传金柝，万里雄心付宝刀。","闻道神京呼癸切，挽刍无计首空搔。"]},{"t":"秋夜书怀 其二","f":"七言律诗","c":["书生白面亦谈兵，杀贼无人孰请缨。","忧国何须论在位，轻财未必尽沽名。","剑锋未试光腾啸，棋劫难消尚战争。","寄语运筹帷幄者，好须努力答升平。"]},{"t":"咏三貂岭","f":"七言律诗","c":["叠壑重岩百状呈，淡、兰于此判疆城。","山深路自云中出，岭峻人从树杪行。","夹道花从风里馥，悬空水带石头鸣。","嵯峨几欲登天似，浓霭还多扑面生。"]},{"t":"率练丁自中港还，马上口号","f":"五言律诗","c":["沙平衰草没，按辔路迢迢。","地旷容盘马，霜高好射雕。","弓声风力劲，鞭影日光摇。","小队鸣刁斗，雄心压海潮。"]},{"t":"寒夜楼前对月","f":"七言古诗","c":["月华如水中庭洁，寒风扫面肤欲裂。","危楼立久悄无言，绕树啼乌听悲切。","此时却忆黄叔度，广文先生寒更绝。","体孱已肖卫玠形，病亟复呕周瑜血。","可怜酒债负寻常，贫病交侵愁郁结。","愧我年来遭轗轲，范舟难补曼卿缺。","那堪屡接阿连书，已知委倾将摧折。","呼癸频频似燃眉，笔墨惨淡如呜咽。","与君至戚同李、卢，重洋遥阻肠空热。","此际遥知馆已捐，哭望天涯奠空设。","翘首寒空洒泪多，凉月侵人比冰雪。"]},{"t":"冬杪忽闻内兄伟山广文讣音，不觉五中如裂，泪沾襟袂。感今忆昔，以歌当哭","f":"五言古诗","c":["苍天曷有极，悠悠恨莫平。","年残家计窘，又当痛内兄。","内兄在榕省，广文官独冷。","半世历穷途，壮年当逆境。","孀妇赖以全，德门赖以整。","弱弟躬提携，慈亲勤定省。","苦志长下帷，乡荐幸早领。","藉此开亲颜，饱煖犹难永。","我谊忝葭莩，与粟常五秉。","得此为西江，一饱无奢请。","羡君真血性，孝友复温醇。","喜怒不形色，毁谤不沾唇。","能文惊笔阵，饮酒见天真。","因饮生议议，可叹少完人。","荷锸方刘伶，投辖类陈遵。","三百六十日，狼籍污车茵。","小饮能养性，大饮定伤身。","嗜痂已成癖，戒语徒书绅。","粉白与黛绿，妍媸无别甄。","每值如泥时，醉眼睨横陈。","旦旦双斧伐，枯树难复春。","相别始六载，远隔沧海滨。","我家被灾后，二年绝指菌。","欲援无馀力，惆怅乃伤神。","近来多笔札，觉非君所亲。","识为三弟书，句句是吟呻。","中皆诀别言，辞简意切要。","家贫事事难，儿稚弟犹少。","与我隔重洋，两心谅相照。","都此悽怆辞，不觉涕倾掉。","缅忆弱冠时，随侍居京师。","我亦从负笈，东床坦腹嬉。","我少也落拓，边幅不修治。","每至颠沛际，辄赖君扶持。","比予归海上，迢迢送不辞。","解装未阅月，一病几垂危。","幸得逢卢、扁，半载始展眉。","回京拜膝下，相见喜复悲。","椿萱能承顺，侍奉无差池。","前年琴断弦，是岁失填篪。","严君忽弃养，阖家困莫支。","况复家万里，廿口无归期。","尚幸贤乔梓，美誉久飙驰。","宗有名公在，倡义首捐赀。","集腋充囊橐，舆榇始有资。","死生关情处，尽入人心脾。","阮籍悲穷途，杨朱哭路歧。","况君恂恂者，赖公免流离。","奉母及幼弱，跋涉相追随。","教弟更成立，学行无瑕疵。","咸谓可安享，食报固其宜。","岂意天难测，理者不可推。","老母遽终堂，弟媳丧在兹。","苜蓿一散员，俸薄官似橘。","加之数年来，茑萝共萧瑟。","自赡犹未能，何暇相周恤。","稚小口嗷嗷，待哺纷绕膝。","窀穸并婚姻，更仆数难悉。","苦况百端凌，沉痾一朝剧。","伏枕嘱遗言，字下血随笔。","其言犹哀惨，泣读不忍毕。","嗟予自断弦，伉俪虚正室。","嘒彼虽小星，聊足侍中栉。","知予故剑怀，终始情如一。","但愿常聚首，畅叙共披襟。","不图溘然逝，魂梦何处寻。","絮酒及烹鸡，遥奠窆莫临。","思君命坎壈，嗟我步崎嵚。","我兴琴自鼓，君乐酒频斟。","我有阮瞻癖，君同潘岳心。","恰好亦郎舅，总角结诚忱。","望君我本奢，平地冀高岑。","讵知壮志日，作此断肠吟。","君已辞杯酒，我亦懒鼓琴。","问我何不鼓，从此少知音。"]},{"t":"哭黄伟山内兄 其一","f":"七言律诗","c":["世事沧桑叹不常，死生大矣岂徒伤。","酒垆感慨怀中散，琴曲凄凉泣孟尝。","念旧重挥今日泪，招魂几断故人肠。","素车白马何由达，营奠空持一瓣香。"]},{"t":"哭黄伟山内兄 其二","f":"七言律诗","c":["閒座寒毡叹也无，樽中常满不愁沽。","死生有命偏怜汝，休戚关情素悉吾。","设帐生徒多就马，连床兄弟久方苏。","他时处仲如相遇，惟见黄公旧酒炉。"]},{"t":"寒夜痛怀伟山内兄","f":"七言律诗","c":["凄凄风雨逼宵寒，愁绪缠绵梦未安。","但觉眼前知己少，可怜世上作人难。","六年阔别空通柬，一旦长离竟盖棺。","魂隔重洋招未得，「楚骚」歌罢泪频弹。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其一","f":"七言律诗","c":["人心叵测此时多，汎爱难施可奈何。","坡为滥交冤狱累，乐原无咎谤书苛。","几回往事诚堪叹，半世虚名未易磨。","月旦有评公道在，含沙射影莫为魔。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其二","f":"七言律诗","c":["人事年来叹不常，集枯集菀幻沧桑。","持身拟作三烧玉，阅世应同百鍊钢。","学问益人休自足，功名随分莫徒忙。","于今只学陶贞白，上下楼高寄隐刚。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其三","f":"七言律诗","c":["半壁纵横遍虎豺，北来音耗听多乖。","螳螂讵信能当毂，虺蜴无端起祸阶。","嚼齿空存吞贼气，拊膺难遂报君怀。","可怜数郡遭荼毒，血肉为泥骨作柴。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其四","f":"七言律诗","c":["军中安得奋空拳，敌势猖狂壁垒坚。","争战年深稀露布，相持日久合屯田。","献谋岂少徐洪客，抗节谁为鲁仲连。","愧我昂藏身七尺，渡江未敢著先鞭。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其五","f":"七言律诗","c":["国计艰难帑藏倾，一波甫息一波生。","牢骚诗有伤时语，忧愤歌多变徵声。","惟有痴顽蠲未了，尚馀垒块叹难平。","自嗟身世同狼狈，薪米营谋亦屡更。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其六","f":"七言律诗","c":["从来泥古病难瘳，千载涛斜话柄留。","报国文章成下策，勤王武略见高谋。","关中转饷功多矣，海外徵粮事就不。","但有萧公经济在，酬庸差不愧封侯。"]},{"t":"寒灯夜雨，独坐有感。赋成七首，以述懑怀 其七","f":"七言律诗","c":["碌碌尘中少赏音，此生风骨自崎嵚。","迎人肯作宣明面，谋国当如汲黯心。","但得山中长啸傲，何能泽畔免讴吟。","知几自古惟明哲，事到非常岂易任。"]},{"t":"元旦花前小宴述怀","f":"七言律诗","c":["瑞日瞳瞳正曙天，屠苏新酿出佳筵。","会宜花下浮三白，又在诗中过一年。","报国无谋唯助饷，生儿好学胜营田。","身閒最易光阴老，自笑光阴浪掷偏。"]},{"t":"依韵和籋云先生「百叶白桃花」","f":"七言律诗","c":["黛绿盈盈粉白堆，瑶池佳种想分栽。","风流欲并梅为偶，隐约浑看玉作胎。","一样天台云影簇，几分露井月痕猜。","平明移向宫门外，错认娥眉淡扫来。"]},{"t":"閒居","f":"七言律诗","c":["深观事理历时艰，养拙年来独闭关。","阅世真如棋局变，辞官始觉布衣閒。","酒怀冷落愁中减，诗草零星病后删。","赖有小园堪涉趣，何须笠屐远看山。"]},{"t":"凤鼻嵌顶晚眺","f":"七言律诗","c":["峦嶂层层景不凡，探游有客履巉岩。","披图碧海窥无际，携句青天问亦堪。","咳唾峰头惊倒瀑，模糊云际辨归帆。","登临饶得精神旷，野草尘心一样芟。"]},{"t":"黄莘田端砚歌","f":"古风","c":["得来好砚同好友，日日摩挲常在手。","伴吟墨使陈静轩，资写「黄庭」向晴牖。","闽中同嗜本有人，十砚老人莘田叟。","直如砚癖子瞻翁，不让风流钱可久。","湖曲百篇擅竹枝，草笺一部描花柳。","杨、李当时并盛名，津津脍炙千人口。","许都高士媲双丁，邺架连篇方二酉。","行遍江南又岭南，喜近素馨田百亩。","平生作吏拙催科，能扇仁风遍原薮。","放衙花底纸挥毫，判牍筵间杯在口。","相关性命砚兼花，自写胸怀诗与酒。","因此罢官归去来，清时何害风流咎。","囊中祗剩二千金，半购端溪紫云母。","归装十砚剩馀赀，还取珠江两姝秀。","桃叶、桃根泛棹归，燕子楼中甘白首。","陈迹回头百十年，浮云变幻成衣狗。","旧物星分到海东，连城荆璞为吾有。","「香草笺」中此砚诗，玉堂佳句镌其后。","漫说牛毛白蕉镵，勿誇鹆眼青华剖。","赚称铜雀赝未央，泥瓦尤嫌难涤垢。","兹珍润发细如脂，元玉之声清越扣。","我有清夜篪钟琴，棐几明窗堪配偶。","吾侪立脚重彝伦，大德不逾何足丑。","自来物固因人传，花木亦当敬欧九。","君不见信国当年玉带生，珍同圭璧辉琮玖。","造就金刚不坏身，二谢之名随不朽。","我砚人间亦既稀，无德以资良愧忸。","于今猛省修虔，善行嘉言书座右。","化为丹篆吐红光，万丈冲霄慑星斗。"]},{"t":"与容谈及嵌城妓家风气偶成","f":"五言律诗","c":["台郡盛秋娘，相欣马队装。","倩妆簪茉莉，款客捧槟榔。","最尚巫家鬼，频烧野庙香。","尽观花与柳，须待送迎王。"]},{"t":"刘将军杀贼歌","f":"七言古诗","c":["将军骑马如乘龙，将军杀贼如屠豕。","将军之命虽太穷，将军之功犹可纪。","昔时妖气警欃枪，伏莽忽然揭竿起。","星星之火倏燎原，迅雷不及防掩耳。","纨裤子弟方将兵，惊闻警报魂魄褫。","畏贼如虎思迁延，师出北门行复止。","时危势急思英雄，将军起自草茅里。","壮志常嗤半段枪，微躯幸未三遗矢。","据鞍顾盼殊自雄，登坛顿令军中喜。","小丑跳梁不足平，朝食还当约灭此。","纷纷贼队薄城陬，猛似虎狼多似蚁。","诸营瑟缩不敢前，将军独自策鞭棰。","单骑奋勇冲重围，挥刀一跃入敌垒。","惊沙扑地掠腥风，白日沉沉鲁戈指。","雄姿飒爽酣战来，霜锋熌烂霜蹄驶。","力强刀脆断连肩，刀光电落渠魁死。","万夫辟易不敢当，猛虎驱羊差可拟。","俄看贼势如冰消，车辙散乱旌旗靡。","率师乘胜还长驱，捣巢势恰摧枯比。","献俘获馘凯歌旋，萑苻从此消奸宄。","破敌同推第一功，勋名首列奏天子。","方欣丹诏渥酬庸，皇衢展足驰骋駬。","岂期功大数偏奇，未膺宠命先颓委。","将星半夜落城南，空留大树供铭诔。","我闻将军生不凡，性情爽直须眉美。","阿谀不屑学脂韦，谗谤遂教兴薏苡。","罢职常遭醉尉呵，穷居屡受庸人訾。","种菜无聊苦闭门，卖浆自给贫居市。","家徒壁立甑生尘，可怜命运真遭否。","一朝得意立功名，穷途方幸逢知己。","讵料天不假之年，功成弗获披金紫。","且闻身后剩妻孥，孤寡无依呼庚癸。","呜呼天道真梦梦，斯人困厄乃如是。","太平不听鼓鼙鸣，谁复闻声思战士。","我怀遗事聊长歌，褒扬勇烈待青史。"]},{"t":"伟山内兄殁于榕城，眷属十馀口渡海远来相依。安置已定，作诗以志感伤","f":"五言古诗","c":["寡鹄啼哀哀，孤雏鸣唧唧。","相依渡海来，可怜皆弱质。","无食号馁饥，无衣苦寒慄。","居住复无庐，何处堪容膝。","举家十馀人，谋生计安出。","睹此怀故人，我心倍怆恻。","葺我南园居，细小藉栖息。","分我布帛衣，寒威免侵逼。","指我北庄囷，三餐聊饱食。","男课以诗书，女课以纺绩。","有井可汲炊，有圃可艺植。","半载经营心，聊以尽吾力。","唯稍分润之，岂能俾充实。","但期教有方，诸雏振云翼。","庶几入九原，相见无惭色。"]},{"t":"遣怀 其一","f":"五言律诗","c":["虚堂清且洁，尽日快吟身。","砚润窗临水，茶清几绝尘。","琴心精后觉，诗思悟中真。","即此舒怀抱，何须访隐沦。"]},{"t":"遣怀 其二","f":"五言律诗","c":["事省怀常放，居閒性自恬。","园池卅亩阔，僧俗一身兼。","博览钦匡鼎，幽栖慕宋纤。","魏三经济拙，林下自称潜。"]},{"t":"遣怀 其三","f":"五言律诗","c":["藤床常抱膝，四壁爱虚明。","坐拥图书富，居环竹木荣。","投壶聊代射，对局当观兵。","无力排时难，于兹合耦耕。"]},{"t":"观盂兰放水灯","f":"七言律诗","c":["一派繁华眼欲迷，瑜伽接引向西溪。","灯光灿烂千家共，人语喧呼百戏齐。","直使水神惊耀蚌，重教鳞族诧燃犀。","今宵暂弛金吾禁，归路频闻报晓鸡。"]},{"t":"族姑余母贞节孝词","f":"楚辞体","c":["骇浪横吞兮片板况，飓风怒掣兮孤舟覆。","余家有子聪明郎，货殖经营往彰鹿。","传来死信到家乡，母痛娇儿彻夜哭。","血泪流残竟失明，时时首向衾中缩。","井泉漱口舐昏眸，岩电光瞳开曤目。","襁褓于归姑是亲，孩提为媳夫同鞠。","望门寡妇直比儿，织席樵苏甘婢仆。","哀啼恐痛老姑心，范氏悲同向山谷。","柏舟有志矢髫龄，「之死靡他」向天祝。","遂将宗子作嗣男，大厦无倾支一木。","养生葬死教子成，数十寒暄嗟迅速。","毕世孝贞天地知，平生节义鬼神服。","可怜子死媳亦贤，膝下孤雁同抚育。","曹、黄二公重伦彝，妇德历陈申宪牍。","纶音一旦降海邦，幽光此日显煌煜。","首倡捐资助建坊，艰难海运稀舻舳。","德可感神非偶然，无端巨石浮溪澳。","造成坊表立河颇，姑来一拜旋平矗。","次年苦旱过夏初，四野焦枯伤黍菽。","官民叩吁总无功，面面相觑额频蹙。","咸请我姑出祷祈，千人万姓同匍匐。","我姑节操凛冰霜，岂有元冥不听服。","归途衣袂尽沾濡，几日淋漓失平陆。","频年数出应同前，风伯雨师相随逐。","共道雨如藏袖中，抖袖登时纷霢霂。","由来节孝眷两间，故为我姑扬芬馥。","八十馀龄大耄身，依然处女范清肃。","请看大甲贞孝坊，万载姑名书帛竹。","我今作诗惭直词，才薄书难盈尺幅。","须知风化系全台，岂独徽光归两族。","重计东瀛节孝坊，我姑之外馀五、六。","仅有我姑「贞孝坊」，「节孝贞」能三字读。"]},{"t":"秋感五首 其一","f":"七言律诗","c":["一年客易又秋风，枕簟凉生竹院东。","断续戍楼闻画角，翱翔云路起征鸿。","兴悲宋玉情堪托，作赋欧阳句自工。","中夜偶然惊梦觉，挑灯我亦问奚僮。"]},{"t":"秋感五首 其二","f":"七言律诗","c":["世事纷纭似乱蓬，一年容易又秋风。","连营刁斗音相递，隔地烽烟道未通。","骐骥已空今冀北，鸱鸮犹踞古江东。","中流击楫平生志，无米之炊计易穷。"]},{"t":"秋感五首 其三","f":"七言律诗","c":["火云收尽见长空，独凭危栏远望通。","几日寂寥因醉酒，一年容易又秋风。","邻砧声急传深巷，墙柳阴疏忆故丛。","最是落花如雨后，不堪回首向城东。"]},{"t":"秋感五首 其四","f":"七言律诗","c":["月冷霜高夜气冲，残灯四壁遍吟虫。","琴书有味堪为伴，山水多情最系衷。","半世浮沉嗟往事，一年容易又秋风。","可怜早岁干云气，浪掷居诸玩愒中。"]},{"t":"秋感五首 其五","f":"七言律诗","c":["柴门深闭寂寥中，抱瓮携锄兴未穷。","诗思满怀宗白傅，菊花盈把感陶公。","气消溽暑来新雁，韵易清商入爨桐。","静里不知时序改，一年容易又秋风。"]},{"t":"友人询潜园近景，作此答之","f":"五言古诗","c":["自笑身如蠖，潜居称此园。","在山消远志，近市隔尘喧。","写兴诗千首，开怀酒一樽。","茶甘留舌本，香妙净闻根。","鼓锻怀嵇灶，围棋慕谢墩。","抚琴欣有趣，读画悟无言。","水活泉通沼，城低堞当垣。","亭台开月榭，楼阁接云轩。","梅绕东西院，花迷左右村。","槿篱围药圃，竹径隐柴门。","吟社新盟结，歌场艳曲翻。","爱才频说项，赌醉每留髡。","笠屐身犹健，林泉乐弗谖。","君生知足甚，名利不须论。","不官如栗里，此地即桃源。","入世嗤牛马，归山约鹤猿。"]},{"t":"余园中多蓄怪石，有合于「绉瘦透」三字者，峭立可人。因赏以诗","f":"七言律诗","c":["东海携归怪状呈，髯苏当日最留情。","灵通说法头应点，峭合论文势不平。","思黯品题宜列甲，元章参拜定呼兄。","故知上世娲皇力，瘦骨玲珑煅炼成。"]},{"t":"家翔秋茂才以为「兄」字难次，复叠前韵戏成","f":"七言律诗","c":["陡峭巉岩骨相呈，苔纹如绣倍生情。","倘投浅水心相契，为漱流泉势不平。","解酒能醒沉湎客，点金随化孔方兄。","可人自有天真在，讵藉神工鬼斧成。"]},{"t":"岁暮杂感 其一","f":"五言古诗","c":["烈风动地来，岁月暮何速。","近事不忍闻，世途尤窘蹙。","中原苦甲兵，元气犹未复。","又加警报频，北顾悲蒿目。","当兹岁暮时，天寒闻野哭。","造化本仁慈，劫运何杀肃。","天王原圣明，荒裔同滋育。","肉食无远谋，临事乃退缩。","愧我无寸权，庸才复碌碌。","愤来学渐离，悲歌自击筑。"]},{"t":"岁暮杂感 其二","f":"五言古诗","c":["寒风号声哀，白日忽西昃。","翘首呼苍天，此心曷有极。","痛余生不辰，孤提遭苦棘。","慈亲怜我孤，柏舟矢型式。","画萩志拳拳，望儿振云翼。","其如姓豪强，肮脏矜勇力。","结交郭与朱，乡闾目咸侧。","慈亲暗中悲，尽日愁胸臆。","辗转再筹思，事穷计忽得。","第使游大邦，阅□多闻识。","理明礼义谙，或可受羁勒。","妇翁正北辕，□携适京国。","数载始归来，自愧无树植。","王母旋弃养，哀痛竟交逼。","季父复继逝，灾祸悲莫测。","家事一身承，重荷愧弗克。","薄祚伤衰微，慈闱多忧色。","未获睹抱孙，每饭不甘食。","无以报春晖，自愧亏子职。","方谓待须臾，此望或可即。","一旦秋风悲，萱草萎堂北。","白日惨无光，黄沙障昏黑。","抱恨无穷期，我心徒引慝。","嗟我空言诗，开篇羞屺陟。"]},{"t":"岁暮杂感 其三","f":"五言古诗","c":["生离已吞声，死别长恻恻。","寒宵卧空床，悼亡长太息。","忆昔我岳翁，举家之燕北。","因怜道路长，纤弱难远适。","挈送入我门，母女泪涟淢。","其时年十五，钗裙无华饰。","十六余远行，代我供子职。","尽孝事重闱，承欢多顺色。","三载余归来，下机喜停织。","十九始成婚，阃仪殊谨饬。","亲戚同里闾，齐声称妇德。","病忽入膏肓，参苓医不得。","零落归山邱，长隔如异域。","魂梦空相亲，音容忍回忆。","一灯雨夜寒，凄绝空房黑。"]},{"t":"岁暮杂感 其四","f":"楚辞体","c":["寒风吹林木，萧萧不忍听。","昔年亲与友，今日半凋零。","我忆陈无已，壮岁能穷经。","据案探坟典，永昼长掩扃。","秋风欣折桂，鹏方奋南溟。","讵期寿不永，赍志归幽冥。","忆我初定婚，其时始十龄。","岳翁黄叔度，一面眼垂青。","相随侍京邸，训诲时亲聆。","贤梓更爱我，感之常镌铭。","泰山忽然颓，恸哭思仪型。","别来曾几时，音讯方欣聆。","岂料溘然逝，身后遗伶仃。","复忆高达夫，玉树立亭亭。","训我以正语，如钟警梦醒。","一朝相永诀，延寿无参苓。","祗今顽钝时，谁复为磨硎。","古人去已远，知己如晨星。","夜深思颜色，悲风吹素屏。","魂兮不可招，怀旧心怆恻。","涕泗流泠泠，枫林青复青。"]},{"t":"岁暮杂感 其五","f":"五言古诗","c":["岁暮气阴森，严风萎百草。","长空死白日，黄尘飞浩浩。","苦见挑负徒，悠悠涉长道。","短褐不蔽肤，形容更枯槁。","饥来不得食，妻孥岂复保。","会见老与弱，身填沟壑早。","嗟予数年来，命蹇身潦倒。","产业渐凋零，田园苦旱潦。","博施力未能，痌瘝空在抱。","惭颜对里闾，中心惄如捣。"]},{"t":"错成","f":"七言律诗","c":["错已错成可奈何，黄金虚掷任媕娿。","悔将肘腋飧狼腹，忍见门庭置雀罗。","卅载交人知己少，半生累我爱根多。","古今二者同堪叹，太息鱼门与老坡。"]},{"t":"频年曲，答萧荐阶茂才见赠之作","f":"古风","c":["频年不见萧子云，今朝得挹芝兰芬。","握谈入座未数语，意味如饮香醪醇。","西窗剪烛认反覆，讶非昔时旧面目。","问君缘何太瘦生，道是频年困场屋。","有命休同平子愁，失时宁作刘蕡哭。","羡子藉藉名，羡子便便腹。","似此英才久不售，我欲更向成都为君一问卜。","如谓文无灵，韩潮、苏海岂非两文星。","千年万载常如在，文章竟是驰风霆。","庐陵先生留青盼，能以文章别真赝。","暗里朱衣不点头，高名依旧罗昭谏。","毕竟老辈能怜才，不因弃甲笑于思。","客榻预因徐孺下，幕寮独为郗超开。","由来爱士同爱将，黄金怎比读书台。","春风桃李开芳宴，棨戟遥临森锁浣。","花香驿路酒频斟，醉来两眼直岩电。","虽说为人作嫁衣，所取无讹尽黄绢。","一枝玉尺代量才，权衡已操八闽遍。","聊此扬雄作解嘲，得士千人多邦彦。","不到九转功，那识金丹鍊。","不步云梯难，怎达凌霄殿。","岂无登科年少人，自谓一第能荣身。","我知天欲为君留后福，故使蹭蹬相折服。","历尽错节与盘根，大器晚成防其速。","愿君勿牢骚，愿君勿退缩。","从此加精进，中原旋得鹿。","吁嗟乎，梁灏、唐皋下第时，落魄归来还苦读。","旋闻杏苑传胪声，千古美谈镌帛竹。","况君正值强壮年，气宇飘飘渺列仙。","采我刍荛休自馁，管教稳步瀛州最上巅。"]},{"t":"小憩龟崙岭观音庵题壁","f":"五言律诗","c":["拾级上层巅，尘襟一洒然。","篁幽阴夹道，树老干参天。","汲水僧烹茗，焚香客问禅。","我来欣晚眺，暮霭袅炊烟。"]},{"t":"内湖庄偶成 其一","f":"七言绝句","c":["郊原春暖草勾萌，叱犊声高遍耦耕。","烟景不分三月暮，子规啼歇乱蛙鸣。"]},{"t":"内湖庄偶成 其二","f":"七言绝句","c":["晓晴复幻密阴天，漠漠平畴尽水田。","野屋万家春树里，午风吹得雨如烟。"]},{"t":"双溪山登眺","f":"五言律诗","c":["群壑开还合，浓云锁几重。","乱流奔石濑，遥翠袭岩松。","鸟语深林答，蚕丛曲径通。","人家何处是，可许结茅从。"]},{"t":"自双溪石阁晚归","f":"七言律诗","c":["东皋回首白云巅，竹策芒鞋度曲旋。","峭壁每生悬涧树，层峦难阻出山泉。","一溪流水回芳磴，十里平芜际暮天。","待得渔樵归去后，渡头落日上轻烟。"]},{"t":"题剑潭村家书屋","f":"七言律诗","c":["富贵、神仙未易兼，贫饶清福复何嫌。","一湾流水青环屋，万笏群山绿入帘。","摊饭人方眠石倦，品茶我亦饮泉廉。","眼前风景皆诗料，好句谁能信手拈。"]},{"t":"大雨飓夜宿官道小楼","f":"七言律诗","c":["危楼摇曳入云高，六月寒生范叔袍。","雨阵射窗同劲弩，风威撼屋肖狂涛。","乾坤若磨随旋转，草木皆兵听怒号。","彻夜惊魂凭酒压，诗成耳热兴犹豪。"]},{"t":"凤山崎归途口号","f":"五言古诗","c":["尽日笋舆间，轧轧听繁响。","薄暮凤山巅，凭高时俯仰。","城垣一气中，迷离浑灌莽。","日入家尚遥，性急心如痒。","努力飧舆夫，踉跄促前往。","妻孥盼我归，久候皆怅惘。","瞥然已到家，相见襟怀爽。"]},{"t":"感时","f":"七言律诗","c":["禦敌鎗多半段才，江南江右总堪哀。","六朝金粉千行泪，三月烟花一劫灰。","戎马不看行掣电，糗车空听动鸣雷。","醉来掣剑频歌舞，抑塞胸襟痛莫开。"]},{"t":"感述 其一","f":"七言律诗","c":["愁绪牢骚可奈何，不堪子夜又闻歌。","人情阴险鱼藏剑，世态炎凉雀设罗。","好客方思追北海，吟诗讵料累东坡。","雨云翻覆浑无定，负义人真世上多。"]},{"t":"感述 其二","f":"七言律诗","c":["填胸礧块郁难开，遥望中原总可哀。","伏阙贾生空上策，助边卜式肯输财。","螳螂枉奋当车臂，骐骥终非伏枥才。","入市无人收骏骨，黄金何日筑燕台。"]},{"t":"望儿既殁，刘姬因痛子，病将不治。又值时艰，感述一首","f":"七言律诗","c":["翀霄无翼可高飞，默计平生志总非。","盛世功名羞卜式，传家世业愧宏微。","营谋几肖鲇升竹，动作频同马受鞿。","难得童时真乐境，卅年回忆尚依稀。"]},{"t":"内湖夜泊","f":"七言律诗","c":["修竹环村柳绕扉，小舟移向绿阴依。","疏林霜冷鸦声咽，远浦星疏蟹火微。","乱苇摇风喧断岸，孤篷引月近寒矶。","忽听笛韵沧浪起，知有渔翁罢钓归。"]},{"t":"感述","f":"五言律诗","c":["可怜强壮日，几断别离肠。","作誓悲秦穆，长歌叹楚狂。","妻儿双别泪，家国九回肠。","且复居偏陋，鞿羁水一方。"]},{"t":"有感","f":"五言律诗","c":["成文时怒骂，对酒每悲歌。","世乱肠空热，家贫累更多。","功名羞捷径，身世寄吟窝。","未遂封侯志，樽前剑自摩。"]},{"t":"秋感","f":"七言律诗","c":["秋色萧萧院落深，捲帘人怯暮寒侵。","胸多磊块聊拚酒，调带悲凉怕鼓琴。","断雁唳霜传远信，哀蛩咽月和微吟。","剧怜长夜空房寂，灯影摇青刻漏沉。"]},{"t":"自双溪石","f":"五言律诗","c":["一雨田原足，芳荪夹岸生。","身轻争马健，径窄让牛行。","溪树连空远，山云积涧平。","清游归去晚，数里夕阳明。"]},{"t":"自芝兰归新庄途次即目","f":"七言律诗","c":["晻暧溪山起暮烟，平芜十里尽园田。","笼笼翳景看遥树，虢虢清流爱细泉。","放牧马嘶芳草岸，泊船人语夕阳天。","最欣一幅营邱画，坐对茅亭意洒然。"]},{"t":"重入双溪","f":"五言律诗","c":["浪迹频年事，耽吟快啸游。","溪山双只屐，烟雨一孤舟。","放鹤来亭上，寻梅过陇头。","吾家有衣钵，高尚自千秋。"]},{"t":"成都马叟年届八旬，只身作万里归计，闻者莫不叹息。口占送之","f":"七言律诗","c":["夕阳亭畔送征镳，云拥峨眉首屡翘。","万里关河身踽踽，五更风雪马萧萧。","境穷始肯刀环唱，气壮休愁剑阁遥。","只叹是翁真矍铄，玉门今日返班超。"]},{"t":"节烈行","f":"古风","c":["吾家有姑端且庄，廿载依依事高堂。","长成远嫁温陵客，天遣梁鸿配孟光。","夫婿本多才，励志帷常下。","伴读操女红，一灯共深夜。","第思战捷可救穷，抟风苦盼鲲鹏化。","讵知郎命生不辰，文章憎达遭邅迍。","再战再北筋力尽，呕心有血长吟呻。","凄风惨烈鸺鹠叫，才人竟赴修文召。","孤雏寡鹄悲㷀㷀，入门惟有青蝇吊。","抚棺恸哭思捐生，决欲相随到玉京。","诸亲劝姑慎勿死，谓姑关系诚非轻。","尔身无姑舅，尔夫无弟兄。","两孤、三尺土，死后谁经营。","吾姑始悟肩荷重，日勤操作夜饮泣，节操凛懔冰霜清。","儇薄少年悦姑美，饵以黄金置诸几。","姑不之顾中赩然，手浣衣裳心似水。","深霄感帨惊吠尨，强暴居然敢窥伺。","烈哉矩姑，握刀而起。","先断己发，后断伧趾。","狂夫跪呼救，号声动邻里。","众人代乞命，舍之不足齿。","姑曰惟恐污我刀，不然一杀直屠豕。","携儿哭诉我祖前，祖重其节筹保全。","谓尔无所居，我有居三椽。","谓尔无所食，我有数亩田。","寒则遗以衣，贫则遗以钱。","困乏不必虑，抚孤心可专。","我母亦少寡，同病乃相怜。","我初出母腹，爱我意拳拳。","日哺我食、夜鸣我眠，我身成立，姑首皓然。","无以报姑德，寸心常歉然。","岂期姑子懦而弱，娶妇任其肆奇虐。","因之愤病入膏肓，延龄竟少神仙药。","吁嗟乎，我闻节烈格穹苍，作善之理宜降祥。","姑乃命乖蹇，其后复不昌。","修德弗获报，天道殊茫茫。","我欲请旌表，为姑建高坊。","大书特书「节烈」字，垂诸不朽长煌煌。"]},{"t":"夜同戴芝轩煮茗弹琴即事","f":"五言律诗","c":["小阁绝纤埃，岩隈际水隈。","池波清浴月，林鹤老巡梅。","茶煮团名雀，琴弹曲作雷。","戴逵高兴在，良夜喜同陪。"]},{"t":"雨夜闻蛤","f":"七言绝句","c":["潇潇细雨养莓苔，杏脸初舒柳眼开。","夜静倍知春意好，晚风时送蛤声来。"]},{"t":"上巳日张筵池东轩，邀曾籋云先生、叶松潭广文、内弟黄翼南孝廉暨诸同好诗歌射奕，作修禊韵事","f":"七言律诗","c":["满轩佳气袭和融，正值兰亭乐事同。","水色浮岚浓淡碧，花颜映日浅深红。","当筵有令人三雅，对景无诗我一中。","醉后连襟池上步，又随蜂蝶入芳丛。"]},{"t":"题武林王棣香二尹诗集并以送别 其一","f":"七言律诗","c":["渊然性格是吾师，华翰何、刘喜并之。","东野官閒聊寄迹，西湖家近称吟脾。","篇皆迈古骚人笔，句尽空前幼妇辞。","尚有一行多惠政，策名正好值清时。"]},{"t":"题武林王棣香二尹诗集并以送别 其二","f":"七言律诗","c":["肯从矮屋忍抬头，中稳曾看白傅讴。","浊世能廉诚雅度，高名不坠乃风流。","慈祥化赞弦歌洽，淡薄交真气味投。","已觉相逢惆怅晚，骊歌倏忽又沧洲。"]},{"t":"题武林王棣香二尹诗集并以送别 其三","f":"七言律诗","c":["姿神恬默性潜沉，两载知交泐我心。","射鸭堂幽欣蹑履，种松庭广快披襟。","事能持重行常稳，物到难移识转深。","何幸南行来召伯，口碑从此遍佳音。"]},{"t":"寿芷亭大姻翁七十 其一","f":"七言律诗","c":["祥光纠缦拥门眉，富贵双兼寿考垂。","风度曲江瞻气概，精神潞国仰丰姿。","地仙有福善清享，天爵尤全端始基。","更羡传经能继美，弹冠早到凤凰池。"]},{"t":"寿芷亭大姻翁七十 其二","f":"七言律诗","c":["苍颜白发眼方瞳，到处争看矍铄翁。","班列文鹓翎本翠，健如老鹤顶新红。","诗书裕后传山左，甲第开先冠海东。","我亦荣施誇梓里，蒹葭叨倚玉兰丛。"]},{"t":"寿芷亭大姻翁七十 其三","f":"七言律诗","c":["圣谟七十许悬车，况著斑衣早遂初。","万石君多贤子弟，二疏老更惠乡闾。","阴浓桃李新培渥，代盛簪缨厚泽馀。","自是传薪好家世，皋比位重共称誉。"]},{"t":"寿芷亭大姻翁七十 其四","f":"七言律诗","c":["在弧耿耿见星躔，门第端卿仰望先。","百亩园居名「北郭」，七旬觞庆际中天。","幔亭宴喜今朝设，海屋筹看比岁添。","从此灵椿增秀茂，九如长愿祝年年。"]},{"t":"购花难行","f":"古风","c":["吾生爱花真有癖，开场筑圃甘形役。","堪嗟僻壤小于拳，且复海陬伤风伯。","唯有春时野草花，閒生杂树连阡陌。","几双不借踏将穿，走遍溪山觅无迹。","虽然篱畔紫与黄，俗卉凡葩兴莫适。","袁保能司玉骨销，河阳虽美沧波隔。","吾侪本是爱花身，结习何能空晨夕。","遍询众口皆同声，言从海内恣求择。","求择虽易运归难，骇浪号风簸海舶。","欲将佳植置艎仓，热气薰蒸无空隙。","无论珠玉一登舟，舵工土视不知惜。","重洋春色望年年，枉把黄金浪虚掷。","无花觅句句难佳，有意求花花莫得。","费尽园居早起心，替花攒眉求妙策。","当时靖海收澎岛，梅花一阵旋降敌。","我今四访购之归，用多运少花终集。","点谱惟无凤阁书，累篇笑有兔园册。","春蚕灯下食叶声，剡藤簌簌鸡毛力。","岂拟平泉花石纲，开列成编寄吴、越。","一航嘱傤十缸回，十舸运来花成百。","遂把荆榛荒芜园，化成锦绣幽香窟。","雅趣并誇殷七家，高风敢并魏三宅。","人生不得拓胸怀，虽寿亦夭头空白。","从此群芳解语迎，一水毋须长脉脉。","抱鹤携琴任徜徉，烹茶觅句供游息。","坦腹篷窗鼓枻时，夹岸飞英落吟席。","回想十年乞购难，爱护栽培比瑶璧。","重申童约课园丁，桐帽棕鞋亲周历。","守户猧儿缀树铃，缭垣青士幔天幂。","君不见顾家国园但接骚人与隐流，不容伧父和狂客。"]},{"t":"闻扬州失守感赋","f":"七言律诗","c":["兵燹谁能浩劫逃，平山堂外雁哀嗷。","三千殿脚红头尽，廿四桥头白骨高。","满地狼烽摧鼓角，故宫萤火没蓬蒿。","绿杨城郭成焦土，回忆繁华首重搔。"]},{"t":"感时","f":"七言律诗","c":["舻舳乘风趁顺流，妖氛惨惨秣陵秋。","如何赤纛临江口，却被黄巾据石头。","避敌已抛丞相节，逃生先走太师舟。","东南半壁容巢穴，从此残棋劫未休。"]},{"t":"述癖","f":"七言律诗","c":["痂嗜何须笑古人，天将奇癖付吾身。","购琴价重甘捐产，养鹤粮多肯指囷。","藏酒款宾非自饮，解囊赠客不言贫。","耽吟更至忘眠食，一字推敲苦费神。"]},{"t":"登牛栏坑后山憩野人家","f":"七言律诗","c":["寒烟凝聚暮云飞，岚翠霏霏欲湿衣。","峭壁萝垂泉脉细，层岩竹密日光微。","山多樵径愁迷路，林有人家许叩扉。","小坐暂将清茗酌，阶前猿鸟亦忘机。"]},{"t":"自芝兰晚归新庄","f":"七言律诗","c":["马蹄轻健快平坡，历落村庄近水多。","乍退潮沙纹绮縠，暴长篱笋簇矛戈。","浓云阵阵方漫野，细雨霏霏尚隔河。","行到渡头天欲晓，待船时听打鱼歌。"]},{"t":"双溪即景","f":"七言绝句","c":["山禽啼罢水禽啼，烟树云泉惬碧栖。","待得两堤桃尽放，双溪即是武陵溪。"]},{"t":"夜宿观音山","f":"七言律诗","c":["秋色苍茫黯远岑，乱山匼匝白云深。","雁传寒信月千里，鸦咽啼声霜半林。","远浦帆樯烟隐隐，下方钟鼓夜沉沉。","幽香闻道生空谷，欲谱猗兰一曲琴。"]},{"t":"雨后艋舺溪归舟汎眺","f":"七言律诗","c":["蓬中朗爽似虚亭，高眄平望极杳冥。","远水并分双涧白，遥山特插一峰青。","堤前林树号秋籁，雨后溪流带晚腥。","我亦志和怀浩落，烟波尽日汎孤舲。"]},{"t":"宿摆接山家","f":"五言律诗","c":["胜地客楼宿，烟峦快入眸。","秋深山月冷，夜静石泉幽。","引水通茶室，携琴上竹楼。","悠悠「三弄」罢，檐际白云浮。"]},{"t":"由芝兰山过金包里","f":"五言律诗","c":["蚕丛行十里，劳顿渐难禁。","岭峻人如豆，山荒草似林。","涧泉奔濑急，岩径入云深。","小憩茅亭下，烹茶许细斟。"]},{"t":"栖云崖晚眺 其一","f":"五言律诗","c":["远望生吟兴，山深景倍幽。","斜阳修竹外，疏柳板桥头。","港小舟成市，崖高屋比楼。","豁然开眼界，凭眺起长讴。"]},{"t":"栖云崖晚眺 其二","f":"五言律诗","c":["遥望长堤外，清波自浅深。","潮回沙渐隐，云暝日将沉。","渔火明孤屿，岩钟度远林。","俄看凉月吐，幽趣契胸襟。"]},{"t":"官渡舟夜","f":"七言绝句","c":["涧云衔日孤鸟度，欲落未落天已暮。","何来耳畔橹摇声，烟水苍茫不知处。"]},{"t":"青潭晚泊","f":"五言律诗","c":["晚泊澄潭上，游踪寄短篷。","溪烟生落日，野烧极遥空。","艇小閒渔父，牛高稳牧童。","自然成习惯，所业在其中。"]},{"t":"官渡舟行","f":"七言绝句","c":["十里平波碧似油，一帆风好送轻舟。","悠然独倚篷窗望，贪看青山不掉头。"]},{"t":"双溪口号 其一","f":"七言绝句","c":["石田茅屋正当溪，绿叶阴森万木齐。","一径飞泉悬峭壁，夕阳时节过山西。"]},{"t":"双溪口号 其二","f":"七言绝句","c":["驾石为桥竹作笆，萦纡流水护人家。","轻风几阵清香送，开遍田间晚稻花。"]},{"t":"雨后泊剑潭作 其一","f":"五言律诗","c":["雨晴添霁色，天气又晴和。","桥岸垂疏柳，溪沙养绿䔋。","半林鸦背日，十里鸭头波。","何处沧浪笛，随风和棹歌。"]},{"t":"雨后泊剑潭作 其二","f":"五言律诗","c":["推篷看夜色，四望思依依。","酒旆前村隐，鱼灯远岸微。","钟声催客枕，月影度渔矶。","领略清宵趣，吾生久息机。"]},{"t":"秋夜宿剑潭寺","f":"七言律诗","c":["怪石澄潭绕径长，登临镇日任相羊。","著衣欲湿皆岚翠，度水尤清是桂香。","松引岩云环客榻，竹招山月下禅房。","停琴品罢支公茗，又鼓谈经廿一章。"]},{"t":"偕戴山人宿栖云岩","f":"七言律诗","c":["泠然听罢戴逵琴，翘首寥空互啸吟。","一榻松云秋瑟瑟，半帘竹月夜沉沉。","丹崖境静清尘梦，碧涧泉幽證道心。","相约明朝游眺去，安排筇屐上层岑。"]},{"t":"宿内湖祖师岩","f":"五言律诗","c":["道人栖隐处，高在白云端。","竹露滴清籁，松涛生暮寒。","灵猿眠石洞，老鹤守香坛。","夜静来明月，瑶琴独自弹。"]},{"t":"薄暮潭底道中","f":"五言律诗","c":["霁景豁吟眸，身閒爱浪游。","波光摇落日，山色淡深秋。","远树笼僧舍，归云拥戍楼。","徘徊驴背上，诗思更清幽。"]},{"t":"雅集新庄别业赏菊","f":"七言律诗","c":["赏菊持螯互品评，清秋日日接群英。","对花我愧陶元亮，把酒谁为阮步兵。","聊藉高吟抒雅趣，敢从豪饮得狂名。","兴酣击钵摧联句，烛尽三条百韵成。"]},{"t":"霄里晓发","f":"五言律诗","c":["鸡声三唱后，揽辔度征邮。","残月溪村曙，清霜野径秋。","闻钟惊旅梦，看剑起离愁。","晓色苍凉甚，风来扑马头。"]},{"t":"冒雨晓行新埔道中","f":"五言律诗","c":["林际雨冥濛，邮程一径通。","冲寒嘶健马，破晓逐征鸿。","山色凉云外，溪声宿雾中。","欲寻沽酒处，茅店记桥东。"]},{"t":"自金门溪晚归","f":"五言律诗","c":["山容环列幛，云气薄于罗。","夕照明烟树，风寒亚晚禾。","渡头芳草断，牛背暮鸦多。","村舍葱茏里，谁家起晚歌。"]},{"t":"晓发上杞林，避寒憩庄家书屋","f":"五言古诗","c":["扶梦上箯舆，犹恋黑甜美。","睡眼尚朦胧，倏行二、三里。","犬吠晓烟中，泉鸣阴涧里。","平楚日未升，前村人乍起。","冲寒涉重溪，霜风捎两耳。","苔石险且滑，奔流互争驶。","舆夫脚瘃皴，凌竞不敢履。","历尽礌硠途，力疲欲暂止。","瞥见一星光，残灯深竹里。","少憩共围炉，檐前息行李。","启口答主人，欲言犹震齿。"]},{"t":"客有自程乡来，云黄香铁先生已殁于江右抚州任内。惊悼之馀，作长歌哭之","f":"七言古诗","c":["香铁先生我岳伯，读书万卷长为客。","囊中杰句天无功，笔下颠书风借力。","文章立缀咄嗟间，纷纷馀子无颜色。","尝闻生长自吴中，姿神潇洒多其风。","十六归乡应童试，玉树翩翩众誉同。","生花不律三峡泻，如锥脱颖惊文宗。","谓折桂枝如拾芥，烧尾龙门嗟屡败。","日向长潭事啸游，岩花社酒亦称快。","五羊城里中副车，落寞频年意不如。","鸿文只作成均贡，从此才名竞应徐。","例同过夏三冬贮，京兆贤书欣得举。","南官报罢陆庄荒，欲去仍留同首鼠。","可怜一第费经营，昔日黄童已得名。","诙谐能动公卿色，诗句曾传粉黛情。","万卷雕龙吟律细，一閒挥麈论衡精。","到处逢迎珠履趿，诸侯宾客幕中入。","宰相堂前许纵谈，将军麾下容长揖。","晚筵客散独留髡，入座重闻丝竹急。","倦还遽授一官归，廿载潮阳列绛帏。","皋比复设韩山院，春官桃李成芳菲。","天下广文官独冷，先生裘马何轻肥。","天下广文饭不足，先生黍稷满囷围。","先生平生嗜侠义，当仁强项无趋避。","京邸归来见末由，询公行止感公谊。","诗篇自昔鸡林通，题名处处碧纱笼。","郑虔事业子云札，杜牧情怀短簿容。","天性由来好诗酒，讽咏杯铛不离口。","四集诗编「读白华」，一区寓室名「香韭」。","丹青尝画醉禅图，高耸吟肩复露肘。","蒲团箕踞赤双趺，笥腹便便光秃首。","一浮三白作鲸吞，掌上瘿瓢大若斗。","天花醉里落缤纷，神女维摩互缠纠。","白鹤朱霞幻合离，龙象争拿狮子吼。","嘻笑怒骂皆文章，狡狯中间戒律守。","诗佛同登弥勒龛，智珠一串菩提手。","兴豪走马章台街，折得春风两枝柳。","诗人少达而多穷，挥霍如公复何有。","晚年需次向豫章，蜡屐庐山再徜徉。","抚州司马青衫客，又作黄粱梦一场。","巫阳促赴修文召，遗金难买返魂香。","鄙人本是公家婿，蒙公一见垂青睇。","海外瞻韩益壮心，何期此日已集逝。","知己不闻胜感恩，天涯哭当寝门例。","太息桃夭古渡头，萧寥最是铁耕楼。","抱琴鼓罢平陵曲，七条弦上一时愁。","年来春日下黄路，唯有桃花逐水流。"]},{"t":"读香铁先生「白华草堂集」「感怀」题后","f":"七言律诗","c":["可怜再见永无期，曲赡高华笔一枝。","名士尽多生乱世，诗人难得见清时。","与花同福常关眼，对酒长春自介眉。","窃把先生方杜牧，情怀气概两相宜。"]},{"t":"闻内地近信书叹","f":"五言律诗","c":["世事乱如麻，闻来痛益加。","有兵皆扫箨，无饷转量沙。","浩劫三千里，沉冤百万家。","城廛邱陇似，寂寞只啼鸦。"]},{"t":"与张鉴三封君重话旧事感赠","f":"七言律诗","c":["燕翼谋贻老景饶，平居无谄复无骄。","家庭德誉原功艺，幕府才名比郤超。","廿载时光嗟浪掷，半生交好叹凋寥。","不堪重话愁中事，昔日干云气已消。"]},{"t":"雨后行金包里道中","f":"五言律诗","c":["笋舆随屈曲，数里入金包。","急水号鱼■，深林隐鸟巢。","石奇岩踞虎，藤老壁蟠蛟。","客过层巅路，如行远树梢。"]},{"t":"宿大坪林祖师庵","f":"五言律诗","c":["禅堂真寂静，小坐惬幽情。","林密泉声隐，花深夜气清。","窥琴松月下，扇茗竹风迎。","我欲诛茅住，岩边构两楹。"]},{"t":"平林庄过孙悫民处士园作赠","f":"七言律诗","c":["寂寂柴门短短篱，群山环绕水涟漪。","花因露润香生座，竹到春深翠入池。","静院谈心閒品茗，虚窗抱膝畅评诗。","翛然顿觉尘襟净，栖隐真惟此地宜。"]},{"t":"八六堵口号","f":"七言律诗","c":["芙蓉匼匝乱烟堆，欸乃歌中峡罅开。","垂钓却嫌新涨长，张帆恰爱好风来。","溪声乱吼知滩近，水势横冲觉岸回。","我欲是乡招隐侣，堤边添个子陵台。"]},{"t":"登大屯山口号","f":"七言绝句","c":["腥风掠地战荆蒿，原兽惊人竞遁逃。","回忆旧时较猎处，鼻端出火血沾袍。"]},{"t":"七星墩即景","f":"古风","c":["历尽嵚?路，山坳又水坳。","溪桥危驾竹，野屋老编茅。","日落鸦争树，云深鸟恋巢。","葱茏欣满目，正值夏秋交。"]},{"t":"偕友登栖云岩留宿","f":"五言律诗","c":["共宿远公社，碧萝欣可攀。","鸟归仍认树，日落尚衔山。","蜡屐迹逾远，蒲团情自閒。","我非陶元亮，煮茗且怡颜。"]},{"t":"回叠前韵","f":"五言律诗","c":["跣足登■确，支颐对孱颜。","竹间暗水咽，岩际栖云閒。","花气袭幽壑，岚光生远山。","少文应识此，胜处相追攀。"]},{"t":"栖云寺即事","f":"七言律诗","c":["岩穴云归雨气收，欣晴林鸟听钩辀。","引泉修笕通厨下，缘木虬藤挂壁头。","竹密行随三径曲，花深坐对一庭幽。","可人最是松间月，似为闻琴上小楼。"]},{"t":"芝兰庄","f":"七言绝句","c":["北庄已过又南庄，鸡犬桑麻趣味长。","一路平畴环峭壁，芝兰香带稻花香。"]},{"t":"出双溪，再上芝兰圆山顶寺中小憩","f":"七言律诗","c":["涧泉漱石径幽隘，茅屋桥头醇酒卖。","送目溪山可入诗，赏心云树浑如画。","蹇驴磴曲辔频停，舴艋风轻帆乍挂。","岩畔夷犹意自然，又过竹院寻僧话。"]},{"t":"内湖田家","f":"七言绝句","c":["修篁夹岸水环村，屋后高峰护短垣。","度过板桥三五武，稻花香里是柴门。"]},{"t":"凤山崎归途暮望","f":"五言律诗","c":["海峤凭高望，垂鞭马暂停。","云低连浪白，野阔混天青。","长啸传空谷，游踪寄驿亭。","苍茫归路远，落日照林扃。"]},{"t":"潜园适兴六十韵","f":"古风","c":["不作封侯想，潜踪已十年。","屡因图画兴，辄起眺游缘。","群峭嵚?度，重峦崒嵂迁。","商羊聊拄杖，款段忍加鞭。","出既胸襟旷，归尤景物全。","灵区瞻谷口，胜处接城边。","颇得渊明趣，非同仲子贤。","筑园容寄傲，著屐任周旋。","适意欣孤往，娱情倦忘还。","崖高堪望远，地静觉居偏。","评石方僧孺，移花法道筌。","斑红阶藓润，茸碧屋萝牵。","水阔波跳鲤，林深树曳蝉。","抚松凭偃蹇，趁鹤步翩?。","淡淡堤摇柳，泠泠沼泻泉。","春融芬岸芷，露浥袭汀莲。","舞蝶翻歌扇，浮鸥傍钓船。","桥多修涧绕，路杳隔墙连。","芡实鸡头剥，蕟藤鸭脚缠。","门低榕并亚，篱密槿添编。","引蔓葡萄架，薰芳茉莉田。","果垂罗汉熟，花绽佛桑妍。","泛鹢回塘曲，盘蛇造洞巅。","苔滋层磴滑，岩瀑一流悬。","题壁鸿留爪，窥渠鹭立拳。","荷喧池过雨，竹暝径笼烟。","撒网危矶上，投壶小院前。","蔬浇抽甲壮，菊种课丁虔。","穴土挖成室，诛茅构数椽。","清宵虫语碎，晴昼鸟声穿。","格磔啼秦吉，?辀叫杜鹃。","百株栽绛雪，万卷录丹铅。","风定云横岫，星稀月在天。","楼台皆倒影，亭榭尽临渊。","避暑宾摊簟，嬉春女落钿。","奚奴随倜傥，侍史列婵娟。","阮籍游而啸，嵇康懒与眠。","茶甘烹雀舌，香霭爇龙涎。","古剑求三尺，名琴操七弦。","诗观辞骆什，帖检换鹅笺。","妙笔挥毫素，寄书问太玄。","锦贉装玳瑁，绣褫记嫏嬛。","钟鼎周陶铸，圭璋汉泐镌。","爱根何日了，吟债几时填。","思苦陈无已，脾幽孟浩然。","论文凭只眼，索句耸双肩。","枕上「逍遥传」，床头「内外篇」。","师坡常说鬼，学晋每逃禅。","交挚相倾盖，讴和共扣舷。","南皮从叶后，北面事曾先。","射覆词坛立，猜枚酒令宣。","笙箫分雅部，醽醁醉华筵。","酿厌中山困，车乘下泽便。","衷怀希魏野，气概仰张颠。","性拙薄戎算，平生轻峤钱。","言狂人窃笑，癖怪我难悛。","默默嚣尘减，悠悠俗虑捐。","有心追隐逸，无志慕腾骞。","况免饥寒逼，犹兼疾痛蠲。","曾闻唐白傅，閒散即神仙。"]},{"t":"久旱得雨，霁后周涉园池，乘兴吟示松潭广文","f":"古风","c":["一雨新众绿，草木知来苏。","荣滋欣满目，密筱连平芜。","负耒亲巡历，曲径行萦纡。","栽竹补篱落，引泉通园厨。","花好当我槛，风凉快我躯。","跣足豆棚下，溽暑倏然无。","即事多欣赏，歠茗同追呼。","人生贵适意，意适情自娱。","何必慕富贵，金张与陶朱。","匆匆扰扰间，终日奉驰驱。","堪嗤世上人，病此心不殊。","我慕香山老，到处无嵚?。","利禄不营谋，权势不争趋。","优悠居里道，歌舞园亭俱。","退老乐天年，清福人莫逾。","本其能知足，平生多欢愉。","历数诗人中，惟公高且孤。","举此示同调，岂以我为愚。"]},{"t":"书叹","f":"七言律诗","c":["陵谷无常叹若何，可怜陆海遍扬波。","秋风客路行人少，落日荒郊战骨多。","阅事十年频俯仰，壮怀半世付悲歌。","迁延岁月师将老，杀贼曾无唤过河。"]},{"t":"鸣琴曲，次朱竹垞先生「听韩七山人弹琴」原韵","f":"古风","c":["我性嗜鸣琴，抱琴夜共宿。","琴宜近水与高楼，琴楼构在池西曲。","炉香袅袅弦初更，泉水流滩漱玉声。","少时变幻调重转，万壑松涛顷刻生。","海上移情历欲遍，蔽鲁龟山伤不见。","抑扬挥洒神自閒，手挥目送长空雁。","雁断衡阳声已悲，胡笳一曲倍凄其。","我有名琴含太古，断绞斑剥光陆离。","落指按弦吟注撞，清钟夜递来遥巷。","逸韵悠悠夜未央，幽音袅袅霜初降。","跌宕中间复寂然，万籁无声月在天。","渊明嗜好嵇生癖，趣味深尝十六年。","盟交愿与托终始，一生长伴閒园里。","晚晴抱向池前鸣，引出波中双金鲤。"]},{"t":"入金包里庄憩佃人家","f":"七言律诗","c":["层巇氤氲散午烟，潺潺流水下梯田。","数家联络依山坞，一径萦纡上岭巅。","犬吠有声樵客过，鸟啼随意野人眠。","扣门少憩茅檐下，村酒留宾不用钱。"]},{"t":"入横坑深山迷途，夜宿茅庵题壁","f":"五言古诗","c":["摄屐踏怪石，振衣度危磴。","水流花自开，引人欣入胜。","逶迤欲穷源，忽觉岩穴暝。","空山不见人，何处问行径。","松杉大十围，行倦此聊凭。","白云深复深，戛然一声磬。","寻声来芳庵，叩门行者应。","佛光映蒲团，老僧初出定。","留我宿禅房，三生喜可證。","更深山月高，清景惬幽兴。","何当脱尘鞿，同参最上乘。"]},{"t":"偕友游祖师岩赠莲汀上人","f":"五言律诗","c":["野竹环阶密，岩泉绕树流。","疏钟敲落月，冷榻卧清秋。","访胜僧能导，谈禅客且留。","参寥诗思好，试茗意悠悠。"]},{"t":"游青潭山","f":"五言律诗","c":["昼永岩栖静，逍遥意适然。","倚松观舞鹤，枕石听流泉。","树远笼烟没，云归让鸟先。","苍茫秋色里，独自下层巅。"]},{"t":"月夜泊官道","f":"五言律诗","c":["秋深泬㵳天，遥望空水连。","犬吠岭头月，舟冲波上烟。","朝鸡客惊起，村火人未眠。","岩下足幽趣，清钟摇枕边。"]},{"t":"金门溪晚归","f":"五言律诗","c":["秋晴行旅快，纵辔过沙陂。","绝壑归云早，平川落日迟。","鸦喧争树宿，马健逆风驰。","吟兴忽然动，微哦便得诗。"]},{"t":"本厅侯恩子荣太守六十寿诗 其一","f":"七言律诗","c":["觞祝兹逢耳顺年，遥遥花甲正周天。","身当老境筋骸健，名策清时福寿全。","袁守心田同佛子，邺侯气概拟神仙。","会看玉杖扶行稳，与宴欣符叟满千。"]},{"t":"本厅侯恩子荣太守六十寿诗 其二","f":"七言律诗","c":["华冑巍巍岂等閒，春官曾列鹭鹓班。","一麾出守歌千姓，万里晨昏到百蛮。","德可化顽龚渤海，智能镇静谢东山。","共称制锦真神手，昔日淳风喜渐还。"]},{"t":"次韵答白仲安明府「赏菊」作","f":"五言律诗","c":["最羡君高雅，何年共结邻。","诗情工写景，笔意善传神。","把酒常邀月，看花不在春。","能知閒淡趣，自是个中人。"]},{"t":"次韵答松潭广文「园中咏菊」","f":"五言律诗","c":["费尽经营计，才成满圃香。","黄疑橙累颗，白肖雁分行。","晚节欣佳色，平明爱淡妆。","一观珠玉句，累我兴难偿。"]},{"t":"次韵答苏昆山上舍「乞菊」","f":"五言律诗","c":["晚节无佳色，篱英放最繁。","忘忧供隐逸，适趣笑温存。","锦赛三春圃，芳孤九月园。","长公多兴事，既得复何言。"]},{"t":"九日偕叶松潭广文、陈性初茂才土地公坑登高即事 其一","f":"七言绝句","c":["携朋得得共登临，无数啼禽竞好音。","路转板桥重拾级，羊肠径绕白云深。"]},{"t":"九日偕叶松潭广文、陈性初茂才土地公坑登高即事 其二","f":"七言绝句","c":["危岩万仞瞰平阿，海甸秋清气候和。","一带云林环雉堞，望中城阙失嵬峨。"]},{"t":"九日偕叶松潭广文、陈性初茂才土地公坑登高即事 其三","f":"七言绝句","c":["回首儿时一刹那，雪泥鸿爪渐消磨。","构亭亲友今何在，独对西风起浩歌。"]},{"t":"九日偕叶松潭广文、陈性初茂才土地公坑登高即事 其四","f":"七言绝句","c":["乱插山花枕石眠，敢将落帽慕前贤。","醉来不管牛童笑，狂态随他到处传。"]},{"t":"九日偕叶松潭广文、陈性初茂才土地公坑登高即事 其五","f":"七言绝句","c":["长啸临风醉半醒，狂歌唱与座宾听。","此游不亚神仙乐，直把山亭作幔亭。"]},{"t":"九日偕叶松潭广文、陈性初茂才土地公坑登高即事 其六","f":"七言绝句","c":["题罢新诗兴未休，一声「去也」唱清讴。","山灵若不嫌奴放，携酒明朝订再游。"]},{"t":"剿禦会匪劳绩，加盐运使衔。恩重功微，诗以志愧","f":"七言绝句","c":["报国无才意却虔，头衔此日戴青天。","枕戈未遂澄清愿，拜命真惭鲁仲连。"]},{"t":"寄感","f":"七言律诗","c":["茫茫人海久浮沉，两鬓萧疏百感侵。","献策无才宜潦倒，耽诗有癖自呻吟。","斩魔剑钝情难断，结客囊空累更深。","安得携樽招隐侣，相将把臂入嵇林。"]},{"t":"香石山房煮茗写兴","f":"七言律诗","c":["扫地焚香俗念轻，翛然时见此心平。","诗宗白傅言多达，琴学嵇康韵自清。","澹泊家风梅与鹤，回环地势竹依城。","满园无限幽奇处，窃学骚人结构成。"]},{"t":"厅幕张君秋汀观潜园山水册索昼未果，爱慕心殷，常形齿颊。赋诗感赠","f":"七言律诗","c":["错爱如君愧不胜，通灵有笔遣閒凭。","原非米石承称赏，若寄桓厨必化腾。","巨眼一双殊阮籍，置身百尺拟陈登。","殷殷雅谊常铭感，此债思偿恐未能。"]},{"t":"书叹","f":"七言律诗","c":["落寞栖迟愧壮猷，凌烟事业已潜休。","持家苦被宏徵笑，无位甘凭邓禹羞。","赖有园林容懒拙，聊将讽咏遣烦忧。","胸中不尽佳山水，何日匡庐快浪游。"]},{"t":"俗讹叹","f":"五言古诗","c":["俗语传易讹，方言洵可嗤。","清晨来妇子，自谓娘与儿。","询渠来何故，云欲请「布司」。","此地非省会，其言实可疑。","儿谓母言误，系欲延「布师」。","兹语更莫解，盘问转支离。","嗫嚅重申告，被盗不知时。","昨日始觉察，寻踪叹已迟。","欲请「布师爷」，神灵为觅追。","厅幕无此姓，即有不在斯。","沉吟忽喷饭，憬然心已知。","乃系城隍庙，两庑六司随。","一司曰「速报」，显赫有威仪。","凡有被盗者，请祷无停期。","闻神在我家，半向致嗟咨。","方言讹相袭，俗语真匪思。","「速」字简截去，「布」「报」浑参差。","足见抄旧方，不可轻为医。","因讹而传讹，日久误愚痴。","然亦未足怪，曾闻杜十姨。"]},{"t":"与客谈乾草湖山景偶成","f":"五言律诗","c":["瘴重云封密，山高日出迟。","岩腰樵径险，岭脊戍楼危。","乱树缠长棘，深林叫怪鸱。","燐燐多鬼火，隐约夜阑时。"]},{"t":"秋夜述怀","f":"五言古诗","c":["『窃闻三十九，劳生已强半』。","此是坡公语，惊心发长叹。","叹我值其年，无成徒愒玩。","矧复遭丧亡，丧亡伤举案。","「关睢」赋「好逑」，调和琴瑟赞。","素性乐恬幽，高怀喜文翰。","照户无小星，房帏绝妒悍。","犹如影随形，尽日陪坐畔。","可叹结缡时，台疆际离乱。","兵燹复年荒，横流嗟浩漫。","加之二竖来，为灾骨中钻。","有时灾于齿，焦灼同炉炭。","有时灾于足，始痛终溃烂。","乃复灾于目，咫尺不能看。","如居土穴中，四堵皆昏暗。","如堕苦海中，茫茫无涯岸。","几至不欲生，心急莫能按。","幸赖闺中人，刻刻侍帏幔。","焚香祷天佛，叩头同捣蒜。","但期夫眼明，自甘减寿算。","至诚果感神，比理可一贯。","金■刮双睛，岩电时忽灿。","可怜伉俪情，三载同患难。","永愿相倡随，何期遽分散。","当此深秋时，连宵倍凄惋。","一纸隔阴阳，俨若千里判。","果能姗然来，念切心无惮。","世世为夫妇，誓词岂河汉。","髣佛听悲声，林风似呼唤。","凄怆不成眠，拥衾以待旦。"]},{"t":"感怀","f":"七言律诗","c":["骨肉频年痛别离，干戈满地欲何之。","清流本恐名难副，才士由来数总奇。","琴鹤遣怀聊结伴，园池藏拙且歌诗。","吾家况有孤山在，终老林泉更合宜。"]},{"t":"哭彭逊兰师","f":"五言古诗","c":["治任归去后，空忆幔亭晨。","毕世雄谈爽，平生率性真。","明经经学博，作赋赋编新。","笔阵降多士，书香继有人。","及门谁立雪，入室我书绅。","已圮灵光殿，难扶大雅轮。","徒然称沆瀣，竟敢诩荀陈。","赙奠余孤往，能禁泪满巾。"]},{"t":"遣怀","f":"七言古诗","c":["鹧鸪声里尽荆棘，几度欲行行不得。","辜负名山滞浪游，神情惨淡无颜色。","床头欲置少文图，触景生情频转侧。","嗟余生晚值时艰，关河万里悲风寒。","何时特出披云手，歼灭豺狼类屠狗。","王道平平汗漫游，贮满奚囊诗百首。","千寻峭壁落云烟，准备兔毫大如帚。"]},{"t":"月夜清吟","f":"古风","c":["露天翘首耸肩高，阁下曲池前。","幽花照水，嫩草含烟。","绕廊时觅句，爱月夜迟眠。","岩畔长松拂尘，桥头弱柳飞绵。","吟能变化诗称佛，家有园林境比仙。"]},{"t":"过青草湖有感","f":"五言古诗","c":["群峭渐丰肌，层峦皆没骨。","沮汝践溪毛，蒙茸披石发。","四顾尽芳荪，苍然欣秀越。","凋零曾几时，万绿来何突。","野草自无心，春风吹乱发。","中含造化机，乘势不能歇。","对此触我怀，低头频咄咄。","伤我同心人，一朝遽颓蹶。","华、扁难回春，千秋感存没。","祭扫罢归时，沾襟泪连滑。"]},{"t":"谭生行","f":"楚辞体","c":["谭生家近滕王阁，文酒笙歌恣欢乐。","轻掷珍珠买绿娥，高吹玉笛招黄鹤。","兴酣好作狭邪游，六博还挥十万筹。","囊金散尽不复惜，由来浪子难回头。","繁华转盼悲萧索，歌场几唱「莲花落」。","肯为饥驱重出门，远抵闽中事游幕。","铁板长歌海上来，耆卿到处绮筵开。","销魂重作扬州梦，落魄谁怜记室才。","轻靴窄袖自豪举，逢场肯演参军舞。","酒酣耳热起催花，当筵笑击三挝鼓。","白雪纷飞曲调成，银筝锦瑟停无声。","主人不语客不饮，如闻仙乐同移情。","閒来访我潜园里，郤生一见令人喜。","花晨月夕时过从，论交敢信成知己。","尊前忽听翻骊歌，送君南浦愁春波。","飘梗可怜游子苦，赠绨莫道故人多。","求名谋利都难遂，途穷转恨妻孥累。","一朝挈眷入吾门，当年张绪伤憔悴。","容颜异昔堪惊疑，踌躇未语生先知。","细诉别来不得志，贫侵病迫难支持。","形骸消瘦态衰老，深恐微躯同露草。","茫茫海内无知音，就化无如此地好。","我闻其语骇且怜，急开客座相留延。","閒居不使筹珠桂，佳日依然乐管弦。","诗酒盘桓将两载，膏肓二竖终为害。","身后能教碧玉随，膝前祗剩文姬在。","沧溟浩渺魂难还，骸骨何由归故山。","一抔新穴堆黄土，五夜空闺泣绿鬟。","娇雏转瞬年十七，为赋桃夭吾事毕。","九原相见庶无惭，一肩重负欣差释。","清明时节雨潇潇，自倾杯酒墓门浇。","回思旧事泪痕湿，翻成楚词将魂招。","我为谭生歌一曲，魂兮若在暗中哭。","灵风捲地是耶非，墓畔白杨飞蔌蔌。"]},{"t":"虹贯月楼为先世藏书处，瞫褫富繁，日久多致残蚀。修葺之馀，感赋此诗","f":"七言律诗","c":["贯虹楼上旧藏书，充栋横陈富五车。","乱部柳州屯野马，倒流苏海簇蟫鱼。","多同鲁鼓亡章法，恰肖秦篇拾烬馀。","阅月晴窗勤检葺，已从玩愒悔当初。"]},{"t":"读家和靖公「书孤山隐居壁次」韵，题青草湖孤山别业","f":"七言绝句","c":["山水未深猿鸟少，幽清人境便为居。","虽睽天竺三千里，此亦孤山可结庐。"]},{"t":"有感","f":"七言律诗","c":["杀贼无人唤渡河，疮痍满目苦干戈。","可怜竖子成名易，太息英雄失路多。","兴到逢场聊作戏，忧来对酒每当歌。","数奇辜负封侯相，四十华年付逝波。"]},{"t":"诸子侄入塾，题书斋南壁。并奉正杨明浦先生 其一","f":"五言律诗","c":["璃窗四壁张，清趣味尤长。","风带书声朗，花资墨气香。","作文师永叔，下笔羡江郎。","此塾诚幽爽，阴阴护翠篁。"]},{"t":"诸子侄入塾，题书斋南壁。并奉正杨明浦先生 其二","f":"五言律诗","c":["入塾年亲送，尊师藉训谟。","最难唯际遇，切勿浪功夫。","机慧烦先导，专勤亦要途。","破蒙三载矣，诗礼重庭趋。"]},{"t":"倪敏堂参戎四月十四日病殁于台镇中营任内，惊闻讣音，作诗哭之","f":"七言律诗","c":["蓦地惊闻到讣音，台阳又见将星沉。","朋情金石君为最，交谊芝兰此独深。","被谤马援冤刺骨，难封李广痛铭心。","伏波横海功何在，举目诸孤泪不禁。"]},{"t":"悲歌行","f":"七言古诗","c":["钱塘筮仕为西湖，前辈风流慕白、苏。","吾家况有栖幽处，孤山踪迹老梅逋。","嗟余少日性莽鲁，六岁伶仃痛失怙。","结纳少友事嬉游，一班牙爪利如虎。","王母、寡母双倚闾，几度呼来复绝裾。","暗中痛切泪凝枕，我家生儿破我车。","三世伶仃寡弟昆，忍心将毋置之死。","易子而教古有方，割将块肉托舅氏。","舅氏部曹值北行，余乃从之游帝京。","自觉一朝身逸乐，离家那顾泪纵横。","乘风破浪意豪放，铜琶铁板江东唱。","旗山、鼓山豁两眸，仙霞峻岭摇鞭上。","北马南船快骋游，小阳春日入皇州。","生来佚荡难驯伏，舌烂生公不点头。","虎坊桥畔交俦伍，驰毬击剑金挥土。","菊部欣聆蓟苑歌，犁园饱看罗门舞。","泰山高今祖帐设，芦沟桥水添呜咽。","但云勉我弧先行，不道从兹是死别。","行尽燕南遍鲁、齐，騑騑驷牡无停蹄。","风尘澒洞人如鬼，渡过黄河日已西。","日西旅舍同沽酒，一路风光数诸口。","扬州明月、姑苏台，洞庭群峭、西湖柳。","建河滩险魂欲销，荒陬除夕倍无聊。","洪山桥畔蒲帆落，满城灯火正元宵。","因之动我浮华兴，顾曲徵歌气未定。","黄金未尽不言旋，多情犹把南楼凭。","叶翁帆海往复回，沙哥祖道送行杯。","七月之秋犹未望，鲸波一舸赋归来。","举家狂喜牵我衣，王母扶姑颤巍巍。","低头下拜天性见，满门喜极转嘘欷。","北堂择吉命成婚，贺客盈堂吊在门。","王母抱孙□抱子，临终有语愿勿谖。","三载杜门躬守制，羸叔劬劳持家计。","道光丙午桂之秋，羸叔沉痾旋去世。","折薪肯搆一肩挑，有弟茕茕惜嫩苗。","始悟无学难自立，一编三绝暮连朝。","昂藏年几三十岁，妻妾死亡竟相继。","慈闱弃养亦同时，搥胸几绝痛长逝。","天昏地惨日无光，欲向泉台觅阿娘。","况复惠连春草恨，死者已矣存者伤。","就中一事倍凄其，予年卅六始得儿。","举眼方无伯道叹，回头竟抱元驹悲。","未几家室遘三丧，十年春梦徒渺茫。","春梦渺茫今暂醒，琴诗陶写赖园亭。","强颜又作詹家婚，弩末犹能中雀屏。","莫道膏肓贪泉石，惭处乡闾乘下泽。","萧萧风木悲重兴，捧檄难追毛义迹。","衣紫腰金念已收，觅水寻山兴未休。","何时得识匡庐面，又造飞来峰上头。","不图遍地皆狼豕，海内于今多事矣。","方、罗时命既同悲，崔、卜功名胡足齿。","子野朝朝唤奈何，平生动作辄坎轲。","壁图空挂运甓苦，愁来弹铗哭还歌。","但期郭、岳两忠武，炙手太平立可睹。","携琴抱鹤孤山行，补种梅花三百树。"]},{"t":"赠戴华庭守戎","f":"七言律诗","c":["待人接物总和平，韬略功深变化生。","联辔绿营时较射，当筵红烛夜谈兵。","雕天风劲弓频响，马埒春回草乍萌。","名将襟怀儒者气，海邦从此赖干城。"]},{"t":"次吴鉴堂二尹「感怀」用连环体原韵二首 其一","f":"七言律诗","c":["满城风雨近重阳，旧恨新愁总系肠。","陶令清吟惟遣兴，司勋绮句岂鸣狂。","绝无势利招人妒，更有琴书累我忙。","几度欲眠眠未得，更深渐觉竹窗凉。"]},{"t":"次吴鉴堂二尹「感怀」用连环体原韵二首 其二","f":"七言律诗","c":["更深渐觉竹窗凉，话到平生倍可伤。","酬酢敢分青白眼，蹉跎强半黑甜乡。","人情此际嗟刁险，世事于今叹孔章。","偏是催租无计却，满城风雨近重阳。"]},{"t":"偶成","f":"七言律诗","c":["回肠日日为愁牵，排遣唯将讽谕编。","地免兵烽洵乐土，身居园墅即真仙。","滇、黔到处多冰解，吴、楚谁家得瓦全。","独有东瀛偏获福，须多为善答苍天。"]},{"t":"青草湖晚归","f":"五言律诗","c":["暧暧环村树，依依出谷烟。","好山皆蕴藉，流水亦周旋。","鸟散长空尽，花开夹径妍。","岭巅回首望，夕照下平川。"]},{"t":"晓晴散步遣怀","f":"古风","c":["连夜淋漓春雨足，挹户林光照晴旭。","杨柳墙头垂嫩青，芭蕉窗外展新绿。","夹廊暴茁碧箖箊，绕槛争开红踯躅。","满园草木尽欣荣，雨力能资地肥沃。","朝来屐笠自周巡，遣怀缓度池西曲。","短篱羃䍥牵牛萝，小圃葱茏长婴粟。","花梢雨点叶留珠，水上荷擎波漾玉。","閒园卅亩堪寄情，修竹千竿可医俗。","小年日日足徜徉，何必夜游更秉烛。","列架图书数万篇，得意欣然自藏录。","隐囊尘尾恣清谈，诗卷琴经与棋局。","吾侪藉此寄天真，何必营谋伤窘促。","矧今满目尽烽烟，神州扰扰争蛮触。","寥寥永日卧山寮，牢愁拟把「离骚」续。","东瀛此际比天堂，散诞优悠无缚束。","为读移文居北山，肯因献赋出西蜀。","君不见安閒毕世香山老，祗缘知命无贪欲。"]},{"t":"戒严","f":"七言律诗","c":["誓众登陴气若虹，腰间宝剑玉珑璁。","戒严已赖成城志，禦敌还凭背水功。","慷慨请缨差可拟，笑谈挥羽敢从同。","王师指日从天降，会见奇勋著海东。"]},{"t":"得徐树人师抚闽信，赋此志喜","f":"七言律诗","c":["乾鹊连朝噪不停，邮书遥达好音听。","东瀛感德怀甘雨，南国倾心仰福星。","日丽蜺旌看建节，春生马帐记传经。","更欣横海楼船集，一旅能消孽气腥。"]},{"t":"闻警戒严作 其一","f":"七言律诗","c":["腥风吹海啸长鲸，小丑跳梁听横行。","毒雾迷漫沉战垒，大星黯淡落空营。","甲溪扼险成天堑，丁汛分防卫石城。","莫道黄巾氛甚恶，么魔蝼蚁不难平。"]},{"t":"闻警戒严作 其二","f":"七言律诗","c":["揭竿斩木势张鸱，深虑难图蔓草滋。","四野闻声多响应，孤城如卵独支持。","门严锁钥防私谍，户奋耰锄起义师。","有备不惊风鹤警，躬擐甲冑日登陴。"]},{"t":"团练","f":"七言律诗","c":["义旗高建奋先声，唇齿相依共结营。","自许孤忠能报国，还期众志果成城。","连乡各为身家计，协力原推子弟兵。","守望祗期吾圉固，瞬看渡海有飞旌。"]},{"t":"兵饷支绌，劝输感作","f":"七言律诗","c":["肉食何人有远谋，可怜未雨失绸缪。","一朝闻警忙擐甲，半夜量沙枉唱筹。","中泽嗷鸿声倍苦，孤城掘鼠事堪忧。","男儿莫作守钱虏，纳粟曾闻卜式侯。"]},{"t":"大甲土堡失守，贼势将欲北趋，义勇力战攻复之，扼溪而军，堑城始能安堵。闻捷喜赋","f":"七言律诗","c":["一军血战扼咽喉，贼势终难犯上游。","坚壁气能通鹿港，扼溪界似划鸿沟。","四郊义旅兴传檄，千里兵机决运筹。","瞬见鲸鲵就诛戮，酒□大笑看吴钩。"]},{"t":"丁述庵观察督师剿匪至淡，赋呈","f":"七言律诗","c":["横海旌旄驻水滨，临淮壁垒一时新。","东瀛建节来儒将，北道输粮作主人。","制梃民皆怀旧德，挥戈军定扫妖尘。","执殳我愿前驱作，报国酬知敢惜身。"]},{"t":"癸亥元旦踏春自东城归，与陈榕士、叶松潭、家薇臣坐谭，首唱一律","f":"七言律诗","c":["下元甲子数将周，又到清时景运头。","四野绿畴忻岁首，一轮红日豁晴眸。","关河完固驱狼豕，刀剑销残买犊牛。","我是西湖閒散吏，几时同泛木兰舟。"]},{"t":"叠元旦前韵示陈、叶诸君","f":"七言律诗","c":["干戈扰攘岁云周，百计焦劳几白头。","历过功名堪冷齿，阅来世事愧昏眸。","利心皆是争趋鹜，人意难如任唤牛。","揽辔澄清原夙愿，中流敢后祖生舟。"]},{"t":"再叠元旦前韵","f":"七言律诗","c":["图忠体孝两难周，但得无惭在念头。","誓众无须呼祖臂，知人毕竟善垂眸。","戈声昼静閒弓马，剑气宵清射斗牛。","此日淡疆成乐土，抚绥尚赖济川舟。"]},{"t":"送陈榕士归嵌城，即次「留别」元韵二首 其一","f":"七言律诗","c":["廿载芳名贯耳知，于今霜鬓已离离。","嗟予废学惭中令，羡子高才媲左思。","腹有诗囊凭啸咏，眼看墨盾佐驱驰。","从戎莫道书生气，下马当先露布移。"]},{"t":"送陈榕士归嵌城，即次「留别」元韵二首 其二","f":"七言律诗","c":["几回欲别复攀留，才渡重洋又买舟。","对菊定增他日泪，脱刀暂解别时愁。","秦川地胜忻随侍，华岳峰多快壮游。","幕府从兹凭借箸，渊源曲逆本封侯。"]},{"t":"春郊即景 其一","f":"七言绝句","c":["沿村萝卜白于霜，油芥花多匝地黄。","开遍夭桃与秾李，春山如笑亦如妆。"]},{"t":"春郊即景 其二","f":"七言绝句","c":["红塍十里尽平坡，绿树青山野趣多。","行过村南与村北，好风处处送秧歌。"]},{"t":"春郊即景 其三","f":"七言绝句","c":["啁啾村学草堂前，咕哔声中一叟眠。","赤脚蒙童三五个，案头犹倚牧牛鞭。"]},{"t":"春郊即景 其四","f":"七言绝句","c":["惊人妇女笑言哗，紫面红唇半黑牙。","最是村庄异妆点，鬅鬙乱插一头花。"]},{"t":"春郊即景 其五","f":"七言绝句","c":["如虹日脚下平川，无数樵歌后复前。","我亦笋舆回去缓，舆夫齐唱「鹧鸪天」。"]},{"t":"春郊即景 其六","f":"七言绝句","c":["廿里芳原去路赊，环村老木郁槎枒。","牧童归晚不吹笛，跨著閒牛数暮鸦。"]},{"t":"初晴，祭扫青草湖有感，归成四律以写哀衷 其一","f":"七言律诗","c":["一别音客两渺茫，不归西土定仙乡。","生前枉绾同心结，死后难寻入梦香。","石冢寒蛩迷乱草，墓门啼鹧苦哀杨。","归来笑语人何在，寂寞灯前意转伤。"]},{"t":"初晴，祭扫青草湖有感，归成四律以写哀衷 其二","f":"七言律诗","c":["秋雨梧桐叶落时，凄凉枕簟最萦思。","雕栏月上追携手，宝镜尘生忆画眉。","作赋江淹常写恨，多情宋玉为兴悲。","只今凄寂妆楼下，深院无人属阿谁。"]},{"t":"初晴，祭扫青草湖有感，归成四律以写哀衷 其三","f":"七言律诗","c":["临别殷勤重寄词，一番叮嘱一番悲。","玉箫誓切多生愿，金屋缘悭隔世痴。","三叠琴心妻即友，两行珠泪母伤儿。","不堪追忆前时事，对酒看花痛不支。"]},{"t":"初晴，祭扫青草湖有感，归成四律以写哀衷 其四","f":"七言律诗","c":["在地愿为连理枝，孜孜私语鬼神知。","死而有识应留憾，病到无名倍可悲。","伤逝惠连留短句，悼亡潘岳费新词。","数年别泪知多少，和墨频吟薤露诗。"]},{"t":"夜醒有感","f":"七言律诗","c":["烛影摇红月影低，唾壶击缺气如霓。","丁年壮志空弹铗，午夜雄怀数舞鸡。","未得请缨狂寇系，何期磨盾捷音题。","关中转饷今非易，功狗功人自可稽。"]},{"t":"山阴陆少海，浙东名下士也。每过从潜园，潜园待之逾于常客。促膝论文，口占以赠","f":"七言律诗","c":["腹笥便便学问充，机、云想克嗣宗风。","笔锋秀颖兰亭近，文境恢奇禹穴通。","略有牵情方杜牧，竟无识字类扬雄。","醇醇儒者彬彬质，赏曲聆音自不同。"]},{"t":"内湖道中","f":"七言律诗","c":["日暖风和正插田，嫩苗遇雨倍芊芊。","营巢鸠拙呼雌共，放軏牛閒带犊眠。","四壁云烟供啸傲，一村泉石足流连。","何时结屋双溪畔，抱鹤携琴拟散仙。"]},{"t":"狮头崖高望","f":"七言律诗","c":["梯田级级径盘盘，立马层巅望眼宽。","茂树千章云外出，扁舟一叶浪中攒。","觅鱼沙鸟栖无定，茹草村羊饱自还。","避雨茅亭时少憩，松声潇飒似鸣滩。"]},{"t":"过陴角庄","f":"七言古诗","c":["今来时异昔来时，满目萧条痛乱离。","碧海那能钩桂魄，蓝田何处觅琼枝。","神伤故里鹦哥唤，泪洒空山杜宇悲。","江令有情还赋恨，徐姬无命为情痴。","生前意态堪追慕，别后容光费梦思。","回首墓门斜照外，松楸谡谡影参差。"]},{"t":"薄暮过新庄山脚","f":"七言律诗","c":["芳塍历历径平沙，修竹柴门野老家。","牛背数声村笛远，渡头十里酒旗斜。","晴云曳白归春岫，落日摇红幻暮霞。","此际吟情溪上好，閒看田父话桑麻。"]},{"t":"赠白少溪司马","f":"七言律诗","c":["青衫此日著瀛东，司马风流与众同。","几卷歌词流倒峡，一枝画笔健生风。","莺花逸趣消行旅，诗酒馀情话退公。","珍重年来亲炙意，微名已入品题中。"]},{"t":"有感","f":"七言律诗","c":["于今世事总难吁，糜烂尤深越与吴。","为国释嫌唯蔺子，毁家纾难只于菟。","君臣义重宜同晓，盗贼仇深切共诛。","剩有荆卿囊剑在，馀腥犹带血模糊。"]},{"t":"感怀","f":"七言律诗","c":["频年筹饷复筹兵，窃愧中流砥柱名。","即日论功应进战，前时破敌已先行。","乐羊无过频遭谤，召虎全师岂擅征。","鼠辈直宜高阁束，免教房琯累书生。"]},{"t":"书叹 其一","f":"七言律诗","c":["半世支离愧此生，咨嗟尽日困愁城。","交情碌碌少知己，歧路迢迢几失声。","拨乱有心遭嫉谤，敛财无术懒逢迎。","小园能否容肥遁，愿藉村歌颂太平。"]},{"t":"书叹 其二","f":"七言律诗","c":["非武非文疣累同，经年跃马愧从戎。","毁家不作宏微计，策杖难追邓禹踪。","戚戚襟怀伤永日，堂堂旗鼓想英风。","丈夫快意昆崙夜，未歇笙歌已立功。"]},{"t":"书叹 其三","f":"七言律诗","c":["连朝咄咄自书空，蠖屈胡能气若虹。","望重筹谋方有济，权轻韬略总无功。","云山何处堪栖隐，海甸于今尚扰戎。","回忆去年当此日，堕鸢跕跕炎蒸中。"]},{"t":"书叹 其四","f":"七言律诗","c":["成败由天岂易知，悠悠浩劫孰能移。","枕戈待旦眠难稳，运饷量沙势不支。","制胜何曾胸有竹，担忧徒见鬓成丝。","相如已去廉颇老，将帅中原少白眉。"]},{"t":"偕诸友人西池泛月，分韵咏洞箫得「城」字","f":"七言律诗","c":["狂歌常作不平鸣，和我阳阿激楚声。","孤鹤唳空音断续，老龙吟水韵凄清。","道人筠管高低奏，学士匏樽慷慨倾。","共泛西池今夜月，不堪回首阖闾城。"]},{"t":"予四十有三初度日，家薇臣以诗见赠。步原韵答之","f":"七言律诗","c":["落落生平少见长，况当狼豕遍台疆。","广交北海君投辖，团练东瀛我滥觞。","薄有微劳传梓里，屡承高誉锡华章。","读来雅颂颜尤赧，无善何当费赞扬。"]},{"t":"六言绝句四首 其一","f":"古风","c":["高拟玉皇案吏，灵山会上因缘。","瞰破人情险恶，于今愿作顽仙。"]},{"t":"六言绝句四首 其二","f":"古风","c":["横江一鹤高飞，下看鹭鸥游戏。","除却觅食閒眠，那识仙禽意气。"]},{"t":"六言绝句四首 其三","f":"古风","c":["怪石清流回绕，奇花瘦竹回遭。","有此閒情不领，肯与傀儡争高。"]},{"t":"六言绝句四首 其四","f":"古风","c":["无数含沙射影，追随牛鬼蛇神。","莫道凭空说怪，红尘吾见其人。"]},{"t":"游内湖庄雨后偶成 其一","f":"七言绝句","c":["南山骤雨北山晴，半树犹馀夕照明。","独向小桥閒立处，倚栏得得听泉鸣。"]},{"t":"游内湖庄雨后偶成 其二","f":"七言绝句","c":["晴云初见湿云忙，天外虹腰耀眼光。","渔艇二三垂柳下，迥桡打桨唱「沧浪」。"]},{"t":"游内湖庄雨后偶成 其三","f":"七言绝句","c":["泉声㵐㵐树苍茫，笠屐前村趁晚凉。","行过小篱频驻足，谁家兰蕙正芬芳。"]},{"t":"偕友人剑潭品茶","f":"古风","c":["怪石嵚?俯水涯，垂藤联络树参差。","花梢山色含晴霭，雨后溪光漾暮霞。","半晌吟蝉添野趣，数声清笛出渔家。","披襟赤足苔矶上，坐对沧浪共品茶。"]},{"t":"自双溪归，复泛剑潭","f":"七言律诗","c":["暗川如画入眸赊，百转清流曲复斜。","岩畔风微修竹静，松巅日冷片云遮。","穿林野蝶随樵担，掠水鱼鹰避钓槎。","我爱澄潭好烟景，寻幽几度欲移家。"]},{"t":"入南港山庄口占","f":"五言古诗","c":["孤村重掩里，风趣喜无涯。","水碓时舂麦，山园遍种茶。","牧童牛代步，渔父艇为家。","岭峻云巢树，泉流涧漾沙。","乱松蟠石偃，一径趁岩斜。","薄暮耽临眺，行吟不觉赊。"]},{"t":"雨后移船泊新庄港","f":"七言律诗","c":["喧哗万叶扰吟脾，顷刻阴晴变幻奇。","云雾渐开山露处，虹霓初见雨残时。","一峰陡立天撑柱，众水争奔壑作池。","此际轻桡溪上去，乘凉不厌放船迟。"]},{"t":"剑潭晚泛","f":"七言律诗","c":["溪南溪北遍桑麻，极目芳塍稻未花。","野渡人归樵担满，岩阿客散鸟声哗。","苍茫云树崖前寺，杳霭烟村竹里家。","共对雨馀好风景，澄潭如镜泛轻槎。"]},{"t":"内湖庄登眺口号","f":"七言律诗","c":["阴阴夏木听啼莺，历落云峦自送迎。","山欲抱村先作势，水将下濑始闻声。","千盘萝磴攀登险，十里芳畴远望平。","陡立层巅长啸起，胸怀慷爽俗尘清。"]},{"t":"自内湖归，道中题壁","f":"七言绝句","c":["倦游归去意如痴，岩谷何曾有色丝。","寄语是乡诸父老，种花且漫种胭脂。"]},{"t":"南征八咏 其一 师出香山途中作","f":"七言律诗","c":["吹篴平明按队行，旌旗映日向南征。","斩蛟胆气豪看剑，汗马功名壮请缨。","社勇练成弓箭手，军心奋起鼓鼙声。","釜鱼穴蚁终诛灭，何事潢池敢弄兵。"]},{"t":"南征八咏 其二 营山脚庄，夜望贼垒作","f":"七言律诗","c":["灯火如星帜若云，眼中蝼蚁尚纷纷。","三申平日严师律，一战明朝扫寇氛。","背水宜排韩信阵，撼山难犯岳家军。","料他破胆将宵遁，班马声喧彻夜闻。"]},{"t":"南征八咏 其三 一战获胜，进攻葭投村，破之","f":"七言律诗","c":["鼓声雷动阵云浮，破竹长驱队不收。","拔帜一军雄背水，用矛三刻壮逾沟。","焚巢竟使枭群散，入穴真能虎子求。","夺险料应寒贼胆，降幡瞬见竖城头。"]},{"t":"南征八咏 其四 十一月初一二鼓，所部全军过大渡，冒险疾趋。彰城内应外攻，奋勇争先，随即克复城池，闻鸡初唱。止寅时二刻也","f":"七言律诗","c":["衔枚夜半越阴平，冷雨寒风扑面迎。","箐密鸱鸮啼类鬼，途危草木动疑兵。","行军雅比龙骧壮，入穴居然虎子坑。","恍似鹳鹅行雪夜，蔡州一鼓报功成。"]},{"t":"南征八咏 其五 初三日，全军入彰化城，呈丁述庵廉访、周子玉主政","f":"七言律诗","c":["屏息衔枝枚疾趋，惊逃蟊贼尚糊涂。","楼船蓦地来王浚，金鼓从天降亚夫。","再岁相持同伐魏，经旬克捷笑平吴。","疮痍满眼堪嗟悼，全赖诸公善后图。"]},{"t":"南征八咏 其六 傍晚登西城楼感述","f":"七言律诗","c":["极目烽烟接远苍，哀声几处断人肠。","云含杀气迷征旆，沙逐腥风过战场。","四野荒庄同陆氏，满城废屋类昆阳。","抚民但愿来阳寇，恤典顿邀降建章。"]},{"t":"南征八咏 其七 凯旋大甲道中作","f":"七言律诗","c":["灵夔竞歇鹗争兴，金镫声中日乍升。","到处逢迎笳鼓奏，逢场作戏士商腾。","匡时有志缘知义，拨乱犹人敢曰能。","扫尽妖氛归去后，此心依旧玉壶冰。"]},{"t":"南征八咏 其八 回军将入竹堑城作","f":"七言律诗","c":["亲友何劳远出迎，悠悠一片管弦声。","全军甲冑归戎伍，夹道衣冠迓凯兵。","鼍鼓□鸣山岳壮，云麾招飐海天晴。","回时制就「南征赋」，长为熙朝颂太平。"]},{"t":"寄怀周子玉部郎","f":"七言古诗","c":["西泠名士周公瑾，书船画舫终难隐。","乍观才略著遐荒，草有声华传禁近。","崇山大老最怜才，名流物色从尘埃。","裴相新道崔湜坐，狐公东阁玉溪陪。","羡君才气本横逸，纵论雄谈常扪虱。","撑肠富有五车书，运腕力扶一枝笔。","是时我师正朝天，携往长安看画日。","典册曾希司马工，驰书更羡枚皋疾。","驱车复出皇都门，馀子纷纷安足论。","克日笋舆指闽峤，绿榕阴接荔阴繁。","繁阴中有越王宅，诸侯幕内为宾客。","乌石山前春酒醲，江瑶、荔子日三百。","剑池玉尺瓣香亭，昌谷囊中多古迹。","终朝据案惜分阴，论衡拟就平南策。","是时海外屡徵兵，台疆鼠子犹纵横。","如君韬略本兼著，壮怀正合请长缨。","乘风一夕破鲸雾，瞬息三山渺回顾。","半肩行李竹城来，相携一笑浑如故。","臭味芝兰意气投，当筵借箸为筹布。","述安廉访我召公，谓予一臂堪相助。","君也赏识□倍拳，有心携我上凌烟。","平生气概重然诺，请君且著祖生鞭。","椎牛誓众向南发，马蹄风疾无留连。","一旦闻予到尺咫，联营将弁皆欢喜。","已教大师待留餐，更贺监军迎倒屣。","谋定同君虎穴探，执殳竟向前矛徙。","葭投一战逆魂飞，当道老熊立披靡。","积年天堑一宵平，奔鼠么魔若狼豕。","彰邑城头羽扉挥，东北西南尽解围。","连镳固欲台南去，转饷无方乃告归。","归时日日思良友，琢句论文数欧九。","君虽隔地自同情，说项推袁不离口。","频闻画策中机宜，歼厥巨魁灭群丑。","迩日欣看入告章，颜色腰间悬紫绶。","何时返旆竹城来，蓬门端得为君开。","杨柳画桥并钓艇，梅花书屋啸吟台。","吟台幽处琴樽设，十日平原肠更热。","长啸高歌召鬼神，案上铜壶扣欲缺。","眼前世事任况净，何暇与人争论列。","我有心愿人不知，所愿无妨为君说。","随君一棹入榕城，陪向程门同立雪。"]},{"t":"哭曾籋云先生 其一","f":"七言律诗","c":["命宫磨蠍因儒冠，入地应知瞑目难。","弟子招魂悲宋玉，才人落第痛方千。","一生潦倒愁拚酒，两字「清高」定盖冠。","海内知音今有几，伤心不忍抱琴弹。"]},{"t":"哭曾籋云先生 其二","f":"七言律诗","c":["襟怀卓荦步蹁跹，文酒相陪二十年。","下笔千言词亹亹，撑肠万卷腹便便。","交情韩、孟能居左，才藻何、刘肯让先。","为检遗珠寿梨枣，九泉如觉料怡然。"]},{"t":"南征纪事","f":"七言律诗","c":["日闪旌旗小队行，前锋鼙鼓振威声。","招降喜用攻心策，剪助先攻犄角营。","破竹一军成胜势，衔枚半□出奇兵。","得他虎子须探穴，入蔡功从冒雪成。"]},{"t":"甲子元日，酒筵中示陈榕士、叶松潭、郑贞甫茂才诸君暨舍弟若村","f":"七言律诗","c":["旭彩瞳瞳照绮筵，花枝池上弄晴妍。","人逢甲子更新运，地息兵戈胜旧年。","筹饷免为愁里客，衔杯且效饮中仙。","诸君已具匡时藻，纶綍旋看降日边。"]},{"t":"元宵延陈榕士、叶松潭、郑贞甫茂才、家薇臣上舍宴赏龙灯烟火诸戏，竟为风雨所阻，不胜懊闷。漫成一律，并示诸君子","f":"七言律诗","c":["阴雨寒风日夜摧，良宵灯月费徘徊。","火龙得水因潜避，银树逢春竟不开。","是处鞦韆虚院落，几家歌舞罢楼台。","清斋寂坐添惆怅，空负多君作赋才。"]},{"t":"周子玉部曹军务告竣后告归榕省，送别二首 其一","f":"七言律诗","c":["处事交人出自然，姿神慷爽致翩翩。","胸中兵甲希前哲，海外经纶继昔贤。","子骏来途随降福，班生归路俨登仙。","襜帷已历台疆遍，载道芳名到处传。"]},{"t":"周子玉部曹军务告竣后告归榕省，送别二首 其二","f":"七言律诗","c":["才经聚首顿离群，执手踌躇袂忍分。","子比晋卿真似日，我如吏部愿为云。","才情契重诚知己，道谊交深独有君。","飞鹭亭前惆怅甚，何时剪烛再论文。"]},{"t":"送陆少海往郡城就馆","f":"五言律诗","c":["驿路慎风霜，嵌城乐事长。","诗书常据案，花月偶逢场。","作客名争羡，閒居业虑荒。","有人劳引领，珍重勿相忘。"]},{"t":"金山面平冈口号","f":"五言律诗","c":["芳草遍萋萋，林梢绿渐齐。","云屯平楚失，野阔众山低。","乱鸟栖牛背，长坡快马蹄。","岭头时小憩，日影已倾西。"]},{"t":"青草湖祭扫口号","f":"七言律诗","c":["冈峦匼匝水回萦，野鸟山花到处迎。","溪上烟云开远景，岩阿松竹自长生。","登临地胜供游眺，感慨诗多见性情。","太息吹箫人葬处，年年唯有子规声。"]},{"t":"淡文山留宿佃屋，马上口占","f":"七言律诗","c":["马蹄风疾步踉跄，长啸扬鞭兴欲狂。","远水波澄如疋练，高山云截肖平冈。","炊烟历历浮春树，返照匆匆下晚堂。","度过斜陂田屋近，四围岚气倍苍茫。"]},{"t":"自大坪庄晚归口佔","f":"七言律诗","c":["夏木悬崖万叶繁，平畴俯瞩遍烟村。","云移林影封岩屋，山趁溪流出海门。","极浦一轮红落日，接天十里绿平原。","独行始觉归途远，新月如钩色尚昏。"]},{"t":"过头分庄","f":"五言律诗","c":["山明空翠绕，水秀活流长。","斸土培新笋，编茅护嫩秧。","门幽知客少，村寂正农忙。","何处书声朗，林门隐学堂。"]},{"t":"近接移知，以克彰微芳，蒙上恩赏加布政使衔。三月十二日，望北叩谢恭纪","f":"七言律诗","c":["一朵红云下阙廷，九重恩重永心铭。","红光爵晋珊瑚顶，华采冠加翡翠翎。","既少勋劳酬厚泽，更无善誉答先灵。","崇朝北望头频叩，霭霭炉烟满袖馨。"]},{"t":"晓晴由霄里过桃园道中，小憩佃人家","f":"七言律诗","c":["崇朝雨过见晴晖，土脉膏深笋蕨肥。","黄鼠倒悬瓜蔓走，乌鹑斜掠稻花飞。","几家村坞流如带，数处陂堤树作围。","每到此间留恋甚，云峦万叠对柴扉。"]},{"t":"上大姑嵌观音亭，马上口号","f":"七言律诗","c":["马头阵阵起浮云，履险临深一径分。","急濑横流无定处，顽山乱叠不成文。","人争野渡滩将雨，猿啸阴箐昼欲曛。","翘首苾刍重拾级，巑岏屹立向溪濆。"]},{"t":"四十初度感赋","f":"七言律诗","c":["桑弧蓬矢志空存，霜雪惊看两鬓痕。","手板懒持销宦兴，头衔宠赐感君恩。","性情自觉难谐俗，身世惟宜老灌园。","四十华年弹指过，蹉跎如此复何言。"]},{"t":"初晴艋溪小泊","f":"七言律诗","c":["绕峡穿崖曲折行，朦胧旭日弄新晴。","云埋林麓山家隐，雨漫溪流水道平。","沃野青黄禾半熟，沿堤斑驳笋初生。","吟航小泊垂杨下，欹枕篷窗听语莺。"]},{"t":"入青潭口占 其一","f":"五言律诗","c":["蒙葺萝径远，数里过桥东。","罗鹊閒林叟，捞虾闹涧童。","藤修篱罥绿，瓜熟架悬红。","扫石客孤坐，迎眸尽化工。"]},{"t":"入青潭口占 其二","f":"五言律诗","c":["溪流千折转，云壑万重深。","古寺穿危磴，孤村隐茂林。","山幽无瘴气，地僻有滩音。","偃息长松下，跏趺复鼓琴。"]},{"t":"由观音山晚归，过栖云寺","f":"五言律诗","c":["诘曲度芳陂，岩阿拾级迟。","看山凭款段，倚树听流离。","花气晴频送，岚光暝忽移。","荼■能好客，数里尚追随。"]},{"t":"剑潭偶成","f":"七言律诗","c":["携筇拾级向高坡，纵目情幽步不颇。","群巘如飞争拱寺，澄潭虽满不兴波。","林间樵径穿岩远，水上鱼家傍竹多。","我爱系船当夏夜，清钟萦榻月浮波。"]},{"t":"双溪醴泉窟晚兴","f":"五言律诗","c":["薄暮快披襟，风蝉断续吟。","树交阴涧冷，云拥晚山深。","好月临幽壑，流泉响隔林。","逍遥盘石坐，煮茗复鸣琴。"]},{"t":"入内湖山","f":"五言律诗","c":["乱流奔濑急，仄径入山多。","榕老根盘涧，门低屋挂萝。","夕阳明野树，晴翠袭岩阿。","鴶鵴声何处，随风似咏歌。"]},{"t":"系船登石岩，烹茶晚眺","f":"七言绝句","c":["绿树阴浓处处蝉，溪山如画晚晴天。","烹茶趺坐西岩上，閒看遥村起暮烟。"]},{"t":"登栖云岩，偶晤家琴樵茂才题壁","f":"七言律诗","c":["舣棹寻幽到上方，故人邂逅永公房。","蝉声时趁钟声远，书味应兼道味长。","四壁风骚留草字，一区水石佔梅香。","评茶坐话苔矶久，岩畔归云已夕阳。"]},{"t":"艋川登眺","f":"七言律诗","c":["溪流浩淼势争奔，狮象交牙锁海门。","沃野辟成香稻界，群峰环护绿篁村。","楼台傍岸闾阎壮，樯楫迷津贾客喧。","别有幽栖山水趣，江南而外漫同论。"]},{"t":"哭吟村弟","f":"七言律诗","c":["骨肉凋残祚已衰，雁行中断更伤悲。","九原相见方知父，一病难延为忌医。","踽踽吾身嗟独在，茫茫天道苦无知。","聪明福命兼原少，夭折翻嫌汝不痴。"]},{"t":"初晴过北势湖庄舟中偶成","f":"七言律诗","c":["竛竮修竹俯双荆，几道流泉下涧鸣。","暑雨乍晴虹未落，暝烟欲起日初平。","劳形仕宦输栖隐，适趣溪山惬性情。","自把纶竿歌款乃，布帆无恙晚风轻。"]},{"t":"自南港到鸡笼道中口号","f":"五言绝句","c":["群峰势何奇，追随十馀里。","回首及斜阳，始入昏霭里。"]},{"t":"小住杨山人栖隐处题壁六首 其一","f":"七言绝句","c":["长松无数护吟楼，一派涛声枕上幽。","读罢「黄庭经」一卷，横琴再鼓「碧天秋」。"]},{"t":"小住杨山人栖隐处题壁六首 其二","f":"七言绝句","c":["雨后空山夜气清，如银月色远峰明。","翛然久坐云根上，云里幽泉自在鸣。"]},{"t":"小住杨山人栖隐处题壁六首 其三","f":"七言绝句","c":["藤床竹槛晚凉多，无数岚光四壁罗。","坐爱午晴新梦觉，穿窗时有白云过。"]},{"t":"小住杨山人栖隐处题壁六首 其四","f":"七言绝句","c":["成蹊瘦竹间寒梅，岩畔幽轩晚尚开。","别有钟声清似水，竟随归鹤入林来。"]},{"t":"小住杨山人栖隐处题壁六首 其五","f":"七言绝句","c":["抱膝长吟兴不违，山居尽日掩荆扉。","焚香默作楞严课，几缕炉烟绕翠微。"]},{"t":"小住杨山人栖隐处题壁六首 其六","f":"七言绝句","c":["盘根老树倚云烟，斗室浓阴欲暮天。","一道寒流穿石出，品茶喜有自来泉。"]},{"t":"有感","f":"七言律诗","c":["南征一剑久摩挲，杀贼曾经夜渡河。","万灶烟青军旅壮，千村地白战场多。","兵机秘密亲磨盾，狼焰消沉尽偃戈。","太息编氓蹂躏甚，不堪此日又兴波。"]},{"t":"晚过剑潭寺留题二首 其一","f":"五言律诗","c":["烟水泛苍茫，澄秋夕照光。","渔矶潭藓滑，樵担野花芳。","扫榻延居士，鸣钟礼法王。","禅关随喜处，缓步上高冈。"]},{"t":"晚过剑潭寺留题二首 其二","f":"五言律诗","c":["放眼骋吟情，吟情此际清。","诗成凭竹枕，茗熟话松棚。","鸟掠晴波远，蝉摧暮霭生。","坐来群动息，新月树端明。"]},{"t":"题林山人草堂","f":"七言律诗","c":["苍松翠柏尽成蹊，篱落周遭护碧栖。","水底波摇潭鲤戏，山坳昼永竹鸡啼。","小楼坐眺时扶槛，曲径行吟每杖藜。","我爱溪前平野外，层峦如画白云低。"]},{"t":"过北势内湖再访林山人题壁","f":"五言律诗","c":["峰回流水转，径曲小村偏。","松竹门庭外，山池几席前。","高吟蝉和韵，罢钓鹭同眠。","赏遍幽栖处，吟怀此渺然。"]},{"t":"水返脚庄雨后晚话","f":"七言律诗","c":["俗冗经旬渐次除，溪山似画对幽居。","号滩流水回潮后，撼树狂风骤雨初。","林外乍晴斜照见，岩阿欲暝积云馀。","晚来共话瓜棚下，汲井评茶兴自如。"]},{"t":"再题林山人斋壁","f":"七言律诗","c":["石遏鸣流树压崖，冈田级级似梯阶。","波纹净印秋光好，山气晴和日夕佳。","十里烟霞遮古渡，一庭松菊绕幽斋。","诗筒画本添新料，得趣时时自遣排。"]},{"t":"由南港入暖暖庄口号","f":"七言律诗","c":["瓦屋茅檐傍水滨，家家织竹自成邻。","村童夹道随看马，野老攀舆笑款人。","高下园田皆沃土，纡回溪涧自通津。","乡风到处争延致，礼貌依然古处纯。"]},{"t":"暖暖山庄夜步","f":"七言律诗","c":["历落芳藤棘作笆，护堤老木郁槎枒。","滩头作响泉添韵，露脚闻香稻著花。","隔水萤光疑鬼火，前林鸡唱有人家。","半规残月苍凉甚，兴尽方知去路赊。"]},{"t":"晚泊岭南，明朝拟过鸡笼","f":"七言律诗","c":["晚泊苍崖旅思寥，邻舟有客和吹箫。","林端兔影中秋月，岭下鸡声半夜潮。","胜概却凭毫底写，闷怀长藉酒中消。","来朝又跨征骖去，浩渺烟波第几桥。"]},{"t":"泛舟鸡笼","f":"五言律诗","c":["山势若罗城，茫然晚趣生。","水天秋一色，风月夜全清。","石乱层崖险，烟沉远屿平。","沧波时极目，渔火半江明。"]},{"t":"金包里横冈远眺","f":"五言律诗","c":["险峻金包路，篮舆不易跻。","渔家看蚁聚，鸟道听猿啼。","沙霁田沿岭，崖悬树隔溪。","明朝石门去，诘曲入云迷。"]},{"t":"金包里旅舍午霁偶成","f":"五言律诗","c":["当户群峰好，溪南雨乍晴。","岚光浮日影，林韵挟泉声。","连陌禾登陇，低檐豆压棚。","我来时八月，篱菊未含英。"]},{"t":"金包里梦觉口号","f":"五言律诗","c":["孤村深夜觉，辗转思无涯。","撼枕涛声壮，穿棂月影斜。","劳形因作客，不寝每思家。","况值中秋后，林风似晓笳。"]},{"t":"由金包里过石门","f":"七言律诗","c":["崱嶪嶕峣百怪呈，危途崭绝倍心惊。","马从密筱穿云出，人向悬崖附葛行。","匝地扬沙风料峭，漫天飞雨浪砰訇。","摇鞭陡立峰峦上，俯首群山似阅兵。"]},{"t":"暮止竹山山家","f":"五言律诗","c":["蚕丛回转处，曲折度荆笆。","马辟云中路，人居树杪家。","樵斤深谷集，水碓乱流哗。","暝色前山起，苍然绮暮霞。"]},{"t":"小坑道中","f":"五言律诗","c":["历历吹烟起，逶迤近小村。","千林苏宿露，一鸟噪朝暾。","云为穿岩滞，泉因下笕奔。","晓炊丛竹里，隐约露柴门。"]},{"t":"雨后石门道中","f":"五言律诗","c":["时雨川原遍，岩扃日未昏。","湿云填断壑，杂树隐孤村。","径为随田曲，泉因漱石喧。","几家山坞里，修竹护低垣。"]},{"t":"由石门过圭柔山道中口号","f":"古风","c":["历过峰峦又水濆，冈田万顷一溪分。","几多黄鸟栖红树，无数青山隐白云。","诗思剧怜秋色晚，客途常怯夕阳曛。","马蹄踏遍嵚?路，林外西风牧笛闻。"]},{"t":"石门道中遇雨，舆中闷卧口占","f":"五言律诗","c":["危途泥滑滑，仆马欲消魂。","雾重埋山市，涛狂撼石门。","溪桥经雨断，岭树受风喧。","彷佛闻鸡犬，欣然已近村。"]},{"t":"过阿里旁有感","f":"五言律诗","c":["鸟道盘危磴，蜗居聚小庄。","褊衷常忐忑，举步遍礌硠。","仆马连朝困，家园数月荒。","何时超坎壈，观景惬诗肠。"]},{"t":"连日为风雨所困，留宿圭柔山田家，□以遣闷","f":"七言律诗","c":["魂梦频惊动地雷，争奔万马竞喧豗。","崩崖骇浪乘潮至，撼屋狂风挟雨来。","水漫溪渠流更急，云封林壑闭难开。","连朝闷卧茅斋下，一卷新诗手腹裁。"]},{"t":"大屯顶登眺","f":"七言律诗","c":["飘渺雄观一望收，遥遥岛屿浪中浮。","看山兴适行无定，困雨心烦醉即休。","云影日移岩穴暝，涛声夜吼海门秋。","从今诗骨添雄健，胜卧元龙百尺楼。"]},{"t":"闻曾涤生大师克复江宁，诸贼歼戮殆尽，不觉狂喜","f":"七言律诗","c":["海天遥处日频瞻，喜信闻来叶梦占。","白下舆图归治化，红头仇寇尽除歼。","十年壮志冰霜励，百世勋名竹帛添。","我愿随鞭凭遣策，瞻韩何日向帷幨。"]},{"t":"江宁克复，曾涤生先生功绩伟甚。敬赋二律，以志欣仰 其一","f":"五言律诗","c":["石头城阙下，又见出降旗。","巢破林鸮殒，坛焚社鼠悲。","跳梁终胆折，读檄足心夷。","会待昌黎笔，重吟警惕诗。"]},{"t":"江宁克复，曾涤生先生功绩伟甚。敬赋二律，以志欣仰 其二","f":"五言律诗","c":["圣世绥屏障，臣穷励雪冰。","回天资大力，指日见中兴。","野寇黄巾尽，元戎白旆称。","从兹安堵卧，击壤看丰登。"]},{"t":"重登大屯山暮望","f":"七言律诗","c":["蜡屐寻幽未觉劳，几回暮望向东皋。","悬崖砌石盘云栈，断涧通流架木槽。","林外夕阳归牧笛，山中空翠落吟袍。","回途领略溪村景，谡谡松风似晚涛。"]},{"t":"步家薇臣「归赴秋闱」原韵送行","f":"七言律诗","c":["乘风指日返仙乡，炯炯文星百丈光。","折桂定跻蓬苑选，看花讵把小园忘。","翀霄力大雕方健，缓辔吟閒马不忙。","会见掇科如拾芥，功名事业两难量。"]},{"t":"三角涌山庄晚眺","f":"七言律诗","c":["戍楼络绎似连营，入谷樵歌邪许声。","涧水倒悬林杪下，山云斜掠市檐行。","岩巅落木秋容瘦，溪上层峦夕照明。","独踞胡床空翠里，双峰如揖更生情。"]},{"t":"温陵故友翁汝哲茂才物化数载，其嗣君克刚抵艋见访，盘桓旬日赴彰春试，握手依依，口号送之","f":"五言律诗","c":["具有凌云志，相期岂一衿。","佳音频洗耳，制课望关心。","学羡三冬足，交论两世深。","临歧重握手，惆怅漫成吟。"]},{"t":"题熊霭堂明府「烹茗赏菊图」小照","f":"古风","c":["我慕栗里翁，东篱自怡悦。","莫道淡逸嗜秋容，吾人由来重晚节。","我希玉川子，龙团手自烹。","浮乳数碗尘虑脱，习习清风两腋生。","坡前丛菊盏中茶，柳边花底时放衙。","海上宦游乔与梓，棠阴垂处可为家。","当日诚君维我早，相看裙屐欣同好。","流光转瞬曾几时，两鬓霜华各苍老。","感君至性方闵、曾，养志承欢登寿考。","海上羁留返棹难，家园远阻三千道。","作图明志淡而真，琴鹤居官岂潦草。","我展兹图已憬然，知君一邱常在抱。","虽然画里非家园，如此高风岂易造。","我家有园同画图，习池牛石殷花俱。","叹我年来事驰驱，笠屐未遑留须臾。","矧今即欲飞双凫，重负风月堪嗟吁。","览君此图心顿输，嗜癖尤欣还不殊。","衣冠桎梏非吾徒，何如脱簪散发相追呼。","异时勇退东篱下，与君坐对南山品茗评花兴不孤。"]},{"t":"艋川书叹 其一","f":"七言律诗","c":["古道谁云今尚留，乡闾时抱杞人忧。","平生意气吞湖海，此日奔驰叹马牛。","尽觉世情如纸薄，肯将时事等云浮。","从兹敢鄙王戎吝，和峤应推第一流。"]},{"t":"艋川书叹 其二","f":"七言律诗","c":["家计时艰两未平，劳薪尽日事非轻。","蚍蜉撼树庸何怪，鬼蜮含沙亦足惊。","忍把货泉填欲壑，遂教乐土变愁城。","归来默默蒲团坐，魔障于今愿不生。"]},{"t":"往观音山祭扫，小憩佃人家","f":"五言律诗","c":["篮舆随径曲，四顾爱晴妍。","吠犬喧村舍，飞禽集墓田。","岩阿穿汲井，竹杪散炊烟。","偃蹇茅堂下，清哦意洒然。"]},{"t":"二月二十四日游登栖云岩、观音山诸胜","f":"七言律诗","c":["依旧閒情物外心，除将静养辄登临。","石羁涧水潺湲下，径入岩松婉转深。","无数白云眠永昼，几多黄鸟闹春阴。","山亭小憩欣烹茗，又自携筇上远岑。"]},{"t":"咏金银山","f":"七言绝句","c":["长挂柴门短络篱，生成活计藉扶持。","记名何事黄兼白，富贵骄人更可嗤。"]},{"t":"读卓人孝廉「逐疫行」，走笔率成绝句 其一","f":"七言绝句","c":["嗷嗷到处听哀鸿，鹃血今尤匝地红。","召伯不来屠伯至，欲教浩劫遍瀛东。"]},{"t":"读卓人孝廉「逐疫行」，走笔率成绝句 其二","f":"七言绝句","c":["鼓吹声高独喜闻，朝朝挖眼复抽筋。","最伤炮烙过钳网，入瓮何时请此君。"]},{"t":"读卓人孝廉「逐疫行」，走笔率成绝句 其三","f":"七言绝句","c":["人命庭前等草菅，可怜十室九沉瘝。","果然一笑方包老，不是朱提不解颜。"]},{"t":"读卓人孝廉「逐疫行」，走笔率成绝句 其四","f":"七言绝句","c":["太息睚眦并餮饕，择肥而噬岂能逃。","伤心最是行途者，胸次难平拟续骚。"]},{"t":"读卓人孝廉「逐疫行」，走笔率成绝句 其五","f":"七言绝句","c":["鬼才说鬼恰相宜，走出仙才腕更奇。","一树诗歌千变化，奸邪妖魅各支离。"]},{"t":"读卓人孝廉「逐疫行」，走笔率成绝句 其六","f":"七言绝句","c":["自古灾祥感召多，蝗飞入境虎过河。","酿成厉气将何遣，逐疫还祈大吏傩。"]},{"t":"与家卓人考廉论诗","f":"七言律诗","c":["生平趣向正无偏，使典驱坟出自然。","遣兴不分唐、宋格，耽吟常见性灵篇。","呕肝莫漫追长吉，得手何须托惠连。","脱去浮词医尽俗，红尘关过始成仙。"]},{"t":"雨后郊前晚归 其一","f":"七言绝句","c":["沟渠㵐㵐遍鸣流，霭霭烟郊雨气收。","斜照忽明云散尽，长虹犹挂碧山头。"]},{"t":"雨后郊前晚归 其二","f":"七言绝句","c":["渡头芳草长萋迷，回首云山在隔溪。","夹岸修篁归道好，斑鸠啼罢蟪蛄啼。"]},{"t":"台湾保举多有遗议，作诗劝勉之","f":"七言律诗","c":["将略尝推细柳营，纯臣郭令至今称。","瘦羊博士廉犹让，大树将军广且平。","谦退由来皆叶吉，骄矜自古鲜完名。","不须击柱频挥剑，碑口传流有定评。"]},{"t":"题黄香铁先生「苜蓿集」卷后","f":"五言古诗","c":["迢迢东海外，一晤总为难。","远信经年达，佳章尽日观。","宛如闻声欬，不禁泪汎澜。","回忆居京邸，蒙公刮目看。","姻谊方卢、李，交亲等弟兄。","于今殷问讯，在昔已知名。","投辖贻三雅，传薪执一经。","何时聆玉屑，顿使鄙怀清。"]},{"t":"读吴修轩上舍诗集，题词二首 其一","f":"七言律诗","c":["渊然学问古为徒，岂藉申、韩作远图。","命笔每开生面目，论文曾下死工夫。","书真元凯耽同癖，画爱云林笑并迂。","角逐名场身欲老，照人肝胆近今无。"]},{"t":"读吴修轩上舍诗集，题词二首 其二","f":"七言律诗","c":["缅忆交游曾几时，相看鬓发渐成丝。","科名而外无馀憾，经济尤深岂独诗。","半世庾山常作赋，平生魏野不求知。","廿年叹我同蹭蹬，觅句推敲只自怡。"]},{"t":"书叹","f":"七言律诗","c":["茫茫世事可如何，一瞬流光卅载过。","座上献酬先达减，樽前谈笑少年多。","巅毛渐改伤劳悴，髀肉閒消痛抚摩。","窃赖家园风月足，勿教对酒不赓歌。"]},{"t":"观赛社有感","f":"七言绝句","c":["不堪回首数交亲，卅载流光变换频。","锣鼓喧天欢笑处，举头多是少年人。"]},{"t":"乙丑除夕团圆歌","f":"古风","c":["去年除夕时，淡北羁栖日。","只隔百里程，归难如有失。","磨蠍坐身宫，二竖重遘疾。","愁病复伶仃，苦况忍复述。","今年除夕时，团圆慰胸臆。","子侄随弟昆，长幼相领率。","?马及乘舆，轧轧北城出。","荐祖礼云周，酬神仪既毕。","旁晚乍归来，欢哗闻内室。","内室谒慈帏，致词颂安吉。","慈帏双眼枯，阿谁不能悉。","举家叩贺来，逐一名字叱。","荆人复贺予，肃然见妇德。","犹子女与儿，再拜立盈侧。","分与压岁钱，并戒毋荡佚。","阿期年差长，垂侍状笃实。","牛儿襁褓中，啜乳无休息。","以手鸣呜之，带笑睡甜黑。","花儿学步趋，攀援绕我膝。","赋性颇聪颖，青睛如点漆。","见予著宫袍，掀玩呼唧唧。","不独羡他人，兼且誇己饰。","满堂百十人，一一咸能识。","戏弟唤爷娘，喧腾不停刻。","老牛舐犊怀，岂予独见惑。","团饮坐围炉，宴酣弛酒律。","羯鼓动摧花，觞政如鬼蜮。","赌谜并猜枚，各炫所长力。","上者给朱提，次者分笔墨。","胜者足矜誇，负者亦悚恧。","男爵背「少仪」，女使诵「内则」。","啾嘈杂火爆，轰雷来莫测。","耄者犹未闻，怯者两耳塞。","大仆方逞能，小婢多逃匿。","一堂哄笑声，四座欣悦色。","和睦家之肥，何暇论饮食。","人生重团圆，半世求不得。","兹夜骨肉亲，其馀焉敢必。","大笑视荆人，此乐可云极。"]},{"t":"致新任台湾道吴桐云观察二首 其一","f":"七言律诗","c":["凤池奏罢出朝端，昼日心诚一点丹。","已见扬鞭游绝塞，曾经决策息狂澜。","衡才惟务华而实，持律能兼猛与宽。","弦诵堂幽萧牍简，皋比豸服共瞻观。"]},{"t":"致新任台湾道吴桐云观察二首 其二","f":"七言律诗","c":["胸怀叔度叹汪洋，揽辔澄清志四方。","善政几多传泐颂，仁风到处羡披扬。","早年词翰齐韩、柳，此日功名媲寇、黄。","厚泽如春台峤遍，旋看斥卤化康庄。"]},{"t":"感事","f":"七言律诗","c":["狂飓飞扬彻骨寒，阿谁发指不冲冠。","休云宁越堪鞭鞑，共道周兴肆酷残。","含怨已多闻鬼哭，择肥而噬任狼餐。","即今重见摸金尉，睡梦家家席不安。"]},{"t":"哭琼州教授印初师","f":"七言律诗","c":["京邸从游道谊长，遥闻恶耗倍心伤。","平生有累惭高足，此劫无辜更断肠。","冷宦家风性朴素，硕儒学术本循良。","可怜垂老还乡日，嚼齿含糊为国殇。"]},{"t":"遥望五指山","f":"七言律诗","c":["遥从空际列难冠，五指森森快纵观。","时压白云同扯絮，还招红日类探丸。","岚光遽隐烟初起，翠色新添雨欲残。","想到徐陵吟咏后，如椽大笔架犹宽。"]},{"t":"入鲤鱼潭番社清丈田甲","f":"五言律诗","c":["尽日似劳薪，篮舆俯仰频。","社丁言鴃舌，田甲册鱼鳞。","面目浑疑鬼，情形不类人。","除将妻子外，餍饫最相亲。"]},{"t":"书叹 其一","f":"七言律诗","c":["每从畴昔溯交亲，落落平生总率真。","至道堪师甘进履，善言可法即书绅。","幽怀已作忘情客，潜养宁为守默人。","射影频频灾害并，忏除何处问前因。"]},{"t":"书叹 其二","f":"七言律诗","c":["落拓山居志本微，形骸复自笑痴肥。","不登科目才何用，他进功名愿已违。","毕世空题司马柱，昔年常闭稚圭扉。","即今故我林泉曲，抱瓮携锄学息机。"]},{"t":"自内湾庄晚归田舍","f":"五言律诗","c":["揽辔层巅上，川原极目长。","溪流翻夕照，山色放秋光。","栖鸟喧深树，归牛下远冈。","炊烟三五缕，遥瞩认田庄。"]},{"t":"自南港内山晚归庄舍","f":"五言律诗","c":["林坳一径通，缓步踏蚕丛。","树老粘苔碧，崖阴返照红。","鸣流奔断涧，平野入遥空。","四顾皆苍莽，岚烟远近笼。"]},{"t":"闻徐大宗丞树人师讣音，集诸同人为位哭奠，馀痛萦怀，赋成哀挽三章 其一","f":"七言律诗","c":["雅量包荒万象涵，口碑自昔播东南。","志同范老忧勤见，名比温公妇孺谙。","本冀异时随马帐，不图此日痛羊昙。","他年重过西州路，掩袂难禁泪眼含。"]},{"t":"闻徐大宗丞树人师讣音，集诸同人为位哭奠，馀痛萦怀，赋成哀挽三章 其二","f":"七言律诗","c":["无从东阁复追陪，挂榻堂空渐染埃。","天上箕星神已往，人间薤露曲深哀。","门僚思泽陈诗诔，村妪衔恩奠酒杯。","一色白衣城野遍，伤心似吊武侯来。"]},{"t":"闻徐大宗丞树人师讣音，集诸同人为位哭奠，馀痛萦怀，赋成哀挽三章 其三","f":"七言律诗","c":["教化于今遍海疆，感恩知己两难忘。","因缘自结三生石，道谊分来一瓣香。","继世贻谋承燕翼，传家经术在文章。","固知霖雨多遗泽，厥后蒸蒸见克昌。"]},{"t":"防冬","f":"五言律诗","c":["初冬时节届，防守慎编氓。","纵火番围屋，鸣枪贼劫人。","村庄多「把径」，商贾勿孤身。","炮匮随修筑，家家击柝频。"]},{"t":"书叹","f":"七言律诗","c":["惹恨牵愁总不禁，秋霜两鬓渐相侵。","仰人事少垂青眼，娱己诗多写素心。","半世诗书閒岁月，百弓园墅小山林。","何时得脱维摩疾，第四禅天行始深。"]},{"t":"读刘苍石广文「半亩轩草」，题词二首 其一","f":"七言律诗","c":["弦歌此日乍闻韶，家世青田溯匪遥。","梦得诗篇多典丽，道真气宇本高标。","词源倒峡才何大，天马行空势更超。","读到风人敦厚处，知君著述富牛腰。"]},{"t":"读刘苍石广文「半亩轩草」，题词二首 其二","f":"七言律诗","c":["可掬春风煦且清，持衡待士总和平。","吟章藻思齐三凤，学业薪传在一经。","黄绢选词徵妙语，碧纱囊句护佳名。","惭予秃尽文通笔，唐突西施感愧生。"]},{"t":"游灵泉禅寺题壁","f":"七言律诗","c":["灵泉绕涧泻浪浪，匼匝峰峦护法王。","梵宇时清禅定永，空山昼静道心长。","钟鱼列案知常课，花木盈阶觉妙香。","礼罢真如随喜遍，龙团一盏润吟肠。"]},{"t":"遣怀","f":"七言律诗","c":["眼前世事等浮沤，日月双丸去若流。","问岁徒惭增马齿，图功讵肯烂羊头。","吟誇商隐千丝网，卧爱元龙百尺楼。","第一养生閒静趣，劳人利欲莫营谋。"]},{"t":"秋斋难感","f":"五言古诗","c":["感慨看丛菊，悲鸣听断鸿。","旧游追蓟北，僻处困瀛东。","债与年俱积，才随境并穷。","几多幽抑事，抒写向吟筒。","陡觉双丸急，华颠半欲丝。","问年加马齿，抚体渐鸡皮。","短鬓疏如许，孱躯弱不支。","萧斋岑寂甚，回首怅芳时。","此时犹坎壈，搔首辄长呼。","霜鬓繁频见，风怀淡欲无。","功名同嚼蜡，陇圃望还珠。","太息高堂镜，何曾尚故吾。","生计蹉跎甚，朝朝自闭门。","妻勤甘并妾，子幼却疑孙。","课仆三章约，交人一念存。","瘦藤随曳履，拨闷赖兹园。","戎马亲经后，劳薪累病躯。","毁家宁左计，报国效前驱。","我自输人吝，人咸笑我愚。","年来吟咏癖，清兴败催租。"]},{"t":"十月初三日纳侧室杜氏","f":"七言律诗","c":["堂前纤月斗新蛾，入院风轻瑞霭多。","恰喜杨稊生意茁，试将桃叶小诗哦。","宜男冀应螽斯相，之子无惭燕尔歌。","笑我乔松苍老态，逢春竟复附青萝。"]},{"t":"病中即事","f":"七言律诗","c":["卧疾连年气不扬，新愁旧事总回肠。","儿童望色时相慰，肌肉消形每自伤。","却病无方徒服药，求神有应愿随香。","于今二竖都驱遣，积善还当答上苍。"]},{"t":"夜宿清水岩僧舍","f":"五言古诗","c":["空岩秋气爽，日夕倍生凉。","石峭山弥险，霜高叶已黄。","涧寒泉激响，林密月沉光。","閒鹤巢松稳，灵猿向洞藏。","烟霞开胜境，香火辟禅堂。","老衲知持偈，游人亦裹粮。","相逢缘共结，留宿趣尤长。","饭罢同趺坐，蒲团睡味良。"]},{"t":"溪前晚步","f":"七言律诗","c":["林木萧萧石径长，四围山色渐苍茫。","帆悬日影归秋浦，鹤带钟声度晚塘。","绿叶半枯棚上豆，短条渐秃渡头杨。","秋光到眼皆诗料，吟草零星尽入囊。"]},{"t":"夜话","f":"七言律诗","c":["南斗模糊北斗辉，凝寒夜气渐侵衣。","声高鶗鴃知霜重，香减狻猊觉火微。","共话不嫌更漏永，閒居尤喜俗情稀。","除将山水琴书兴，日日潜园自掩扉。"]},{"t":"午后即事","f":"七言律诗","c":["幂地湘帘午梦成，罘罳半掩静无声。","茶烟绕榻蝉初歇，竹影当阶鹤独行。","琴抚朱弦尘虑涤，扇挥白羽薄凉生。","世间难得惟清福，似此幽閒最惬情。"]},{"t":"新庄道中口号 其一","f":"七言律诗","c":["琴剑装轻恰一肩，閒游欲学地行仙。","护田水绿溪流曲，绕屋阴浓竹树连。","争渡人喧芳草岸，唱歌樵答夕阳天。","舆中镇日无些事，睡醒看书倦复眠。"]},{"t":"秋夜书怀 其三","f":"七言律诗","c":["口里雌黄任爱憎，只求心似玉壶冰。","清高赵老琴同鹤，神骏支公马与鹰。","身外功名甘落寞，胸中意气尚崚嶒。","有时醉把吴钩舞，一片寒芒百丈腾。"]},{"t":"题徐碧岩桃溪自在图","f":"古风","c":["蕉阳之西，村庄幽沃。","云峰崔巍，烟林葱郁。","碧桃千树，绕溪之澳。","堤夹绿阴，岩悬飞瀑。","绣陌交通，古道蟠屈。","十里桑麻，声闻碌碡。","西邻可沽，村醪乍熟。","东沼可脍，游鳞潜跃。","或叟或童，为樵为牧。","斧斤丁丁，响答岩谷。","依山为庐，临水结屋。","中有幽人，志在邱壑。","案横瑶琴，架拥牙轴。","扫地焚香，侍者如玉。","清风有情，明月不速。","春日迟迟，草堂睡足。","啸傲羲皇，超尘绝俗。","优哉游哉，何荣何辱。"]},{"t":"南园即景","f":"七言律诗","c":["总为耽吟万事休，况当佳日许清游。","园花似锦春争绣，野鸟如簧晓更幽。","竹外有山皆蕴藉，柳边得水倍风流。","一池凝碧斜阳候，自把鱼竿上钓舟。"]},{"t":"新庄道中口号 其五","f":"七言古诗","c":["撑起幽窗对绿漪，波光树色两迷离。","筑楼恰好山环水，作记难传喜与悲。","欸乃声高知艇过，□□□□□□□。","溪山似此真清福，何必乘槎再访奇。"]}]};